<template>
  <TouchlessWidgetWrapper
    :title="$t('touchless_supplier_queue_title')"
    icon="mdi:account-multiple-outline"
    :error="error"
    data-test="touchless-supplier-queue"
    @retry="$emit('retry')"
  >
    <DocBitsTable
      :rows="rows"
      :columns="v2Columns"
      row-key="supplier_key"
      table-id="touchless_supplier_queue"
      :features="v2TableFeatures"
      :pagination="v2PaginationState"
      :loading="loading"
      table-height="55vh"
      no-data-label="no_data_found"
      @update:sorting="handleV2Sort"
      @update:pagination="handleV2Pagination"
      @row-click="handleRowClick"
    >
      <!--
        DOCB-14333. The unattributed bucket arrives with `unknown` in BOTH the
        key and the name column, and this table printed it verbatim — a row
        that reads like a broken record rather than like the finding it is.
      -->
      <template #body-cell-supplier_name="{ row }">
        <span data-test="touchless-supplier-row-name">{{
          supplierLabel(row)
        }}</span>
      </template>
      <template #body-cell-pure_pct="{ row }">
        <!-- No colour when there is no rate: red would read as "failing" for a
             supplier that has simply not finished any document yet. -->
        <span :class="pctClass(row.pure_pct)">
          {{ formatPct(row.pure_pct) }}
        </span>
      </template>
      <template #body-cell-root_cause_domain="{ row }">
        <span>{{
          row.root_cause_domain
            ? translateEnum('touchless_domain_', row.root_cause_domain)
            : '—'
        }}</span>
      </template>
      <template #body-cell-expected_lift_pct="{ row }">
        <span>{{ formatPct(row.expected_lift_pct) }}</span>
      </template>
      <template #body-cell-confidence="{ row }">
        <q-chip
          dense
          square
          :color="confidenceColor(row.confidence)"
          text-color="white"
          :label="confidenceLabel(row.confidence)"
        />
      </template>
      <template #body-cell-status="{ row }">
        <q-chip
          dense
          square
          outline
          :label="translateEnum('touchless_status_', row.status)"
        />
      </template>
    </DocBitsTable>
  </TouchlessWidgetWrapper>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { DocBitsTable } from 'src/components/Table';
import type {
  UnifiedTableColumn,
  SortEventPayload,
  PaginationChangePayload,
} from 'src/components/Table';
import TouchlessWidgetWrapper from './TouchlessWidgetWrapper.vue';
import type { TouchlessSupplierOpportunity } from 'src/services/analytics/TouchlessService';
import type { TouchlessPagination } from 'src/store/touchless-intelligence.store';
import {
  confidenceBand,
  confidenceColor as confidenceColorFor,
  formatTouchlessPct,
  NO_VALUE,
} from 'src/utils/touchless-format';
import { isUnresolvedSupplier } from 'src/utils/touchless-supplier';

/**
 * Suppliers ranked by recoverable loss — the work queue behind the headline
 * rate. Server-paged exactly like `ImportLogs.vue`: the parent owns the
 * pagination state and refetches; this component only translates the table's
 * events into `sort` / `page` emits.
 */
export default defineComponent({
  name: 'SupplierQueueTable',

  components: { DocBitsTable, TouchlessWidgetWrapper },

  props: {
    rows: {
      type: Array as PropType<TouchlessSupplierOpportunity[]>,
      default: () => [],
    },
    pagination: {
      type: Object as PropType<TouchlessPagination>,
      required: true,
    },
    totalRows: { type: Number, default: 0 },
    loading: { type: Boolean, default: false },
    error: { type: Boolean, default: false },
    /** Org target in percent, used to colour the per-supplier rate. */
    target: { type: Number, default: 70 },
  },

  emits: ['sort', 'page', 'select-supplier', 'retry'],

  computed: {
    v2Columns(): UnifiedTableColumn[] {
      return [
        {
          name: 'supplier_name',
          label: this.$t('supplier') as string,
          field: 'supplier_name',
          align: 'left',
          sortable: true,
        },
        {
          name: 'volume',
          label: this.$t('touchless_col_volume') as string,
          field: 'volume',
          align: 'right',
          sortable: true,
        },
        {
          name: 'pure_pct',
          label: this.$t('touchless_col_pure_rate') as string,
          field: 'pure_pct',
          align: 'right',
          sortable: true,
        },
        {
          name: 'lost_docs',
          label: this.$t('touchless_col_lost_docs') as string,
          field: 'lost_docs',
          align: 'right',
          sortable: true,
        },
        {
          name: 'root_cause_domain',
          label: this.$t('touchless_col_root_cause') as string,
          field: 'root_cause_domain',
          align: 'left',
          sortable: true,
        },
        {
          name: 'recoverable_docs',
          label: this.$t('touchless_col_recoverable') as string,
          field: 'recoverable_docs',
          align: 'right',
          sortable: true,
        },
        {
          name: 'expected_lift_pct',
          label: this.$t('touchless_col_expected_lift') as string,
          field: 'expected_lift_pct',
          align: 'right',
          sortable: true,
        },
        {
          name: 'confidence',
          label: this.$t('touchless_col_confidence') as string,
          field: 'confidence',
          align: 'left',
          sortable: true,
        },
        {
          name: 'status',
          label: this.$t('status') as string,
          field: 'status',
          align: 'left',
          sortable: true,
        },
      ];
    },

    v2TableFeatures() {
      return {
        sorting: true,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: false,
        resizable: true,
        pagination: true,
        columnReorder: false,
      };
    },

    v2PaginationState() {
      return {
        sortBy: this.pagination.sortBy || null,
        descending: this.pagination.descending,
        page: this.pagination.page,
        rowsPerPage: this.pagination.rowsPerPage,
        rowsNumber: this.totalRows,
      };
    },
  },

  methods: {
    /**
     * The supplier's name, or the explanatory label for the bucket nobody
     * could attribute (DOCB-14333). Never the raw key.
     */
    supplierLabel(row: Record<string, unknown>): string {
      const name =
        typeof row?.supplier_name === 'string' ? row.supplier_name : '';
      if (!isUnresolvedSupplier(row?.supplier_key, name)) {
        return name || String(row?.supplier_key ?? '');
      }
      const lost = Number(row?.lost_docs);
      return Number.isFinite(lost) && lost > 0
        ? (this.$t('touchless_supplier_unidentified_count', {
            count: Math.floor(lost),
          }) as string)
        : (this.$t('touchless_supplier_unidentified') as string);
    },

    formatPct(value: unknown): string {
      return formatTouchlessPct(value);
    },

    /**
     * Green above target, red below, NO colour when there is no rate.
     * Red on a null would read as "failing" for a supplier that has simply
     * not finished a document yet.
     */
    pctClass(value: unknown): string {
      if (typeof value !== 'number' || !Number.isFinite(value)) return '';
      return value >= this.target ? 'text-positive' : 'text-negative';
    },

    /** i18n label for an enum value, falling back to the raw backend value. */
    translateEnum(prefix: string, value: string): string {
      if (!value) return '';
      const key = `${prefix}${String(value).toLowerCase()}`;
      const translated = this.$t(key) as string;
      return translated === key ? value : translated;
    },

    confidenceColor(confidence: unknown): string {
      return confidenceColorFor(confidence);
    },

    /** The chip's text: a translated band, or an em dash when unknown. */
    confidenceLabel(confidence: unknown): string {
      const band = confidenceBand(confidence);
      if (band === null) return NO_VALUE;
      return this.translateEnum('touchless_confidence_', band);
    },

    handleV2Sort(payload: SortEventPayload): void {
      if (payload.direction === null) {
        this.$emit('sort', {
          sortBy: 'recoverable_docs',
          descending: true,
        });
        return;
      }
      this.$emit('sort', {
        sortBy: payload.column,
        descending: payload.direction === 'desc',
      });
    },

    handleV2Pagination(payload: PaginationChangePayload): void {
      this.$emit('page', {
        page: payload.page,
        rowsPerPage: payload.rowsPerPage,
      });
    },

    handleRowClick(payload: { row: TouchlessSupplierOpportunity }): void {
      if (!payload?.row?.supplier_key) return;
      this.$emit('select-supplier', payload.row.supplier_key);
    },
  },
});
</script>
