                  class="text-center q-pa-lg text-grey"
                  style="
                    min-height: 125px;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                  "
                >
                  {{ $t('no_data_found') }}
                </div>
              </div>
            </div>
          </q-card>
        </div>
      </div>
      <q-inner-loading :showing="processing">
        <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
      </q-inner-loading>
    </div>
  </q-page>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent } from 'vue';
import { mapState } from 'pinia';
import {
  useSettingStore,
  useDropdownStore,
  useDashboardStore,
} from 'src/store/main';
import {
  amount_format_setting,
  analytics_dashboard_setting,
} from 'src/constants';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import { isUserAdmin } from 'src/utils/UserDetails';

import MessageBanner from 'src/components/MessageBanner.vue';

import { documentFlowDataService } from 'src/services';
import DocumentFlowCard from './AnalyticsFlowCard.vue';
import AverageTimeChart from './AverageTimeChart.vue';
import ServiceTimeChart from './ServiceTimeChart.vue';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import TouchlessIntelligencePanel from 'src/pages/TouchlessIntelligence/TouchlessIntelligencePanel.vue';
import { useTouchlessAccess } from 'src/composables/useTouchlessAccess';
import { useTouchlessIntelligenceStore } from 'src/store/touchless-intelligence.store';

import { LocalStorage } from 'quasar';

import { getOrgId } from 'src/utils/organization/org_id_helper';
import { UserOrg } from 'src/utils/organization/user_organization';
import csvExportUtil from 'src/utils/csvExportUtil';
import dateUtils from 'src/utils/date';

import TimeFilter from './AnalyticsTimeFilter.vue';
import {
  formatServiceLabel,
  formatAmount,
  normalizeServiceName,
  clearCaches,
  resolveDocFlowIcon,
  compareFlowCards,
} from './analyticsUtils';

// Constant for "All" filter sentinel value
const ALL_FILTER_VALUE = '__ALL__';

// Separate order maps per flow type (modules/status/user never mix)
const MODULE_ORDER = new Map<string, number>([
  ['IMPORT', 0],
  ['SPLITTER', 1],
  ['PDF_SEARCHABLE', 2],
  ['OCR', 3],
  ['CLASSIFY', 4],
  ['BARCODE_EXTRACTION', 5],
  ['FIELDS_EXTRACTION', 6],
  ['TABLE_EXTRACTION', 7],
  ['TR_OCR', 8],
  ['METADATA_POPULATOR', 9],
  ['TRANSFORMER', 10],
  ['LOOKUP_DATA', 11],
  ['PO_MATCHING', 12],
  ['VALIDATOR', 13],
  ['SCRIPT', 14],
  ['WORKFLOW_EXECUTION', 15],
  ['EXPORT', 16],
]);

const STATUS_ORDER = new Map<string, number>([
  // Happy path: intake → validation → approval → export
  ['STATUS_NEW', 0],
  ['STATUS_RUNNING', 1],
  ['STATUS_VALIDATING', 2],
  ['STATUS_READY_FOR_VALIDATION', 3],
  ['STATUS_VALIDATED_PENDING_APPROVAL', 4],
  ['STATUS_APPROVED_PENDING_SECOND_APPROVAL', 5],
  ['STATUS_VALIDATED_PENDING_EXPORT', 6],
  ['STATUS_PENDING_WATCHER_EXPORT', 7],
  ['STATUS_EXPORTING', 8],
  // Exception statuses, grouped at the end
  ['STATUS_ERROR', 9],
  ['STATUS_RESTART_EXPORT', 10],
  ['STATUS_EXPORT_ERROR', 11],
  ['STATUS_RESTARTED', 12],
]);

const USER_ORDER = new Map<string, number>([
  ['USER_VALIDATION_WAITING', 0],
  ['USER_VALIDATION', 1],
  ['USER_PO_VALIDATION', 2],
  ['USER_APPROVAL_WAITING', 3],
  ['USER_APPROVAL', 4],
  ['USER_SECOND_APPROVAL_WAITING', 5],
  ['USER_SECOND_APPROVAL', 6],
]);

// Per-tab filter state interface
/**
 * The three ANALYTICS flow types. Every computed that reads flow data keys off
 * this union, and Touchless is deliberately NOT part of it: it is a sibling
 * report with its own store and its own endpoints, not a fourth flow type over
 * the same `flow_data`.
 */
type AnalyticsFlowType = 'modules' | 'user' | 'status';

/** Query parameter that makes the active tab shareable and restorable. */
const TAB_QUERY_KEY = 'tab';

/** What the tab bar can show — the flow types plus the Touchless report. */
type AnalyticsTabValue = AnalyticsFlowType | 'touchless';

interface TabFilterState {
  selectedSubOrg: string[];
  prevSelectedSubOrg: string[];
  selectedDocType: string[];
  prevSelectedDocType: string[];
  selectedSupplier: string[];
  prevSelectedSupplier: string[];
  selectedAssignedGroup: string[];
  prevSelectedAssignedGroup: string[];
  selectedSteps: string[];
  prevSelectedSteps: string[];
  documentSearch: string;
  documentSearchInput: string;
  chartGroupBy: string;
  timeChartGroupBy: string;
  hiddenDocumentIds: Set<string>;
  selectedServices: Set<string>;
  topDocumentsSortOrder: string;
}

function createDefaultTabFilterState(): TabFilterState {
  return {
    selectedSubOrg: [getOrgId()],
    prevSelectedSubOrg: [getOrgId()],
    selectedDocType: [ALL_FILTER_VALUE],
    prevSelectedDocType: [ALL_FILTER_VALUE],
    selectedSupplier: [ALL_FILTER_VALUE],
    prevSelectedSupplier: [ALL_FILTER_VALUE],
    selectedAssignedGroup: [ALL_FILTER_VALUE],
    prevSelectedAssignedGroup: [ALL_FILTER_VALUE],
    selectedSteps: [ALL_FILTER_VALUE],
    prevSelectedSteps: [ALL_FILTER_VALUE],
    documentSearch: '',
    documentSearchInput: '',
    chartGroupBy: 'flow',
    timeChartGroupBy: 'flow',
    hiddenDocumentIds: new Set<string>(),
    selectedServices: new Set<string>(),
    topDocumentsSortOrder: 'desc',
  };
}

function getCardOrder(service: string): number {
  return (
    MODULE_ORDER.get(service) ??
    STATUS_ORDER.get(service) ??
    USER_ORDER.get(service) ??
    999
  );
}

// Helper function to format date
function formatDate(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

// Calculate initial dates
function getInitialDates() {
  const today = new Date();
  const ninetyDaysAgo = new Date(today);
  ninetyDaysAgo.setDate(today.getDate() - 90);
  return {
    start_date: formatDate(ninetyDaysAgo),
    end_date: formatDate(today),
  };
}

export default defineComponent({
  components: {
    SubHeader,
    DocumentFlowCard,
    TimeFilter,
    AverageTimeChart,
    ServiceTimeChart,
    MessageBanner,
    DocBitsTable,
    TouchlessIntelligencePanel,
  },
  mixins: [dateUtils],

  setup() {
    // Single source of truth for whether this org may see Touchless at all.
    // DOCB-14282: one gate for this whole page. `useTouchlessAccess` now
    // delegates to `canAccessAnalytics`, so the Touchless tab, the page banner
    // and the bootstrap guard below are the SAME decision — they cannot drift
    // apart the way the three hand-written copies of `flag && is_admin` on
    // this page did.
    const {
      accessGranted,
      accessDenied,
      settingsReady,
      isAdmin,
      ensureSettingsLoaded,
    } = useTouchlessAccess();
    // Needed to invalidate in-flight Touchless requests when access is revoked.
    const touchlessStore = useTouchlessIntelligenceStore();
    return {
      touchlessAccessGranted: accessGranted,
      // The banner's condition and `analyticsAccessReady` below are the same
      // computed on purpose — see the comment on `analyticsAccessReady`.
      analyticsAccessDenied: accessDenied,
      analyticsAccessGranted: accessGranted,
      preferencesReady: settingsReady,
      reactiveIsAdmin: isAdmin,
      ensureSettings: ensureSettingsLoaded,
      touchlessStore,
    };
  },

  props: {
    doc_id: {
      type: String,
      default: '',
    },
  },
  data() {
    const initialDates = getInitialDates();
    return {
      cardsPerRow: 5,
      resizeObserver: null as ResizeObserver | null,
      currentOrg: getOrgId(),
      wordfilter: [
        { ocr_by_google: 'OCR' },
        { 'infor-idm-cloud_export': 'Infor IDM Export' },
        { 'infor-ln-cloud_export': 'Infor LN Export' },
      ] as Record<string, string>[],
      analytics_dashboard_setting,
      start_date: initialDates.start_date,
      end_date: initialDates.end_date,
      selectedSubOrg: [getOrgId()] as string[],
      selectedDocType: [ALL_FILTER_VALUE] as string[],
      selectedSupplier: [ALL_FILTER_VALUE] as string[],
      // Track previous values to detect what was clicked
      prevSelectedDocType: [ALL_FILTER_VALUE] as string[],
      prevSelectedSupplier: [ALL_FILTER_VALUE] as string[],
      selectedAssignedGroup: [ALL_FILTER_VALUE] as string[],
      prevSelectedAssignedGroup: [ALL_FILTER_VALUE] as string[],
      prevSelectedSubOrg: [getOrgId()] as string[],
      selectedSteps: [ALL_FILTER_VALUE] as string[],
      prevSelectedSteps: [ALL_FILTER_VALUE] as string[],
      // Stays a real flow type even while the Touchless tab is shown, so every
      // flow-data computed keeps operating on data that exists. Only the tab
      // indicator moves.
      selectedFlowType: 'status' as AnalyticsFlowType,
      displayFlowType: 'status' as AnalyticsTabValue,
      // Analytics bootstrap runs once, when access becomes known.
      analyticsInitialized: false,
      // Ownership token for in-flight analytics requests.
      analyticsRequestGeneration: 0,
      // Restricts per-doc-total metrics (Workflow time, grouped chart by
      // sub_org/doc_type/supplier/group, time-trend series) to docs that
      // reached a fully-exported status. Default ON = production benchmark;
      // OFF = debug mode, includes partial-pipeline docs.
      // Per-step card averages are NOT affected — they self-clean because a
      // FlowLog row is only written when a doc leaves the step.
      completedOnly: true as boolean,
      topDocumentsSortOrder: 'desc' as 'asc' | 'desc',
      hiddenDocumentIds: new Set<string>(),
      // Per-tab filter state storage
      _tabFilterStates: new Map<string, TabFilterState>(),
      _skipFlowTypeWatcher: false,
      flow_data: null as any,
      system_avg_data: null as any,
      selectedServices: new Set<string>(),
      processing: false,
      is_admin: isUserAdmin(),
      documentSearch: '' as string,
      documentSearchInput: '' as string, // Performance: separate input for debouncing
      chartGroupBy: 'flow' as
        | 'flow'
        | 'sub_org'
        | 'doc_type'
        | 'supplier'
        | 'assigned_group',
      timeChartGroupBy: 'flow' as
        | 'flow'
        | 'sub_org'
        | 'doc_type'
        | 'supplier'
        | 'assigned_group',
      tablePagination: {
        sortBy: null as string | null,
        descending: false,
        page: 1,
        rowsPerPage: 20,
        rowsNumber: 0,
      },
      hiddenColumnNames: [] as string[],
      draggedColumnName: null as string | null,
      isDraggingToHide: false,
      isDraggingToRestore: false,
      dragSource: null as 'table' | 'hidden' | null,
      showDocbitsAverage: true,
      // Performance: debounce timers for filter changes
      _filterDebounceTimer: null as ReturnType<typeof setTimeout> | null,
      _documentVisibilityDebounceTimer: null as ReturnType<
        typeof setTimeout
      > | null,
      // Performance: batch service selection changes to avoid multiple recomputations
      _serviceSelectionDebounceTimer: null as ReturnType<
        typeof setTimeout
      > | null,
      _pendingServiceSelection: null as Set<string> | null,
      // Performance: cached _allStats to avoid array spreading on every access
      _cachedAllStats: null as any[] | null,
      _cachedAllStatsVersion: 0 as number,
      // Performance: Track flow_data version for cache invalidation
      _flowDataVersion: 0 as number,
      // Performance: Cached label lookup maps for grouping operations
      _cachedSubOrgLabelMapForGrouping: null as Map<string, string> | null,
      _cachedDocTypeLabelMapForGrouping: null as Map<string, string> | null,
      // Performance: Cache for _statsFilteredByFlowAndServices to avoid redundant filtering
      _cachedStatsFilteredByServices: null as any[] | null,
      _cachedStatsFilteredByServicesKey: '' as string,
      // Performance: Cache for _statsFilteredByFlowAndServicesIncludingHidden
      _cachedStatsFilteredByServicesIncludingHidden: null as any[] | null,
      _cachedStatsFilteredByServicesIncludingHiddenKey: '' as string,
      // Top documents pagination
      topDocsPageSizeOptions: [
        { label: '10', value: 10 },
        { label: '20', value: 20 },
        { label: '50', value: 50 },
      ],
      topDocsPageSize: 10 as number,
      topDocsCurrentPage: 1 as number,
      topDocsPageInput: 1 as number,
    };
  },
  computed: {
    ...mapState(useSettingStore, ['user_settings']),
    ...mapState(useDashboardStore, ['quickFilterMap']),
    ...mapState(useDropdownStore, [
      'active_doc_type_list',
      'subOrgList',
      'supplierNameMap',
      'groupsMap',
    ]),

    orgName(): string {
      // Try user_details.org_name first
      const userDetails = LocalStorage.getItem('user_details') as any;
      if (userDetails?.org_name?.trim()) {
        return userDetails.org_name.trim();
      }
      // Fall back to organizations from session cache
      const organizations = UserOrg.get();
      if (organizations?.length) {
        const defaultOrg = organizations.find((org: any) => org.is_default);
        return defaultOrg?.name?.trim() || organizations[0]?.name?.trim() || '';
      }
      return '';
    },

    defaultOption(): { label: string; value: string } {
      return {
        label: this.orgName ? `${this.orgName} (CROSS)` : 'CROSS',
        value: getOrgId(),
      };
    },

    filterSubOrgsList(): Array<{ label: string; value: string }> {
      const currentOrgId = getOrgId();
      // Filter out the current org and deduplicate by value to prevent duplicate checkboxes
      const seenValues = new Set<string>([currentOrgId]); // Start with currentOrgId to exclude it
      const filteredSubOrgs = (this.subOrgList || []).filter((item: any) => {
        if (seenValues.has(item.value)) {
          return false; // Skip duplicates
        }
        seenValues.add(item.value);
        return true;
      });
      return [this.defaultOption, ...filteredSubOrgs];
    },

    filterDocTypeList(): Array<{ label: string; value: string }> {
      return [
        { label: this.$t('all'), value: ALL_FILTER_VALUE },
        ...(this.active_doc_type_list || []).filter(
          (item: any) =>
            item.value !== null &&
            item.value !== ALL_FILTER_VALUE &&
            item.label?.toLowerCase() !== 'all',
        ),
      ];
    },

    flowTypeOptions(): Array<{ label: string; value: AnalyticsTabValue }> {
      const options: Array<{ label: string; value: AnalyticsTabValue }> = [];
      // Second gate on top of the page's own ANALYTICS_DASHBOARD + admin check:
      // without the org's TOUCHLESS_INTELLIGENCE flag the tab is not rendered at
      // all, so there is nothing to click and nothing to request.
      if (this.touchlessAccessGranted) {
        options.push({
          label: this.$t('touchless_intelligence'),
          value: 'touchless',
        });
      }
      // Touchless is intentionally the cheap landing tab. The flow-data request
      // behind Status is the slowest part of the dashboard bootstrap, so keep
      // it last and defer that request until somebody actually opens it.
      options.push(
        { label: this.$t('filter_processing'), value: 'modules' },
        { label: this.$t('user_interaction'), value: 'user' },
        { label: this.$t('status'), value: 'status' },
      );
      return options;
    },

    /** True while the Touchless report owns the content area. */
    isTouchlessTab(): boolean {
      return this.displayFlowType === 'touchless';
    },

    /**
     * Whether this page may load its own data yet. Preferences arrive after
     * mount on a cold direct load, so this is the signal the bootstrap waits
     * for rather than a one-shot check in mounted().
     */
    analyticsAccessReady(): boolean {
      // DOCB-14282: this and the MessageBanner's `v-if` are now literally the
      // same computed (`analyticsAccessGranted` / `analyticsAccessDenied`,
      // both from `useTouchlessAccess` -> `canAccessAnalytics`). They MUST
      // stay that way: when they were two hand-written conditions they
      // disagreed on a stored '0' — the banner hid, the page rendered, and
      // the bootstrap never ran, leaving an empty dashboard with no
      // explanation. If you change one, you are changing the other; there is
      // no longer a second place to edit.
      return this.analyticsAccessGranted;
    },

    chartGroupByOptions(): Array<{
      label: string;
      value: 'flow' | 'sub_org' | 'doc_type' | 'supplier' | 'assigned_group';
    }> {
      const options: Array<{
        label: string;
        value: 'flow' | 'sub_org' | 'doc_type' | 'supplier' | 'assigned_group';
      }> = [
        { label: this.$t('flow'), value: 'flow' },
        { label: this.$t('sub_org'), value: 'sub_org' },
        { label: this.$t('document_type'), value: 'doc_type' },
        { label: this.$t('supplier'), value: 'supplier' },
      ];
      // Add assigned group option for status and user flow types
      if (
        this.selectedFlowType === 'status' ||
        this.selectedFlowType === 'user'
      ) {
        options.push({ label: this.$t('group'), value: 'assigned_group' });
      }
      return options;
    },

    topDocumentsLimitOptions(): Array<{ label: string; value: number }> {
      return [
        { label: '5', value: 5 },
        { label: '10', value: 10 },
        { label: '25', value: 25 },
        { label: '50', value: 50 },
        { label: this.$t('all'), value: 0 },
      ];
    },

    filterSupplierList(): Array<{ label: string; value: string }> {
      const stats = this._allStats;
      if (stats.length === 0) {
        return [{ label: this.$t('all'), value: ALL_FILTER_VALUE }];
      }

      // Get unique supplier_ids from the data and resolve names via store map
      const supplierMap = this.supplierNameMap as Map<string, string>;
      const seen = new Set<string>();
      const supplierOptions: Array<{ label: string; value: string }> = [];

      for (const item of stats) {
        const supplierId = item.supplier_id;
        if (supplierId && !seen.has(supplierId)) {
          seen.add(supplierId);
          const name = supplierMap.get(supplierId) || supplierId;
          supplierOptions.push({ label: name, value: supplierId });
        }
      }

      supplierOptions.sort((a, b) => a.label.localeCompare(b.label));

      return [
        { label: this.$t('all'), value: ALL_FILTER_VALUE },
        ...supplierOptions,
      ];
    },

    // Display value for Sub Org multi-select
    getSubOrgDisplayValue(): string {
      const currentOrgId = getOrgId();
      if (
        this.selectedSubOrg.length === 1 &&
        this.selectedSubOrg[0] === currentOrgId
      ) {
        return this.orgName ? `${this.orgName} (CROSS)` : 'CROSS';
      }
      if (this.selectedSubOrg.length === 1) {
        const option = this.filterSubOrgsList.find(
          (opt) => opt.value === this.selectedSubOrg[0],
        );
        return option?.label || '';
      }
      return `${this.selectedSubOrg.length} ${this.$t('selected')}`;
    },

    // Display value for Doc Type multi-select
    getDocTypeDisplayValue(): string {
      if (this.selectedDocType.includes(ALL_FILTER_VALUE)) {
        return this.$t('all');
      }
      if (this.selectedDocType.length === 1) {
        const option = this.filterDocTypeList.find(
          (opt) => opt.value === this.selectedDocType[0],
        );
        return option?.label || '';
      }
      return `${this.selectedDocType.length} ${this.$t('selected')}`;
    },

    // Display value for Supplier multi-select
    getSupplierDisplayValue(): string {
      if (this.selectedSupplier.includes(ALL_FILTER_VALUE)) {
        return this.$t('all');
      }
      if (this.selectedSupplier.length === 1) {
        const option = this.filterSupplierList.find(
          (opt) => opt.value === this.selectedSupplier[0],
        );
        return option?.label || '';
      }
      return `${this.selectedSupplier.length} ${this.$t('selected')}`;
    },

    // Assigned Group filter list - available for status and user flow types
    filterAssignedGroupList(): Array<{ label: string; value: string }> {
      const stats = this._allStats;
      if (stats.length === 0) {
        return [{ label: this.$t('all'), value: ALL_FILTER_VALUE }];
      }

      const groupsMap = this.groupsMap as Map<string, any>;
      const seen = new Set<string>();
      const groupOptions: Array<{ label: string; value: string }> = [];

      for (const item of stats) {
        const gid = item.assigned_group_id;
        if (gid && !seen.has(gid)) {
          seen.add(gid);
          const group = groupsMap.get(gid);
          groupOptions.push({
            label: group?.name || gid,
            value: gid,
          });
        }
      }

      groupOptions.sort((a, b) => a.label.localeCompare(b.label));

      return [
        { label: this.$t('all'), value: ALL_FILTER_VALUE },
        ...groupOptions,
      ];
    },

    // Display value for Assigned Group multi-select
    getAssignedGroupDisplayValue(): string {
      if (this.selectedAssignedGroup.includes(ALL_FILTER_VALUE)) {
        return this.$t('all');
      }
      if (this.selectedAssignedGroup.length === 1) {
        const option = this.filterAssignedGroupList.find(
          (opt) => opt.value === this.selectedAssignedGroup[0],
        );
        return option?.label || '';
      }
      return `${this.selectedAssignedGroup.length} ${this.$t('selected')}`;
    },

    // Elements actually rendered as flow cards. The Flow Steps dropdown
    // (selectedSteps) hides cards whose base status isn't selected. Distinct
    // from card click which only greys-out via selectedServices, never hides.
    visibleFlowElements(): any[] {
      if (
        this.selectedSteps.includes(ALL_FILTER_VALUE) ||
        this.selectedSteps.length === 0
      ) {
        return this.elements;
      }
      const allowedBases = new Set(this.selectedSteps);
      return (this.elements as any[]).filter((el) => {
        const baseName = el.name.includes('::')
          ? el.name.split('::')[0]
          : el.name;
        return allowedBases.has(baseName);
      });
    },

    // Steps filter list - mirrors the flow step cards with same translation.
    // Deduplicates per base status so the dropdown shows "New" / "Running"
    // once instead of one entry per occurrence ("1. New", "2. New", ...).
    filterStepsList(): Array<{ label: string; value: string }> {
      const seen = new Set<string>();
      const stepOptions: Array<{ label: string; value: string }> = [];
      for (const el of this.elements as any[]) {
        const baseName = el.name.includes('::')
          ? el.name.split('::')[0]
          : el.name;
        if (seen.has(baseName)) continue;
        seen.add(baseName);
        const baseLabel = (el.label as string).replace(/^\d+\.\s*/, '');
        stepOptions.push({ label: baseLabel, value: baseName });
      }

      return [
        { label: this.$t('all'), value: ALL_FILTER_VALUE },
        ...stepOptions,
      ];
    },

    // Display value for Steps multi-select
    getStepsDisplayValue(): string {
      if (this.selectedSteps.includes(ALL_FILTER_VALUE)) {
        return this.$t('all');
      }
      if (this.selectedSteps.length === 1) {
        const option = this.filterStepsList.find(
          (opt) => opt.value === this.selectedSteps[0],
        );
        return option?.label || '';
      }
      return `${this.selectedSteps.length} ${this.$t('selected')}`;
    },

    // Performance: Generate cache key for base filter state
    _baseFilterCacheKey(): string {
      const currentOrgId = getOrgId();
      const byFlowType = this.flow_data?.by_flow_type;
      const totalStats = byFlowType
        ? (byFlowType.modules?.length || 0) +
          (byFlowType.user?.length || 0) +
          (byFlowType.status?.length || 0)
        : 0;
      return [
        totalStats,
        this.selectedSubOrg.join(','),
        this.selectedDocType.join(','),
        this.selectedSupplier.join(','),
        this.selectedAssignedGroup.join(','),
        this.documentSearch?.trim() || '',
        currentOrgId,
        this.completedOnly ? '1' : '0',
      ].join('|');
    },

    // Performance: Get stats pre-filtered by flow type from backend (O(1) lookup)
    _statsForCurrentFlowType(): any[] {
      const byFlowType = this.flow_data?.by_flow_type;
      if (!byFlowType) return [];
      return byFlowType[this.selectedFlowType] || [];
    },

    // Get all stats across all flow types (used for filter dropdowns)
    // Performance: Returns cached array reference when flow_data hasn't changed
    _allStats(): any[] {
      const byFlowType = this.flow_data?.by_flow_type;
      if (!byFlowType) return [];

      // Performance: Check if we can return cached result
      // Cache invalidation happens when flow_data changes (tracked via _flowDataVersion)
      const currentVersion = this._flowDataVersion;
      if (
        this._cachedAllStats !== null &&
        this._cachedAllStatsVersion === currentVersion
      ) {
        return this._cachedAllStats;
      }

      // Build and cache the combined array from all flow types
      const modules = byFlowType.modules || [];
      const user = byFlowType.user || [];
      const status = byFlowType.status || [];

      // Performance: Use concat instead of spread for better performance with large arrays
      const result = modules.concat(user, status);

      this._cachedAllStats = result;
      this._cachedAllStatsVersion = currentVersion;
      return result;
    },

    // Base filtered service stats used by multiple computed properties
    // Base stats without hidden document filter (used for top documents list display)
    // Performance: Uses Sets for O(1) lookups instead of array.includes() which is O(n)
    baseFilteredServiceStatsIncludingHidden(): any[] {
      // Performance: Start with flow-type-filtered data (pre-indexed from backend)
      const stats = this._statsForCurrentFlowType;
      if (stats.length === 0) return [];

      const currentOrgId = getOrgId();

      // Performance: Convert arrays to Sets for O(1) lookup
      const selectedSubOrgSet = new Set(this.selectedSubOrg);
      const selectedDocTypeSet = new Set(this.selectedDocType);
      const selectedSupplierSet = new Set(this.selectedSupplier);
      const selectedAssignedGroupSet = new Set(this.selectedAssignedGroup);

      // Determine filter states once
      const isSubOrgAllSelected =
        this.selectedSubOrg.length === 1 &&
        this.selectedSubOrg[0] === currentOrgId;
      const isDocTypeAllSelected = selectedDocTypeSet.has(ALL_FILTER_VALUE);
      const isSupplierAllSelected = selectedSupplierSet.has(ALL_FILTER_VALUE);
      const isAssignedGroupAllSelected =
        selectedAssignedGroupSet.has(ALL_FILTER_VALUE);
      const searchTerm = this.documentSearch?.trim().toLowerCase() || '';
      const hasSearch = searchTerm.length > 0;

      // "Completed only" — applied at the base alongside the other filters so
      // every downstream metric (per-step cards, top docs, charts, time
      // series) inherits it consistently. Backend pre-computes the id set
      // using DOC_FULLY_EXPORTED_STATUSES.
      const completedOnly = this.completedOnly;
      const completed = this.completedDocIds;

      // Performance: Single pass filter instead of multiple chained filters
      return stats.filter((item: any) => {
        // Filter by sub_org
        if (!isSubOrgAllSelected && this.selectedSubOrg.length > 0) {
          if (!selectedSubOrgSet.has(item.sub_org_id)) return false;
        }

        // Filter by doc_type
        if (
          !isDocTypeAllSelected &&
          this.selectedDocType.length > 0 &&
          item.doc_type
        ) {
          if (!selectedDocTypeSet.has(item.doc_type)) return false;
        }

        // Filter by supplier (selectedSupplier now contains supplier_ids)
        if (!isSupplierAllSelected && this.selectedSupplier.length > 0) {
          if (!selectedSupplierSet.has(item.supplier_id)) return false;
        }

        // Filter by assigned group
        if (
          !isAssignedGroupAllSelected &&
          this.selectedAssignedGroup.length > 0
        ) {
          if (!selectedAssignedGroupSet.has(item.assigned_group_id))
            return false;
        }

        // Filter by search term
        if (hasSearch) {
          const docId = (item.document_id || '').toLowerCase();
          const filename = (item.filename || '').toLowerCase();
          if (!docId.includes(searchTerm) && !filename.includes(searchTerm))
            return false;
        }

        // Filter to fully-exported docs only
        if (completedOnly && !completed.has(item.document_id || 'unknown'))
          return false;

        return true;
      });
    },

    // Base stats with hidden document filter applied (used for analytics/charts)
    // Performance: Direct Set.has() check is O(1)
    baseFilteredServiceStats(): any[] {
      const filteredStats = this.baseFilteredServiceStatsIncludingHidden;
      const hiddenIds = this.hiddenDocumentIds;

      // Performance: Skip filter if no hidden documents
      if (hiddenIds.size === 0) {
        return filteredStats;
      }

      return filteredStats.filter(
        (item: any) => !hiddenIds.has(item.document_id),
      );
    },

    // Performance: Generate cache key for stats filtered by services
    _statsFilteredByServicesKey(): string {
      return [
        this._baseFilterCacheKey,
        Array.from(this.selectedServices).sort().join(','),
        this.hiddenDocumentIds.size, // Include hidden count for cache invalidation
      ].join('|');
    },

    // Performance: Generate cache key for stats including hidden docs (no hidden filter applied)
    _statsFilteredByServicesIncludingHiddenKey(): string {
      // Same as above but without hidden doc count since we include hidden docs
      return [
        this._baseFilterCacheKey,
        Array.from(this.selectedServices).sort().join(','),
        'includeHidden',
      ].join('|');
    },

    // Performance: Shared intermediate computation for stats filtered by selected services
    // Flow type filtering is already done in _statsForCurrentFlowType (pre-indexed from backend)
    // Uses caching to avoid redundant array filtering on repeated access
    _statsFilteredByFlowAndServices(): any[] {
      const cacheKey = this._statsFilteredByServicesKey;

      // Return cached result if cache key matches
      if (
        this._cachedStatsFilteredByServicesKey === cacheKey &&
        this._cachedStatsFilteredByServices !== null
      ) {
        return this._cachedStatsFilteredByServices;
      }

      const baseStats = this.baseFilteredServiceStats;
      if (baseStats.length === 0 || this.selectedServices.size === 0) {
        this._cachedStatsFilteredByServices = [];
        this._cachedStatsFilteredByServicesKey = cacheKey;
        return [];
      }

      // Performance: Only filter by selected services (flow type already filtered)
      // Handles composite keys (e.g., STATUS_X::2) for status entries with occurrence >= 2
      const selectedServicesSet = this.selectedServices;

      const result = baseStats.filter((item: any) => {
        const serviceName = normalizeServiceName(item.service);
        // Direct match (non-status or occurrence 1)
        if (selectedServicesSet.has(serviceName)) return true;
        // Composite match for status entries with occurrence >= 2
        const occurrence = item.status_occurrence || 1;
        if (occurrence >= 2) {
          return selectedServicesSet.has(`${serviceName}::${occurrence}`);
        }
        return false;
      });

      // Cache the result
      this._cachedStatsFilteredByServices = result;
      this._cachedStatsFilteredByServicesKey = cacheKey;

      return result;
    },

    // Performance: Shared intermediate for stats including hidden docs
    // Uses caching to avoid redundant array filtering on repeated access
    _statsFilteredByFlowAndServicesIncludingHidden(): any[] {
      const cacheKey = this._statsFilteredByServicesIncludingHiddenKey;

      // Return cached result if cache key matches
      if (
        this._cachedStatsFilteredByServicesIncludingHiddenKey === cacheKey &&
        this._cachedStatsFilteredByServicesIncludingHidden !== null
      ) {
        return this._cachedStatsFilteredByServicesIncludingHidden;
      }

      const baseStats = this.baseFilteredServiceStatsIncludingHidden;
      if (baseStats.length === 0 || this.selectedServices.size === 0) {
        this._cachedStatsFilteredByServicesIncludingHidden = [];
        this._cachedStatsFilteredByServicesIncludingHiddenKey = cacheKey;
        return [];
      }

      // Performance: Only filter by selected services (flow type already filtered)
      // Handles composite keys (e.g., STATUS_X::2) for status entries with occurrence >= 2
      const selectedServicesSet = this.selectedServices;

      const result = baseStats.filter((item: any) => {
        const serviceName = normalizeServiceName(item.service);
        // Direct match (non-status or occurrence 1)
        if (selectedServicesSet.has(serviceName)) return true;
        // Composite match for status entries with occurrence >= 2
        const occurrence = item.status_occurrence || 1;
        if (occurrence >= 2) {
          return selectedServicesSet.has(`${serviceName}::${occurrence}`);
        }
        return false;
      });

      // Cache the result
      this._cachedStatsFilteredByServicesIncludingHidden = result;
      this._cachedStatsFilteredByServicesIncludingHiddenKey = cacheKey;

      return result;
    },

    filteredTopDocuments(): any[] {
      const filteredStats = this._statsFilteredByFlowAndServices;
      if (filteredStats.length === 0) return [];

      // Performance: Group by document_id in single pass
      const docMap = new Map<
        string,
        { document_id: string; filename: string; total_time_spent: number }
      >();

      for (const item of filteredStats) {
        const docId = item.document_id;
        if (!docId) continue;

        const existing = docMap.get(docId);
        if (existing) {
          existing.total_time_spent += item.time_spent || 0;
        } else {
          docMap.set(docId, {
            document_id: docId,
            filename: item.filename || docId,
            total_time_spent: item.time_spent || 0,
          });
        }
      }

      // Convert to array and sort
      const result = Array.from(docMap.values());
      const sortMultiplier = this.topDocumentsSortOrder === 'desc' ? -1 : 1;
      result.sort(
        (a, b) => sortMultiplier * (a.total_time_spent - b.total_time_spent),
      );

      return result;
    },

    // All top documents including hidden ones (for display in list with visibility toggle)
    // Hybrid computation: Uses pre-aggregated top 100 documents from backend for large datasets
    // Hidden documents are tracked by ID and shown with faded style in the UI
    allTopDocumentsIncludingHidden(): any[] {
      // Early return if no data loaded
      if (!this.flow_data) {
        return [];
      }

      // Local computation from raw data
      // Note: filteredStats already has filters applied via baseFilteredServiceStatsIncludingHidden
      const filteredStats = this._statsFilteredByFlowAndServicesIncludingHidden;
      if (filteredStats.length === 0) return [];

      // Performance: Group by document_id in single pass
      const docMap = new Map<
        string,
        { document_id: string; filename: string; total_time_spent: number }
      >();

      for (const item of filteredStats) {
        const docId = item.document_id;
        if (!docId) continue;

        const existing = docMap.get(docId);
        if (existing) {
          existing.total_time_spent += item.time_spent || 0;
        } else {
          docMap.set(docId, {
            document_id: docId,
            filename: item.filename || docId,
            total_time_spent: item.time_spent || 0,
          });
        }
      }

      // Convert to array and sort
      const result = Array.from(docMap.values());
      const sortMultiplier = this.topDocumentsSortOrder === 'desc' ? -1 : 1;
      result.sort(
        (a, b) => sortMultiplier * (a.total_time_spent - b.total_time_spent),
      );

      return result;
    },

    // Total pages for top documents pagination
    topDocsTotalPages(): number {
      const total = this.allTopDocumentsIncludingHidden.length;
      if (total === 0) return 1;
      return Math.ceil(total / this.topDocsPageSize);
    },

    topDocumentsDisplay(): any[] {
      // Get all documents (backend returns all, sorted by total_time)
      const allDocs = this.allTopDocumentsIncludingHidden;
      if (allDocs.length === 0) return [];

      // Apply pagination
      const startIndex = (this.topDocsCurrentPage - 1) * this.topDocsPageSize;
      const endIndex = startIndex + this.topDocsPageSize;
      const topDocs = allDocs.slice(startIndex, endIndex);

      // Performance: Calculate maxTime from ALL documents (for consistent progress bar scaling)
      let maxTime = 0;
      for (const d of allDocs) {
        const t = d.total_time_spent || 0;
        if (t > maxTime) maxTime = t;
      }
      if (maxTime === 0) maxTime = 1;

      const systemAvg = this.systemAverageTotal;
      const showAvg =
        this.showDocbitsAverage &&
        systemAvg !== null &&
        systemAvg !== undefined;
      const criticalThreshold = showAvg ? systemAvg * 1.25 : 0;
      const hiddenIds = this.hiddenDocumentIds;

      // Performance: Pre-allocate result array
      const result = new Array(topDocs.length);
      for (let i = 0; i < topDocs.length; i++) {
        const doc = topDocs[i];
        const timeSpent = doc.total_time_spent || 0;
        const isHidden = hiddenIds.has(doc.document_id);

        let progressColor: string;
        let textClass: string;

        if (isHidden) {
          progressColor = 'grey';
          textClass = 'text-grey';
        } else if (showAvg) {
          if (timeSpent >= criticalThreshold) {
            progressColor = 'red';
            textClass = 'text-red';
          } else if (timeSpent > systemAvg!) {
            progressColor = 'orange';
            textClass = 'text-orange';
          } else {
            progressColor = 'green';
            textClass = 'text-green';
          }
        } else {
          progressColor = 'primary';
          textClass = '';
        }

        result[i] = {
          document_id: doc.document_id,
          filename: doc.filename,
          total_time_spent: timeSpent,
          normalizedValue: timeSpent / maxTime,
          progressColor,
          textClass,
          isHidden,
        };
      }
      return result;
    },

    // Label for top documents count
    topDocumentsCountLabel(): string {
      const total = this.allTopDocumentsIncludingHidden.length;
      return `${this.$t('total')}: ${total}`;
    },

    // Set of document_ids whose current status counts as "fully exported".
    // Backend pre-filters using DOC_FULLY_EXPORTED_STATUSES and returns just
    // the ids, so per-doc-total metrics can skip partial-pipeline docs in
    // O(1) without the frontend ever seeing raw statuses.
    completedDocIds(): Set<string> {
      return new Set((this.flow_data as any)?.completed_doc_ids ?? []);
    },

    aggregatedChartData(): Array<{ service: string; avg: number }> {
      // baseFilteredServiceStats already uses _statsForCurrentFlowType (pre-indexed by flow type)
      const filteredStats = this.baseFilteredServiceStats;
      if (filteredStats.length === 0) return [];

      // Step 1: Aggregate by (service + occurrence + document_id) to get sum per document per service
      // For status entries with occurrence >= 2, use composite key to separate them
      // Structure: Map<service, Map<document_id, sum>>
      const serviceDocMap = new Map<string, Map<string, number>>();

      filteredStats.forEach((item: any) => {
        const normalized = normalizeServiceName(item.service);
        const occurrence = item.status_occurrence || 1;
        const service =
          normalized.startsWith('STATUS_') && occurrence >= 2
            ? `${item.service}::${occurrence}`
            : item.service;
        const documentId = item.document_id || 'unknown';

        if (!serviceDocMap.has(service)) {
          serviceDocMap.set(service, new Map<string, number>());
        }
        const docMap = serviceDocMap.get(service)!;
        const currentSum = docMap.get(documentId) || 0;
        docMap.set(documentId, currentSum + (item.time_spent || 0));
      });

      // Step 2: For each service, calculate average across unique documents
      // avg = sum of all document totals / number of unique documents
      const aggregatedStats: Array<{ service: string; avg: number }> = [];
      serviceDocMap.forEach((docMap, service) => {
        let totalSum = 0;
        docMap.forEach((docSum) => {
          totalSum += docSum;
        });
        const uniqueDocCount = docMap.size;
        const avgPerDocument =
          uniqueDocCount > 0 ? totalSum / uniqueDocCount : 0;

        aggregatedStats.push({
          service,
          avg: avgPerDocument,
        });
      });

      return aggregatedStats;
    },

    // Filtered chart data based on selected services - used for AverageTimeChart
    selectedChartData(): Array<{ service: string; avg: number }> {
      const chartData = this.aggregatedChartData;
      if (chartData.length === 0 || this.selectedServices.size === 0) return [];

      return chartData.filter((item: { service: string; avg: number }) => {
        return this.selectedServices.has(normalizeServiceName(item.service));
      });
    },

    totalDocumentsAverage(): number | undefined {
      // Calculate total average based on selected services only
      // This ensures the chart reacts when cards are selected/unselected
      const selectedData = this.selectedChartData;
      if (selectedData.length === 0) return undefined;

      // Sum selected service averages to get total average time
      const totalTime = selectedData.reduce(
        (sum: number, item: { service: string; avg: number }) =>
          sum + (item.avg || 0),
        0,
      );
      return totalTime;
    },

    // Performance: Pre-compute label maps for grouping operations (avoid .find() in loops)
    _subOrgLabelMapForGrouping(): Map<string, string> {
      const map = new Map<string, string>();
      const defaultLabel = this.orgName ? `${this.orgName} (CROSS)` : 'CROSS';
      for (const opt of this.filterSubOrgsList) {
        map.set(opt.value, opt.label);
      }
      // Store default for missing values
      map.set('__default__', defaultLabel);
      return map;
    },

    _docTypeLabelMapForGrouping(): Map<string, string> {
      const map = new Map<string, string>();
      const unknownLabel = this.$t('unknown');
      for (const opt of this.filterDocTypeList) {
        map.set(opt.value, opt.label);
      }
      map.set('__default__', unknownLabel);
      return map;
    },

    // Grouped chart data based on chartGroupBy selection - used for AverageTimeChart
    groupedChartData(): Array<{ service: string; avg: number }> {
      // When grouping by service, use the existing selectedChartData
      if (this.chartGroupBy === 'flow') {
        return this.selectedChartData;
      }

      // Performance: Use pre-computed stats filtered by flow type and services
      const filteredStats = this._statsFilteredByFlowAndServices;
      if (filteredStats.length === 0) return [];

      // Performance: Use pre-computed label maps for O(1) lookup instead of .find() in loop
      const subOrgLabelMap = this._subOrgLabelMapForGrouping;
      const docTypeLabelMap = this._docTypeLabelMapForGrouping;
      const unknownLabel = this.$t('unknown');

      // Step 1: aggregate per (groupKey, document_id) — per-doc total time
      // per group. The "Completed only" toggle is applied at the base filter
      // (baseFilteredServiceStatsIncludingHidden) so filteredStats already
      // excludes partial-pipeline docs when the toggle is on.
      const groupDocMap = new Map<string, Map<string, number>>();

      for (const item of filteredStats) {
        let groupKey: string;

        switch (this.chartGroupBy) {
          case 'sub_org':
            groupKey =
              subOrgLabelMap.get(item.sub_org_id) ||
              subOrgLabelMap.get('__default__')!;
            break;
          case 'doc_type':
            groupKey =
              docTypeLabelMap.get(item.doc_type) ||
              item.doc_type ||
              unknownLabel;
            break;
          case 'supplier':
            groupKey =
              (this.supplierNameMap as Map<string, string>).get(
                item.supplier_id,
              ) ||
              item.supplier_id ||
              unknownLabel;
            break;
          case 'assigned_group': {
            const gid = item.assigned_group_id;
            groupKey = gid
              ? (this.groupsMap as Map<string, any>).get(gid)?.name || gid
              : unknownLabel;
            break;
          }
          default:
            groupKey = item.service;
            break;
        }

        const documentId = item.document_id || 'unknown';

        let docMap = groupDocMap.get(groupKey);
        if (!docMap) {
          docMap = new Map<string, number>();
          groupDocMap.set(groupKey, docMap);
        }
        const currentSum = docMap.get(documentId) || 0;
        docMap.set(documentId, currentSum + (item.time_spent || 0));
      }

      // Step 2: For each group, calculate average across unique documents
      // avg = sum of all document totals / number of unique documents
      const result: Array<{ service: string; avg: number }> = [];
      groupDocMap.forEach((docMap, groupKey) => {
        let totalSum = 0;
        docMap.forEach((docSum) => {
          totalSum += docSum;
        });
        const uniqueDocCount = docMap.size;
        const avgPerDocument =
          uniqueDocCount > 0 ? totalSum / uniqueDocCount : 0;

        result.push({
          service: groupKey,
          avg: avgPerDocument,
        });
      });

      // Sort by avg descending for better visualization
      result.sort((a, b) => b.avg - a.avg);

      return result;
    },

    groupedChartTotalAverage(): number | undefined {
      // "Workflow time" — end-to-end time per document. The "Completed only"
      // toggle is applied at the base filter, so filteredStats already
      // restricts to fully-exported docs when on.

      const filteredStats = this._statsFilteredByFlowAndServices;
      if (filteredStats.length === 0) return undefined;

      const docTotals = new Map<string, number>();
      filteredStats.forEach((item: any) => {
        const docId = item.document_id || 'unknown';
        const currentSum = docTotals.get(docId) || 0;
        docTotals.set(docId, currentSum + (item.time_spent || 0));
      });

      let totalSum = 0;
      docTotals.forEach((docSum) => {
        totalSum += docSum;
      });
      const uniqueDocCount = docTotals.size;

      return uniqueDocCount > 0 ? totalSum / uniqueDocCount : undefined;
    },

    // Base filtered system average stats for phase totals (doc_type_stats)
    baseFilteredSystemAvgStats(): any[] {
      const stats = this.system_avg_data?.doc_type_stats;
      if (!stats || stats.length === 0) return [];

      // Filter by selected doc_types (multi-select)
      let filteredStats = stats;
      const isDocTypeAllSelected =
        this.selectedDocType.includes(ALL_FILTER_VALUE);
      if (!isDocTypeAllSelected && this.selectedDocType.length > 0) {
        filteredStats = filteredStats.filter((item: any) =>
          this.selectedDocType.includes(item.doc_type),
        );
      }

      return filteredStats;
    },

    // Base filtered service averages (service_averages) - for individual card system averages
    baseFilteredServiceAvgStats(): any[] {
      const stats = this.system_avg_data?.service_averages;
      if (!stats || stats.length === 0) return [];

      // Filter by selected doc_types (multi-select)
      let filteredStats = stats;
      const isDocTypeAllSelected =
        this.selectedDocType.includes(ALL_FILTER_VALUE);
      if (!isDocTypeAllSelected && this.selectedDocType.length > 0) {
        filteredStats = filteredStats.filter((item: any) =>
          this.selectedDocType.includes(item.doc_type),
        );
      }

      return filteredStats;
    },

    // System average by phase - weighted average per phase based on selected doc_types
    // Returns Map<'processing'|'status'|'user', weighted_avg>
    systemAverageByFlowType(): Map<string, number> {
      const map = new Map<string, number>();

      const filteredStats = this.baseFilteredSystemAvgStats;
      if (filteredStats.length === 0) return map;

      // Group by flow_type, calculate weighted average by doc_count
      const flowTypeStats = new Map<
        string,
        { weightedSum: number; totalDocs: number }
      >();

      filteredStats.forEach((item: any) => {
        const flowType = item.flow_type; // 'processing', 'status', or 'user'
        if (!flowType) return;

        if (!flowTypeStats.has(flowType)) {
          flowTypeStats.set(flowType, { weightedSum: 0, totalDocs: 0 });
        }
        const entry = flowTypeStats.get(flowType)!;
        const avg = item.avg || 0;
        const docCount = item.doc_count || 1;
        entry.weightedSum += avg * docCount;
        entry.totalDocs += docCount;
      });

      // Calculate weighted average for each flow_type
      flowTypeStats.forEach((value, flowType) => {
        if (value.totalDocs > 0) {
          map.set(flowType, value.weightedSum / value.totalDocs);
        }
      });

      return map;
    },

    // System average total - sum of flow_type averages for selected services' flow_types
    // Only counts each flow_type once (avoids double-counting multiple STATUS_* or USER_* cards)
    systemAverageTotal(): number | null {
      if (this.selectedServices.size === 0) {
        return null;
      }

      // Collect unique flow_types from selected services
      const selectedFlowTypes = new Set<string>();
      this.selectedServices.forEach((serviceName) => {
        const flowType = this.getServiceFlowType(serviceName);
        selectedFlowTypes.add(flowType);
      });

      // Sum the flow_type averages for selected flow_types
      let totalSum = 0;
      let hasValue = false;

      selectedFlowTypes.forEach((flowType) => {
        const flowTypeAvg = this.systemAverageByFlowType.get(flowType);
        if (flowTypeAvg !== undefined) {
          totalSum += flowTypeAvg;
          hasValue = true;
        }
      });

      return hasValue ? totalSum : null;
    },

    // System average map by service name for flow cards (from service_averages)
    systemAverageByService(): Map<string, number> {
      const map = new Map<string, number>();

      // Use filtered service avg stats
      const filteredStats = this.baseFilteredServiceAvgStats;
      if (filteredStats.length === 0) return map;

      // Group by service and calculate weighted average by count
      const serviceStats = new Map<
        string,
        { weightedSum: number; totalCount: number }
      >();
      filteredStats.forEach((item: any) => {
        const normalizedName = normalizeServiceName(item.service);
        if (!serviceStats.has(normalizedName)) {
          serviceStats.set(normalizedName, { weightedSum: 0, totalCount: 0 });
        }
        const entry = serviceStats.get(normalizedName)!;
        const avg = item.avg_time_spent || 0;
        const count = item.count || 1;
        entry.weightedSum += avg * count;
        entry.totalCount += count;
      });

      // Calculate weighted average for each service
      serviceStats.forEach((value, service) => {
        if (value.totalCount > 0) {
          map.set(service, value.weightedSum / value.totalCount);
        }
      });

      return map;
    },

    combinedServicesTimeData(): Array<{
      date: string;
      min: number;
      avg: number;
      max: number;
    }> {
      // Performance: Use pre-computed stats filtered by flow type and services
      const filteredStats = this._statsFilteredByFlowAndServices;
      if (filteredStats.length === 0) return [];

      // Time-series of per-doc totals bucketed by date. "Completed only" is
      // applied at the base filter; when on, recent days will look thin
      // until today's docs export.
      const dateDocMap = new Map<string, Map<string, number>>();

      filteredStats.forEach((item: any) => {
        const documentId = item.document_id || 'unknown';
        const date = item.date;
        const timeSpent = item.time_spent || 0;

        if (!dateDocMap.has(date)) {
          dateDocMap.set(date, new Map<string, number>());
        }
        const docMap = dateDocMap.get(date)!;
        docMap.set(documentId, (docMap.get(documentId) || 0) + timeSpent);
      });

      // Step 2: For each date, calculate min/avg/max from document totals
      const result: Array<{
        date: string;
        min: number;
        avg: number;
        max: number;
      }> = [];
      dateDocMap.forEach((docMap, date) => {
        // Get document totals (filter out zero values)
        const documentTotals = Array.from(docMap.values()).filter((v) => v > 0);

        if (documentTotals.length > 0) {
          const sum = documentTotals.reduce((acc, val) => acc + val, 0);
          result.push({
            date,
            min: Math.min(...documentTotals),
            avg: sum / documentTotals.length,
            max: Math.max(...documentTotals),
          });
        } else {
          result.push({
            date,
            min: 0,
            avg: 0,
            max: 0,
          });
        }
      });

      // Sort by date
      return result.sort(
        (a, b) => new Date(a.date).getTime() - new Date(b.date).getTime(),
      );
    },

    // Grouped time series data for ServiceTimeChart when grouping by sub_org/doc_type/supplier
    groupedTimeSeriesData(): Array<{
      name: string;
      data: Array<{ date: string; avg: number }>;
    }> {
      if (this.timeChartGroupBy === 'flow') return [];

      // Performance: Use pre-computed stats filtered by flow type and services
      const filteredStats = this._statsFilteredByFlowAndServices;
      if (filteredStats.length === 0) return [];

      // Performance: Use pre-computed label maps for O(1) lookup instead of .find() in loop
      const subOrgLabelMap = this._subOrgLabelMapForGrouping;
      const docTypeLabelMap = this._docTypeLabelMapForGrouping;
      const unknownLabel = this.$t('unknown');

      const groupDateDocMap = new Map<
        string,
        Map<string, Map<string, number>>
      >();
      const allDates = new Set<string>();

      for (const item of filteredStats) {
        let groupKey: string;

        switch (this.timeChartGroupBy) {
          case 'sub_org':
            groupKey =
              subOrgLabelMap.get(item.sub_org_id) ||
              subOrgLabelMap.get('__default__')!;
            break;
          case 'doc_type':
            groupKey =
              docTypeLabelMap.get(item.doc_type) ||
              item.doc_type ||
              unknownLabel;
            break;
          case 'supplier':
            groupKey =
              (this.supplierNameMap as Map<string, string>).get(
                item.supplier_id,
              ) ||
              item.supplier_id ||
              unknownLabel;
            break;
          case 'assigned_group': {
            const gid = item.assigned_group_id;
            groupKey = gid
              ? (this.groupsMap as Map<string, any>).get(gid)?.name || gid
              : unknownLabel;
            break;
          }
          default:
            continue;
        }

        const date = item.date;
        const documentId = item.document_id || 'unknown';
        allDates.add(date);

        let dateMap = groupDateDocMap.get(groupKey);
        if (!dateMap) {
          dateMap = new Map<string, Map<string, number>>();
          groupDateDocMap.set(groupKey, dateMap);
        }
        let docMap = dateMap.get(date);
        if (!docMap) {
          docMap = new Map<string, number>();
          dateMap.set(date, docMap);
        }
        const currentSum = docMap.get(documentId) || 0;
        docMap.set(documentId, currentSum + (item.time_spent || 0));
      }

      // Sort dates
      const sortedDates = Array.from(allDates).sort(
        (a, b) => new Date(a).getTime() - new Date(b).getTime(),
      );

      // Step 2: Convert to array of series, calculating average per document for each date
      const result: Array<{
        name: string;
        data: Array<{ date: string; avg: number }>;
      }> = [];
      groupDateDocMap.forEach((dateMap, groupKey) => {
        const seriesData: Array<{ date: string; avg: number }> = [];
        for (const date of sortedDates) {
          const docMap = dateMap.get(date);
          if (!docMap || docMap.size === 0) {
            seriesData.push({ date, avg: 0 });
          } else {
            // Calculate average: sum of all document totals / number of unique documents
            let totalSum = 0;
            docMap.forEach((docSum) => {
              totalSum += docSum;
            });
            const avgPerDocument = totalSum / docMap.size;
            seriesData.push({ date, avg: avgPerDocument });
          }
        }
        result.push({
          name: groupKey,
          data: seriesData,
        });
      });

      // Sort by total avg descending (most significant groups first)
      result.sort((a, b) => {
        const totalA = a.data.reduce((sum, d) => sum + d.avg, 0);
        const totalB = b.data.reduce((sum, d) => sum + d.avg, 0);
        return totalB - totalA;
      });

      return result;
    },

    selectedServicesLabels(): string {
      // Only include labels for services that are currently visible in elements
      // Use el.label directly to handle composite names with occurrence prefix
      const visibleElements = this.elements;
      const labelMap = new Map<string, string>(
        visibleElements.map((el: any) => [el.name, el.label]),
      );
      const labels: string[] = [];
      this.selectedServices.forEach((serviceName) => {
        const label = labelMap.get(serviceName);
        if (label) {
          labels.push(label);
        }
      });
      return labels.join(', ');
    },

    allSelected(): boolean {
      // Check if all visible cards are selected
      if (this.elements.length === 0) return false;
      const visibleServiceNames = this.elements.map((el: any) => el.name);
      return visibleServiceNames.every((name: string) =>
        this.selectedServices.has(name),
      );
    },

    // Performance: Pre-compute selection state for each element to avoid method calls in template
    // This creates a reactive dependency that only updates when selectedServices or elements change
    _elementSelectionStates(): Map<string, boolean> {
      const states = new Map<string, boolean>();
      const pending = this._pendingServiceSelection;
      const selected = this.selectedServices;

      for (const el of this.elements) {
        const name = el.name;
        if (pending) {
          states.set(name, pending.has(name));
        } else {
          states.set(name, selected.has(name));
        }
      }
      return states;
    },

    selectedRowIds(): string[] {
      // Convert selectedServices (Set of names) to array of row IDs for DocBitsTable
      return this.elements
        .filter((el: any) => this.selectedServices.has(el.name))
        .map((el: any) => el.id);
    },

