    // Visible table columns (excluding hidden ones)
    visibleTableColumns(): any[] {
      return this.tableColumns.filter(
        (col) => !this.hiddenColumnNames.includes(col.name),
      );
    },

    // Hidden table columns
    hiddenTableColumns(): any[] {
      return this.tableColumns.filter((col) =>
        this.hiddenColumnNames.includes(col.name),
      );
    },

    // Canonical column order (includes all columns, for restoring hidden columns to original position)
    tableColumnOrder(): string[] {
      return this.tableColumns.map((col) => col.name);
    },

    // Performance: Pre-compute label lookup maps for tableElements
    _subOrgLabelMap(): Map<string, string> {
      const map = new Map<string, string>();
      for (const opt of this.filterSubOrgsList) {
        map.set(opt.value, opt.label);
      }
      return map;
    },

    _docTypeLabelMap(): Map<string, string> {
      const map = new Map<string, string>();
      for (const opt of this.filterDocTypeList) {
        map.set(opt.value, opt.label);
      }
      return map;
    },

    // Table elements - dynamically grouped based on visible columns
    // When columns are hidden, rows are aggregated and min/max/avg are recalculated
    tableElements(): any[] {
      // Performance: Use pre-computed stats filtered by flow type and services
      const filteredStats = this._statsFilteredByFlowAndServices;
      if (filteredStats.length === 0) return [];

      // Performance: Use pre-computed label maps for O(1) lookup
      const subOrgLabelMap = this._subOrgLabelMap;
      const docTypeLabelMap = this._docTypeLabelMap;

      // Determine which columns are visible (not hidden)
      const visibleColNames = new Set(
        this.visibleTableColumns.map((col) => col.name),
      );

      // Build dynamic group key based on visible columns only
      const groupKey = (item: any) => {
        const parts: string[] = [];

        // Only include dimension in key if its column is visible
        if (visibleColNames.has('subOrg')) {
          parts.push(item.sub_org_id || '');
        }
        if (visibleColNames.has('docType')) {
          parts.push(item.doc_type || '');
        }
        if (visibleColNames.has('supplier')) {
          parts.push(item.supplier_id || '');
        }
        if (visibleColNames.has('flowStep')) {
          const normalized = normalizeServiceName(item.service);
          const occurrence = item.status_occurrence || 1;
          parts.push(
            normalized.startsWith('STATUS_') && occurrence >= 2
              ? `${normalized}::${occurrence}`
              : normalized,
          );
        }
        if (visibleColNames.has('assignedGroup')) {
          parts.push(item.assigned_group_id || '');
        }
        if (visibleColNames.has('documentName')) {
          parts.push(item.document_id || '');
        }
        if (visibleColNames.has('date')) {
          parts.push(item.date || '');
        }

        return parts.join('|');
      };

      // Group data based on dynamic key, collecting time_spent values
      const docGroupMap = new Map<
        string,
        {
          sub_org_id: string;
          doc_type: string;
          supplier_id: string;
          assigned_group_id: string;
          service: string;
          status_occurrence: number;
          document_id: string;
          filename: string;
          date: string;
          values: number[];
        }
      >();

      filteredStats.forEach((item: any) => {
        const key = groupKey(item);
        if (!docGroupMap.has(key)) {
          docGroupMap.set(key, {
            sub_org_id: item.sub_org_id || '',
            doc_type: item.doc_type || '',
            supplier_id: item.supplier_id || '',
            assigned_group_id: item.assigned_group_id || '',
            service: normalizeServiceName(item.service),
            status_occurrence: item.status_occurrence || 1,
            document_id: item.document_id || '',
            filename: item.filename || item.document_id || '',
            date: item.date || '',
            values: [],
          });
        }
        const entry = docGroupMap.get(key)!;
        const timeSpent = item.time_spent || 0;
        if (timeSpent > 0) {
          entry.values.push(timeSpent);
        }
      });

      // Convert to array and create table rows
      const result: any[] = [];
      let index = 0;
      docGroupMap.forEach((entry) => {
        const normalizedName = entry.service;
        const compositeKey =
          entry.status_occurrence >= 2
            ? `${normalizedName}::${entry.status_occurrence}`
            : normalizedName;
        const capitalizedLabel = this.formatServiceLabel(compositeKey);

        // Performance: Use pre-computed label maps for O(1) lookup instead of .find()
        const subOrgLabel =
          subOrgLabelMap.get(entry.sub_org_id) || entry.sub_org_id || '-';
        const docTypeLabel =
          docTypeLabelMap.get(entry.doc_type) || entry.doc_type || '-';

        // Document name: use filename or document_id
        const documentName = entry.filename || '-';

        // Performance: Calculate min/avg/max in single pass (avoids spread operator overhead)
        let minVal = 0;
        let avgVal = 0;
        let maxVal = 0;
        const values = entry.values;
        const len = values.length;
        if (len > 0) {
          let sum = values[0];
          minVal = values[0];
          maxVal = values[0];
          for (let i = 1; i < len; i++) {
            const v = values[i];
            sum += v;
            if (v < minVal) minVal = v;
            if (v > maxVal) maxVal = v;
          }
          avgVal = sum / len;
        }

        result.push({
          id: `${index}`,
          name: normalizedName,
          subOrg: subOrgLabel,
          docType: docTypeLabel,
          supplier:
            (this.supplierNameMap as Map<string, string>).get(
              entry.supplier_id,
            ) ||
            entry.supplier_id ||
            '-',
          assignedGroup: entry.assigned_group_id
            ? (this.groupsMap as Map<string, any>).get(entry.assigned_group_id)
                ?.name || entry.assigned_group_id
            : '-',
          documentName: documentName,
          docId: entry.document_id || '-',
          date: entry.date
            ? this.formatDateAccordingToPreference(entry.date, true)
            : '-',
          rawDate: entry.date || '', // Performance: Store raw date for sorting
          flowStep: capitalizedLabel,
          avgTime: this.formatDuration(avgVal),
          minTime: this.formatDuration(minVal),
          maxTime: this.formatDuration(maxVal),
          // Performance: Store raw numeric values to avoid re-parsing during sorting
          _avgTimeRaw: avgVal,
          _minTimeRaw: minVal,
          _maxTimeRaw: maxVal,
        });
        index++;
      });

      return result;
    },

    // Sorted table elements - applies user-selected column sorting and pagination
    // Performance: Uses raw numeric values stored in tableElements to avoid re-parsing
    sortedTableElements(): any[] {
      const elements = [...this.tableElements];
      const sortBy = this.tablePagination.sortBy;
      const descending = this.tablePagination.descending;
      const sortMultiplier = descending ? -1 : 1;

      // Performance: Map time columns to their raw counterparts
      const rawTimeColumns: Record<string, string> = {
        minTime: '_minTimeRaw',
        avgTime: '_avgTimeRaw',
        maxTime: '_maxTimeRaw',
      };

      // Apply sorting
      if (!sortBy) {
        // Default sort - use localeCompare for strings
        elements.sort((a, b) => {
          if (a.subOrg !== b.subOrg) return a.subOrg.localeCompare(b.subOrg);
          if (a.docType !== b.docType)
            return a.docType.localeCompare(b.docType);
          if (a.supplier !== b.supplier)
            return a.supplier.localeCompare(b.supplier);
          if (a.documentName !== b.documentName)
            return a.documentName.localeCompare(b.documentName);
          if (a.rawDate !== b.rawDate)
            return a.rawDate.localeCompare(b.rawDate);
          return a.flowStep.localeCompare(b.flowStep);
        });
      } else {
        // Sort by selected column
        const rawColumn = rawTimeColumns[sortBy];

        if (rawColumn) {
          // Performance: Use pre-computed raw numeric values for time columns
          elements.sort(
            (a, b) => sortMultiplier * (a[rawColumn] - b[rawColumn]),
          );
        } else if (sortBy === 'date') {
          // Sort by raw date string for proper chronological ordering
          elements.sort(
            (a, b) => sortMultiplier * a.rawDate.localeCompare(b.rawDate),
          );
        } else {
          // String columns
          elements.sort((a, b) => {
            const aVal = a[sortBy] || '';
            const bVal = b[sortBy] || '';
            return sortMultiplier * aVal.localeCompare(bVal);
          });
        }
      }

      // Apply pagination - slice to current page
      const page = this.tablePagination.page || 1;
      const rowsPerPage = this.tablePagination.rowsPerPage || 20;
      const startIndex = (page - 1) * rowsPerPage;
      const endIndex = startIndex + rowsPerPage;

      return elements.slice(startIndex, endIndex);
    },

    // Elements (DocumentFlowCards) - computed to react to all filters including document search
    // Hybrid computation: Uses pre-aggregated backend data for large datasets (>= 500 docs)
    elements(): any[] {
      // Early return if no data loaded
      if (!this.flow_data) {
        return [];
      }

      // Local computation from raw data
      // Performance: baseFilteredServiceStats already uses _statsForCurrentFlowType (pre-indexed by flow type)
      const filteredStats = this.baseFilteredServiceStats;
      if (filteredStats.length === 0) return [];

      // Group by service (and status_occurrence for status entries), then by document_id to calculate per-document totals
      // For status entries with occurrence >= 2, use composite key to create separate cards
      const serviceMap = new Map<string, Map<string, number>>();
      const serviceOccurrenceMap = new Map<string, number>(); // Track occurrence per composite key

      filteredStats.forEach((item: any) => {
        const service = item.service;
        const occurrence = item.status_occurrence || 1;
        const normalizedService = normalizeServiceName(service);
        const isStatus = normalizedService.startsWith('STATUS_');

        // For status entries, group by service + occurrence to create separate cards
        const groupKey =
          isStatus && occurrence > 1 ? `${service}::${occurrence}` : service;

        if (isStatus && occurrence > 1) {
          serviceOccurrenceMap.set(groupKey, occurrence);
        }

        const documentId = item.document_id || 'unknown';
        if (!serviceMap.has(groupKey)) {
          serviceMap.set(groupKey, new Map<string, number>());
        }
        const docMap = serviceMap.get(groupKey)!;
        const currentSum = docMap.get(documentId) || 0;
        docMap.set(documentId, currentSum + (item.time_spent || 0));
      });

      // Performance: Convert map to array with single-pass min/avg/max calculation
      const aggregatedStats: any[] = [];
      serviceMap.forEach((docMap, groupKey) => {
        // Extract base service name from composite key (service::occurrence)
        const baseService = groupKey.includes('::')
          ? groupKey.split('::')[0]
          : groupKey;
        const occurrence = serviceOccurrenceMap.get(groupKey) || 1;

        let sum = 0;
        let min = Infinity;
        let max = 0;
        let count = 0;

        docMap.forEach((value) => {
          if (value > 0) {
            sum += value;
            if (value < min) min = value;
            if (value > max) max = value;
            count++;
          }
        });

        if (count > 0) {
          aggregatedStats.push({
            service: baseService,
            occurrence,
            avg: sum / count,
            min,
            max,
          });
        } else {
          aggregatedStats.push({
            service: baseService,
            occurrence,
            avg: 0,
            min: 0,
            max: 0,
          });
        }
      });

      aggregatedStats.sort((a, b) => compareFlowCards(a, b, getCardOrder));

      const result = aggregatedStats.map((item: any, index: number) => {
        const normalizedName = normalizeServiceName(item.service);
        // Use composite name for uniqueness when occurrence > 1
        const uniqueName =
          item.occurrence >= 2
            ? `${normalizedName}::${item.occurrence}`
            : normalizedName;
        // formatServiceLabel handles composite keys and occurrence prefix (e.g., "Status: 2. Ready For Validation")
        const displayLabel = this.formatServiceLabel(uniqueName);
        // Get system average for this service
        const systemAvgValue = this.systemAverageByService.get(normalizedName);
        return {
          id: index.toString(),
          name: uniqueName,
          label: displayLabel,
          avgTime: this.formatDuration(item.avg),
          minTime: this.formatDuration(item.min),
          maxTime: this.formatDuration(item.max),
          systemAvg:
            systemAvgValue !== undefined
              ? this.formatDuration(systemAvgValue)
              : null,
          showIcon: index < aggregatedStats.length - 1,
          // Raw values for child components to avoid re-parsing formatted strings
          _avgTimeRaw: item.avg,
          _systemAvgRaw: systemAvgValue !== undefined ? systemAvgValue : null,
        };
      });

      return result;
    },
  },
  watch: {
    // Cold direct load: preferences arrive after mount, so the bootstrap
    // resumes here instead of being skipped for the page's lifetime.
    analyticsAccessReady: {
      immediate: true,
      handler(ready: boolean) {
        if (ready) this.resolveInitialTab();
      },
    },

    // Access revoked mid-session: the tab drops out of flowTypeOptions, but
    // `displayFlowType` would still read 'touchless' and the panel would stay
    // mounted with its loaded data. Fall back to the retained analytics flow
    // and invalidate whatever the panel still has in flight.
    touchlessAccessGranted(granted: boolean) {
      if (granted || !this.isTouchlessTab) return;
      this.touchlessStore.beginAllGenerations();
      this.displayFlowType = this.selectedFlowType;
      this.syncTabQuery(this.selectedFlowType);
      this.initializeDashboard();
    },

    topDocsCurrentPage(newValue) {
      this.topDocsPageInput = newValue;
    },
    selectedFlowType(newValue, oldValue) {
      if (newValue !== oldValue) {
        // Skip rebuild if filter state was restored from a saved tab.
        // Dropdown is now independent of card selection, so restored
        // selectedSteps stays as the user left it — no sync needed.
        if (this._skipFlowTypeWatcher) {
          this._skipFlowTypeWatcher = false;
          return;
        }
        // Performance: Defer selection update to avoid double recalculation
        // Use requestAnimationFrame to batch with the DOM update
        requestAnimationFrame(() => {
          // Get service names for the NEW flow type directly from _statsForCurrentFlowType
          // Since selectedFlowType already changed, _statsForCurrentFlowType returns correct data
          const stats = this._statsForCurrentFlowType;
          const serviceNames = new Set<string>();
          for (const item of stats) {
            if (item.service) {
              const normalized = normalizeServiceName(item.service);
              const occurrence = item.status_occurrence || 1;
              // For status entries with occurrence >= 2, use composite key
              if (normalized.startsWith('STATUS_') && occurrence >= 2) {
                serviceNames.add(`${normalized}::${occurrence}`);
              } else {
                serviceNames.add(normalized);
              }
            }
          }
          // Single atomic update - avoids intermediate empty state
          this.selectedServices = serviceNames;
          // Reset dropdown visibility to "show everything" on a fresh tab.
          this.selectedSteps = [ALL_FILTER_VALUE];
          this.prevSelectedSteps = [ALL_FILTER_VALUE];
        });
      }
    },
    // Update pagination rowsNumber when table elements change
    tableElements: {
      handler(newElements: any[]) {
        this.tablePagination.rowsNumber = newElements.length;
      },
      immediate: true,
    },
  },
  mounted() {
    // Kicks off the preferences round if it has not run yet. The dashboard
    // bootstrap itself is driven by the `analyticsAccessReady` watcher below —
    // gating it here on a `user_settings` object that is still `{}` during a
    // cold direct load skipped the whole initialisation for the lifetime of the
    // page (pre-existing defect; the Touchless tab now depends on this path).
    void this.ensureSettings();

    // Set up ResizeObserver to dynamically calculate cards per row
    this.$nextTick(() => {
      this.setupResizeObserver();
    });
  },
  beforeUnmount() {
    // Clean up ResizeObserver
    if (this.resizeObserver) {
      this.resizeObserver.disconnect();
      this.resizeObserver = null;
    }
    // Clean up window resize listener
    window.removeEventListener('resize', this.handleWindowResize);
    // Performance: Clean up debounce timers
    if (this._filterDebounceTimer) {
      clearTimeout(this._filterDebounceTimer);
      this._filterDebounceTimer = null;
    }
    if (this._documentVisibilityDebounceTimer) {
      clearTimeout(this._documentVisibilityDebounceTimer);
      this._documentVisibilityDebounceTimer = null;
    }
    if (this._serviceSelectionDebounceTimer) {
      clearTimeout(this._serviceSelectionDebounceTimer);
      this._serviceSelectionDebounceTimer = null;
    }
    // Release large cached data and module-level caches to free memory
    clearCaches();
    this.flow_data = null;
    this.system_avg_data = null;
    this._cachedAllStats = null;
    this._cachedStatsFilteredByServices = null;
    this._cachedStatsFilteredByServicesIncludingHidden = null;
    this._cachedSubOrgLabelMapForGrouping = null;
    this._cachedDocTypeLabelMapForGrouping = null;
    this._pendingServiceSelection = null;
  },
  methods: {
    setupResizeObserver(): void {
      const container = this.$refs.flowContainer as HTMLElement;
      if (!container) return;

      // Observe the parent card element instead of flowContainer
      // because flowContainer has overflow-x: auto and doesn't shrink when window shrinks
      const parentCard = container.closest('.q-card') as HTMLElement;
      const observeTarget = parentCard || container;

      // Use ResizeObserver for element size changes
      this.resizeObserver = new ResizeObserver((entries) => {
        for (const entry of entries) {
          // Account for card padding (16px on each side from q-pa-md) when observing parent card
          const padding = parentCard ? 32 : 0;
          this.calculateCardsPerRow(entry.contentRect.width - padding);
        }
      });

      this.resizeObserver.observe(observeTarget);

      // Also listen to window resize for when the container width changes due to window resize
      window.addEventListener('resize', this.handleWindowResize);

      // Initial calculation - use parent card width if available
      const initialWidth = parentCard
        ? parentCard.clientWidth - 32
        : container.clientWidth;
      this.calculateCardsPerRow(initialWidth);
    },

    handleWindowResize(): void {
      // Use the parent card element for width calculation since
      // flowContainer has overflow-x: auto and doesn't shrink when window shrinks
      const container = this.$refs.flowContainer as HTMLElement;
      const parentCard = container?.closest('.q-card') as HTMLElement;
      if (parentCard) {
        // Account for card padding (16px on each side from q-pa-md)
        const availableWidth = parentCard.clientWidth - 32;
        this.calculateCardsPerRow(availableWidth);
      } else if (container) {
        this.calculateCardsPerRow(container.clientWidth);
      }
    },

    calculateCardsPerRow(containerWidth: number): void {
      // Card width is 220px (from CSS grid-template-columns)
      const cardWidth = 250;
      const minCards = 2;
      const maxCards = 10;

      const calculatedCards = Math.floor(containerWidth / cardWidth);
      this.cardsPerRow = Math.max(
        minCards,
        Math.min(maxCards, calculatedCards),
      );
    },

    handleTableSort(payload: {
      column: string;
      direction: 'asc' | 'desc';
    }): void {
      this.tablePagination = {
        ...this.tablePagination,
        sortBy: payload.column,
        descending: payload.direction === 'desc',
      };
    },

    handleTablePaginationUpdate(payload: {
      page?: number;
      rowsPerPage?: number;
    }): void {
      this.tablePagination = {
        ...this.tablePagination,
        ...payload,
      };
