    filterStatsByFlowType(stats: any[], flowType?: string): any[] {
      const type = flowType || this.selectedFlowType;
      if (type === 'modules') {
        return stats.filter((item: any) => {
          const serviceName = normalizeServiceName(item.service);
          const isUserStatus = serviceName.startsWith('USER_');
          const isStatusPrefixed = serviceName.startsWith('STATUS_');
          return !isUserStatus && !isStatusPrefixed;
        });
      } else if (type === 'user') {
        return stats.filter((item: any) => {
          return normalizeServiceName(item.service).startsWith('USER_');
        });
      } else if (type === 'status') {
        return stats.filter((item: any) => {
          return normalizeServiceName(item.service).startsWith('STATUS_');
        });
      }
      return stats;
    },

    // Determine which flow_type a service belongs to for system average calculation
    getServiceFlowType(serviceName: string): 'processing' | 'status' | 'user' {
      const normalized = normalizeServiceName(serviceName);
      if (normalized.startsWith('STATUS_')) return 'status';
      if (normalized.startsWith('USER_')) return 'user';
      return 'processing';
    },

    formatAmount(value: number): string {
      const userLocale = this.user_settings.AMOUNTS_LOCALE;

      return formatAmount(value, userLocale);
    },

    formatServiceLabel(service: string): string {
      return formatServiceLabel(service, this.$t);
    },

    getGroupByLabel(groupBy: string): string {
      const option = this.chartGroupByOptions.find(
        (opt: { label: string; value: string }) => opt.value === groupBy,
      );
      return option?.label || groupBy;
    },

    async updateSelectedTime(value: { start_date: string; end_date: string }) {
      // Same gate as the banner and the bootstrap (DOCB-14282) — a revoked
      // user must not be able to refire org-scoped requests from a date picker
      // that is still on screen.
      if (!this.analyticsAccessGranted) return;
      this.start_date = value.start_date;
      this.end_date = value.end_date;
      const orgId = getOrgId();
      await this.prepareAnalyticsData(orgId, value.start_date, value.end_date);
    },

    async prepareAnalyticsData(
      orgId: string,
      start_date: string,
      end_date: string,
    ) {
      // Nothing on the Touchless tab reads flow data, and its filter bar does
      // not drive this loader. A stray trigger while that tab is open would be
      // a burst of API calls nobody asked for.
      if (this.isTouchlessTab) return;
      // Ownership token: a tab switch mid-flight bumps it, so the response
      // cannot land on a page that has moved on and reset the service
      // selection behind Touchless.
      const generation = ++this.analyticsRequestGeneration;
      this.processing = true;

      let apiData;
      let systemAvgData;
      try {
        // Get available document types for the organization (for system average)
        const docTypesForAvg = (this.active_doc_type_list || [])
          .filter(
            (item: any) =>
              item.value !== null &&
              item.value !== ALL_FILTER_VALUE &&
              item.label?.toLowerCase() !== 'all',
          )
          .map((item: any) => item.value);

        // Fetch both org data and system average in parallel
        // All filtering (sub_org, doc_type, supplier, search) is done in frontend
        [apiData, systemAvgData] = await Promise.all([
          documentFlowDataService.getData_org({ orgId, start_date, end_date }),
          documentFlowDataService
            .getSystemAverage(start_date, end_date, docTypesForAvg)
            .catch(() => null),
        ]);
      } catch (error) {
        // A superseded request's failure is not the user's problem: the newer
        // one owns the screen, and its own outcome will be reported.
        if (generation === this.analyticsRequestGeneration) {
          notify.error(this.$t('ERROR_GETTING_DATA'));
        }
        console.error(error);
        return;
      } finally {
        // Only the request that still owns the screen may take the spinner
        // down; an older one finishing would hide the newer one's loading
        // state while its data is still on the way.
        if (generation === this.analyticsRequestGeneration) {
          this.processing = false;
        }
      }

      // Superseded while in flight — commit nothing.
      if (
        generation !== this.analyticsRequestGeneration ||
        this.isTouchlessTab
      ) {
        return;
      }

      // Store the API response in flow_data so computed properties react
      // (elements is now a computed property that will automatically update)
      this.flow_data = apiData;
      this._flowDataVersion++; // Invalidate _allStats cache
      this.system_avg_data = systemAvgData;

      // Select all services by default when data loads
      this.$nextTick(() => {
        this.toggleSelectAll(true);
      });
    },

    toggleServiceSelection(card: any) {
      const serviceName = card.name;

      // Performance: Use pending set to batch rapid selection changes
      // Initialize pending set from current selection if not already pending
      if (!this._pendingServiceSelection) {
        this._pendingServiceSelection = new Set(this.selectedServices);
      }

      // Apply toggle to pending set
      if (this._pendingServiceSelection.has(serviceName)) {
        this._pendingServiceSelection.delete(serviceName);
      } else {
        this._pendingServiceSelection.add(serviceName);
      }

      // Performance: Trigger immediate UI update by creating new Set reference
      // This makes _elementSelectionStates recompute immediately for responsive UI
      this._pendingServiceSelection = new Set(this._pendingServiceSelection);

      // Debounce the actual state update to batch rapid clicks
      if (this._serviceSelectionDebounceTimer) {
        clearTimeout(this._serviceSelectionDebounceTimer);
      }

      this._serviceSelectionDebounceTimer = setTimeout(() => {
        // Apply pending changes
        if (this._pendingServiceSelection) {
          this.selectedServices = this._pendingServiceSelection;
          this._pendingServiceSelection = null;
        }
        this._serviceSelectionDebounceTimer = null;
      }, 100); // 100ms debounce for batching rapid clicks
    },

    isServiceSelected(card: any): boolean {
      // Performance: Use pre-computed selection states map
      return this._elementSelectionStates.get(card.name) ?? false;
    },

    toggleSelectAll(value: boolean) {
      // Get currently visible service names from elements
      const visibleServiceNames = new Set(
        this.elements.map((el: any) => el.name),
      );

      // Cancel any pending individual selection changes
      if (this._serviceSelectionDebounceTimer) {
        clearTimeout(this._serviceSelectionDebounceTimer);
        this._serviceSelectionDebounceTimer = null;
      }
      this._pendingServiceSelection = null;

      if (!value) {
        // Deselect all visible services (keep non-visible ones selected)
        const newSet = new Set(this.selectedServices);
        visibleServiceNames.forEach((name) => newSet.delete(name));
        this.selectedServices = newSet;
        return;
      }

      // Select all visible services
      const newSet = new Set(this.selectedServices);
      visibleServiceNames.forEach((name) => newSet.add(name));
      this.selectedServices = newSet;
    },

    handleTableSelectionChange(payload: {
      selectedIds: string[];
      selectedRows: any[];
    }) {
      // Convert selected row IDs back to service names
      const newSet = new Set<string>();
      payload.selectedRows.forEach((row: any) => {
        newSet.add(row.name);
      });
      this.selectedServices = newSet;
    },

    // Search input change handler - IMMEDIATE (frontend filtering with debounce)
    onSearchInputChange(value: string | null) {
      this.documentSearch = value ?? '';
    },

    // Handle Enter key press on search input (no-op now, filtering is immediate)
    onSearchEnterKey() {
      // No-op - filtering is immediate
    },

    // Legacy handler for backward compatibility
    onDocumentSearchChange(value: string) {
      this.onSearchInputChange(value);
    },

    async copyDocumentId(documentId: string) {
      try {
        await navigator.clipboard.writeText(documentId);
        notify.success(this.$t('copied_successfully'));
      } catch {
        notify.error(this.$t('error'));
      }
    },

    // Seeds the dashboard's quickFilterMap with a raw_query predicate for
    // this single document, then navigates. dashboard.vue rebuilds its
    // queryParams from the column-filter store on mount, so the doc
    // appears pre-filtered without any URL-parameter plumbing.
    openDocumentInDashboard(documentId: string) {
      if (!documentId) return;
      const dashboard_store = useDashboardStore();
      const escaped = String(documentId)
        .replace(/\\/g, '\\\\')
        .replace(/"/g, '\\"');
      // Start from an empty map so leftover date-range / status filters
      // can't hide the requested document on the destination dashboard.
      const next = new Map<string, any>();
      next.set('raw_query', `id="${escaped}"`);
      dashboard_store.overWriteFilters(next);
      this.$router.push('/dashboard');
    },

    // Toggle document visibility (exclude/include from calculations) - IMMEDIATE
    toggleDocumentVisibility(documentId: string) {
      if (this.hiddenDocumentIds.has(documentId)) {
        this.hiddenDocumentIds.delete(documentId);
      } else {
        this.hiddenDocumentIds.add(documentId);
      }
      // Debounce the reactivity trigger to batch rapid changes
      if (this._documentVisibilityDebounceTimer) {
        clearTimeout(this._documentVisibilityDebounceTimer);
      }
      this._documentVisibilityDebounceTimer = setTimeout(() => {
        this.hiddenDocumentIds = new Set(this.hiddenDocumentIds);
        this._documentVisibilityDebounceTimer = null;
      }, 150);
    },

    toggleAllDocumentsVisibility() {
      if (this.hiddenDocumentIds.size > 0) {
        // Include all - clear hidden set
        this.hiddenDocumentIds = new Set();
      } else {
        // Exclude all - hide all currently visible documents
        const allDocIds = this.allTopDocumentsIncludingHidden.map(
          (doc: any) => doc.document_id,
        );
        this.hiddenDocumentIds = new Set(allDocIds);
      }
    },

    closeAllDropdowns() {
      const dropdownRefs = [
        'topDocsSelect',
        'avgTimeSelect',
        'timeTrendSelect',
