    getIconSrc(name: string): string {
      return resolveDocFlowIcon(name);
    },

    onTableIconError(event: Event) {
      const target = event.target as HTMLImageElement;
      target.src = '/images/docflow/field_extraction.svg';
    },

    /**
     * Generic handler for multi-select filter changes.
     * Handles "All" option toggling logic consistently across Sub Org, Doc Type, and Supplier filters.
     *
     * @param newValue - The new array of selected values
     * @param allValue - The sentinel value representing "All" (e.g., currentOrgId or ALL_FILTER_VALUE)
     * @param prevValueKey - Key to access the previous value array on this component
     * @param currentValueKey - Key to set the current value array on this component
     */
    handleMultiSelectChange(
      newValue: string[],
      allValue: string,
      prevValueKey:
        | 'prevSelectedSubOrg'
        | 'prevSelectedDocType'
        | 'prevSelectedSupplier'
        | 'prevSelectedSteps',
      currentValueKey:
        | 'selectedSubOrg'
        | 'selectedDocType'
        | 'selectedSupplier'
        | 'selectedSteps',
    ): void {
      const hasAll = newValue.includes(allValue);
      const hasOthers = newValue.some((v) => v !== allValue);

      // If nothing selected, default to "All"
      if (newValue.length === 0) {
        this[currentValueKey] = [allValue];
        this[prevValueKey] = [allValue];
        return;
      }

      // If both "All" and other options are selected, decide based on what was just clicked
      if (hasAll && hasOthers) {
        // Use previous value to determine what was clicked
        const prevValue = this[prevValueKey];
        const hadAllBefore =
          prevValue.includes(allValue) && prevValue.length === 1;
        if (hadAllBefore) {
          // User clicked a specific option while "All" was selected -> remove "All"
          const result = newValue.filter((v) => v !== allValue);
          this[currentValueKey] = result;
          this[prevValueKey] = [...result];
        } else {
          // User clicked "All" while other options were selected -> keep only "All"
          this[currentValueKey] = [allValue];
          this[prevValueKey] = [allValue];
        }
        return;
      }

      this[currentValueKey] = newValue;
      this[prevValueKey] = [...newValue];
    },

    // === APPLY BUTTON PATTERN: Pending filter state management ===

    // Resolve "All" toggle logic for multi-select filters
    // Returns the resolved value array after handling All/specific toggle logic
    resolveMultiSelectValue(
      newValue: string[],
      allValue: string,
      prevValue: string[],
    ): string[] {
      if (newValue.length === 0) return [allValue];

      const hasAll = newValue.includes(allValue);
      const hasOthers = newValue.some((v) => v !== allValue);

      if (hasAll && hasOthers) {
        const hadAllBefore =
          prevValue.includes(allValue) && prevValue.length === 1;
        return hadAllBefore
          ? newValue.filter((v) => v !== allValue)
          : [allValue];
      }
      return newValue;
    },

    // Handle Sub Org multi-select change - IMMEDIATE (frontend filtering)
    handleSubOrgChange(newValue: string[]) {
      const currentOrgId = getOrgId();
      const resolved = this.resolveMultiSelectValue(
        newValue,
        currentOrgId,
        this.prevSelectedSubOrg,
      );
      this.selectedSubOrg = resolved;
      this.prevSelectedSubOrg = [...resolved];
    },

    // Handle Doc Type multi-select change - IMMEDIATE (frontend filtering)
    handleDocTypeChange(newValue: string[]) {
      const resolved = this.resolveMultiSelectValue(
        newValue,
        ALL_FILTER_VALUE,
        this.prevSelectedDocType,
      );
      this.selectedDocType = resolved;
      this.prevSelectedDocType = [...resolved];
    },

    // Handle Supplier multi-select change - IMMEDIATE (frontend filtering)
    handleSupplierChange(newValue: string[]) {
      const resolved = this.resolveMultiSelectValue(
        newValue,
        ALL_FILTER_VALUE,
        this.prevSelectedSupplier,
      );
      this.selectedSupplier = resolved;
      this.prevSelectedSupplier = [...resolved];
    },

    // Handle Assigned Group multi-select change - IMMEDIATE (frontend filtering)
    handleAssignedGroupChange(newValue: string[]) {
      const resolved = this.resolveMultiSelectValue(
        newValue,
        ALL_FILTER_VALUE,
        this.prevSelectedAssignedGroup,
      );
      this.selectedAssignedGroup = resolved;
      this.prevSelectedAssignedGroup = [...resolved];
    },

    /**
     * The dashboard's own bootstrap. Idempotent: the readiness watcher, a
     * revocation fallback and the first switch to an analytics tab can all
     * reach it, and only the first call does the work.
     */
    initializeDashboard() {
      if (this.analyticsInitialized) return;
      if (!this.analyticsAccessReady) return;
      // Refuse while Touchless owns the content area. prepareAnalyticsData()
      // would return without requesting anything, and the flag would then block
      // every later attempt — a direct ?tab=touchless load followed by a click
      // on Status left analytics permanently empty for the session.
      if (this.isTouchlessTab) return;
      this.analyticsInitialized = true;

      const dashboard_store = useDashboardStore();
      dashboard_store.quickFilterMap.set('filter', {
        value: 'last_90_days',
        label: 'last_90_days',
      });

      // Load sub-organizations, supplier name map, and groups
      const dropdown_store = useDropdownStore();
      dropdown_store.getSubOrgsList();
      dropdown_store.getSupplierNameMap();
      dropdown_store.prepareGroupsDropdown();

      // Load data from API with the default date range (today - 90 days)
      void this.prepareAnalyticsData(
        this.currentOrg,
        this.start_date,
        this.end_date,
      );
    },

    /**
     * Picks the tab to show once access is known, honouring `?tab=`.
     *
     * Deep-linkable state is what a tab costs you: before the move, Touchless
     * had its own URL, and the supplier/trace back links returned to it. Landing
     * those users on Status would be a plain regression.
     */
    resolveInitialTab() {
      const requested = this.readTabFromQuery();
      const initial =
        requested ?? (this.touchlessAccessGranted ? 'touchless' : 'status');

      if (initial === 'touchless') {
        this.displayFlowType = 'touchless';
        // A bare dashboard load and a Touchless deep link both stay on the
        // report's lightweight endpoints. Flow-data starts only if the user
        // later opens an analytics tab.
        this.syncTabQuery('touchless');
        return;
      }

      this.displayFlowType = initial;
      this.selectedFlowType = initial;
      this.initializeDashboard();
    },

    /** `?tab=` if it names a tab this user may actually see, else null. */
    readTabFromQuery(): AnalyticsTabValue | null {
      const raw = this.$route?.query?.[TAB_QUERY_KEY];
      const value = Array.isArray(raw) ? raw[0] : raw;
      if (typeof value !== 'string') return null;
      const allowed = this.flowTypeOptions.map((option) => option.value);
      return allowed.includes(value as AnalyticsTabValue)
        ? (value as AnalyticsTabValue)
        : null;
    },

    /** Mirrors the active tab into the URL so it can be shared and restored. */
    syncTabQuery(value: AnalyticsTabValue) {
      const current = this.$route?.query?.[TAB_QUERY_KEY];
      if (current === value) return;
      void this.$router
        .replace({
          query: { ...(this.$route?.query || {}), [TAB_QUERY_KEY]: value },
        })
        // A redundant navigation is not an error worth surfacing.
        .catch(() => undefined);
    },

    flowTypeIcon(value: string): string {
      switch (value) {
        case 'status':
          return 'swap_horiz';
        case 'modules':
          return 'settings';
        case 'user':
          return 'person';
        case 'touchless':
          return 'touch_app';
        default:
          return 'category';
      }
    },

    // Save current filter state for the active tab
    _saveTabFilterState() {
      const state: TabFilterState = {
        selectedSubOrg: [...this.selectedSubOrg],
        prevSelectedSubOrg: [...this.prevSelectedSubOrg],
        selectedDocType: [...this.selectedDocType],
        prevSelectedDocType: [...this.prevSelectedDocType],
        selectedSupplier: [...this.selectedSupplier],
        prevSelectedSupplier: [...this.prevSelectedSupplier],
        selectedAssignedGroup: [...this.selectedAssignedGroup],
        prevSelectedAssignedGroup: [...this.prevSelectedAssignedGroup],
        selectedSteps: [...this.selectedSteps],
        prevSelectedSteps: [...this.prevSelectedSteps],
        documentSearch: this.documentSearch,
        documentSearchInput: this.documentSearchInput,
        chartGroupBy: this.chartGroupBy,
        timeChartGroupBy: this.timeChartGroupBy,
        hiddenDocumentIds: new Set(this.hiddenDocumentIds),
        selectedServices: new Set(this.selectedServices),
        topDocumentsSortOrder: this.topDocumentsSortOrder,
      };
      this._tabFilterStates.set(this.selectedFlowType, state);
    },

    // Restore filter state for a tab, or apply defaults
    _restoreTabFilterState(tab: string) {
      const state = this._tabFilterStates.get(tab);
      if (state) {
        this.selectedSubOrg = [...state.selectedSubOrg];
        this.prevSelectedSubOrg = [...state.prevSelectedSubOrg];
        this.selectedDocType = [...state.selectedDocType];
        this.prevSelectedDocType = [...state.prevSelectedDocType];
        this.selectedSupplier = [...state.selectedSupplier];
        this.prevSelectedSupplier = [...state.prevSelectedSupplier];
        this.selectedAssignedGroup = [...state.selectedAssignedGroup];
        this.prevSelectedAssignedGroup = [...state.prevSelectedAssignedGroup];
        this.selectedSteps = [...state.selectedSteps];
        this.prevSelectedSteps = [...state.prevSelectedSteps];
        this.documentSearch = state.documentSearch;
        this.documentSearchInput = state.documentSearchInput;
        this.chartGroupBy = state.chartGroupBy as any;
        this.timeChartGroupBy = state.timeChartGroupBy as any;
        this.hiddenDocumentIds = new Set(state.hiddenDocumentIds);
        this.selectedServices = new Set(state.selectedServices);
        this.topDocumentsSortOrder = state.topDocumentsSortOrder as any;
      } else {
        // Apply defaults for a tab visited for the first time
        const defaults = createDefaultTabFilterState();
        this.selectedSubOrg = defaults.selectedSubOrg;
        this.prevSelectedSubOrg = defaults.prevSelectedSubOrg;
        this.selectedDocType = defaults.selectedDocType;
        this.prevSelectedDocType = defaults.prevSelectedDocType;
        this.selectedSupplier = defaults.selectedSupplier;
        this.prevSelectedSupplier = defaults.prevSelectedSupplier;
        this.selectedAssignedGroup = defaults.selectedAssignedGroup;
        this.prevSelectedAssignedGroup = defaults.prevSelectedAssignedGroup;
        this.selectedSteps = defaults.selectedSteps;
        this.prevSelectedSteps = defaults.prevSelectedSteps;
        this.documentSearch = defaults.documentSearch;
        this.documentSearchInput = defaults.documentSearchInput;
        this.chartGroupBy = defaults.chartGroupBy as any;
        this.timeChartGroupBy = defaults.timeChartGroupBy as any;
        this.hiddenDocumentIds = new Set(defaults.hiddenDocumentIds);
        this.selectedServices = new Set(defaults.selectedServices);
        this.topDocumentsSortOrder = defaults.topDocumentsSortOrder as any;
      }
    },

    // Handle flow type change - INSTANT (frontend only, no API call needed)
    // Backend returns all flow types, frontend just switches which one to display
    handleFlowTypeChange(newValue: AnalyticsTabValue) {
      // Touchless is not a flow type: it reads its own endpoints and shares no
      // state with the flow-data machinery. Moving `selectedFlowType` to it
      // would send every flow computed looking for `by_flow_type.touchless`,
      // find nothing, and wipe the analytics tab's selection on the way back.
      // So only the tab indicator moves.
      if (newValue === 'touchless') {
        // Any analytics response still in flight now belongs to a tab nobody is
        // looking at; bumping the token stops it committing behind Touchless.
        this.analyticsRequestGeneration++;
        this.displayFlowType = newValue;
        this.syncTabQuery(newValue);
        return;
      }

      // Switch tab indicator immediately (display only, no heavy recomputation).
      // MUST happen before initializeDashboard(): the initializer loads for the
      // ACTIVE tab, so initialising while `displayFlowType` still said
      // 'touchless' requested nothing and yet marked itself done.
      this.displayFlowType = newValue;
      this.syncTabQuery(newValue);

      // Coming back from Touchless (or arriving via ?tab=touchless first): the
      // analytics side may never have been initialised.
      this.initializeDashboard();
      // Show loader, then delay the actual data change so the loader paints first
      this.processing = true;

      // Save current tab's filter state before switching
      this._saveTabFilterState();

      this.$nextTick(() => {
        setTimeout(() => {
          // Restore the target tab's filter state before changing flow type
          // so the watcher knows to skip rebuild
          const hasSavedState = this._tabFilterStates.has(newValue);
          if (hasSavedState) {
            this._skipFlowTypeWatcher = true;
          }
          this._restoreTabFilterState(newValue);
          this.selectedFlowType = newValue;
          this.topDocsCurrentPage = 1;
          this.$nextTick(() => {
            this.processing = false;
          });
        }, 50);
      });
    },

    // Jump to a specific page in top documents list
    jumpToTopDocsPage() {
      const page = Math.max(
        1,
        Math.min(this.topDocsPageInput || 1, this.topDocsTotalPages),
      );
      this.topDocsCurrentPage = page;
      this.topDocsPageInput = page;
    },

    // Handle Steps multi-select change - IMMEDIATE (frontend only, no API call needed).
    // Drives two effects:
    //   1. Visibility — `visibleFlowElements` hides cards whose base isn't
    //      in `selectedSteps`.
    //   2. Metric recalculation — mirrors the selection into `selectedServices`
    //      so downstream stats (time trend, top docs, table, averages) exclude
    //      the deselected steps, same as the sub-org / doc-type dropdowns.
    // Card clicks remain one-way: they only adjust `selectedServices` (grey-out)
    // and do NOT collapse the dropdown.
    handleStepsChange(newValue: string[]) {
      this.handleMultiSelectChange(
        newValue,
        ALL_FILTER_VALUE,
        'prevSelectedSteps',
        'selectedSteps',
      );

      if (this.selectedSteps.includes(ALL_FILTER_VALUE)) {
        // All steps visible → all visible services selected for metrics.
        const visibleServiceNames = (this.elements as any[]).map(
          (el) => el.name,
        );
        this.selectedServices = new Set(visibleServiceNames);
      } else {
        const allowedBases = new Set(this.selectedSteps);
        const next = new Set<string>();
        for (const el of this.elements as any[]) {
          const baseName = el.name.includes('::')
            ? el.name.split('::')[0]
            : el.name;
          if (allowedBases.has(baseName)) next.add(el.name);
        }
        this.selectedServices = next;
      }
    },

    // Column visibility drag-and-drop methods

    // Drag from table header to hide column
    onTableDragStart(event: DragEvent) {
      const target = event.target as HTMLElement;
      const th = target.closest('th[data-col-name]') as HTMLElement;
      if (th) {
        const columnName = th.getAttribute('data-col-name');
        if (
          columnName &&
          columnName !== '__selection__' &&
          columnName !== '__actions__'
        ) {
          this.draggedColumnName = columnName;
          this.dragSource = 'table';
        }
      }
    },

    // Drag from hidden column chip to restore column
    onHiddenColumnDragStart(event: DragEvent, columnName: string) {
      this.draggedColumnName = columnName;
      this.dragSource = 'hidden';
      event.dataTransfer?.setData('text/plain', columnName);
    },

    // Common drag end handler
    onDragEnd() {
      this.isDraggingToHide = false;
      this.isDraggingToRestore = false;
      this.draggedColumnName = null;
      this.dragSource = null;
    },

    // Drag over handler (common)
    onColumnDragOver(event: DragEvent) {
      event.preventDefault();
      if (event.dataTransfer) {
        event.dataTransfer.dropEffect = 'move';
      }
    },

    // Hide zone (left side) - accepts drags from table
    onHideZoneDragEnter(event: DragEvent) {
      event.preventDefault();
      if (this.dragSource === 'table') {
        this.isDraggingToHide = true;
      }
    },

    onHideZoneDragLeave(event: DragEvent) {
      const relatedTarget = event.relatedTarget as HTMLElement;
      const dropZone = event.currentTarget as HTMLElement;
      if (!dropZone.contains(relatedTarget)) {
        this.isDraggingToHide = false;
      }
    },

    onHideZoneDrop(event: DragEvent) {
      event.preventDefault();
      this.isDraggingToHide = false;

      // Only hide if dragged from table
      if (this.dragSource === 'table' && this.draggedColumnName) {
        if (!this.hiddenColumnNames.includes(this.draggedColumnName)) {
          this.hiddenColumnNames.push(this.draggedColumnName);
        }
      }
      this.draggedColumnName = null;
      this.dragSource = null;
    },

    // Table zone (right side) - accepts drags from hidden chips
    onTableDragOver(event: DragEvent) {
      event.preventDefault();
      if (event.dataTransfer) {
        event.dataTransfer.dropEffect = 'move';
      }
    },

    onTableDragEnter(event: DragEvent) {
      event.preventDefault();
      if (this.dragSource === 'hidden') {
        this.isDraggingToRestore = true;
      }
    },

    onTableDragLeave(event: DragEvent) {
      const relatedTarget = event.relatedTarget as HTMLElement;
      const dropZone = event.currentTarget as HTMLElement;
      if (!dropZone.contains(relatedTarget)) {
        this.isDraggingToRestore = false;
      }
    },

    onTableDrop(event: DragEvent) {
      event.preventDefault();
      this.isDraggingToRestore = false;

      // Only restore if dragged from hidden zone
      if (this.dragSource === 'hidden' && this.draggedColumnName) {
        this.restoreColumn(this.draggedColumnName);
      }
      this.draggedColumnName = null;
      this.dragSource = null;
    },

    restoreColumn(columnName: string) {
      const index = this.hiddenColumnNames.indexOf(columnName);
      if (index > -1) {
        this.hiddenColumnNames.splice(index, 1);
      }
    },

    downloadTableCSV() {
      if (this.tableElements.length === 0) return;

      // Generate filename with current date
      const today = new Date();
      const dateStr = formatDate(today);
      const filename = `analytics_export_${dateStr}.csv`;

      // Use the visible columns for export
      const exportColumns = this.visibleTableColumns;

      try {
        // Export using the CSV utility
        const result = csvExportUtil.methods.createAndExportCSV(
          this.tableElements,
          exportColumns,
          filename,
        );

        if (result) {
          notify.success(this.$t('download') + ' CSV');
        } else {
          notify.error(this.$t('error'));
        }
      } catch (error) {
        console.error('CSV export failed:', error);
        notify.error(this.$t('error'));
      }
    },
  },
});
</script>

