<template>
  <div class="touchless-filter-bar row items-center wrap">
    <q-btn-toggle
      :model-value="filters.period"
      toggle-color="primary"
      class="toggle_time dashboard-text-color back-white"
      :ripple="false"
      :options="periodOptions"
      data-test="touchless-period-toggle"
      @update:model-value="onPeriodChange"
    />

    <q-select
      v-if="docTypeOptions.length"
      :model-value="filters.doc_type"
      outlined
      dense
      clearable
      emit-value
      map-options
      behavior="menu"
      :options="docTypeSelectOptions"
      :label="$t('document_type')"
      class="select-box q-ml-md"
      data-test="touchless-doc-type-select"
      @update:model-value="onDocTypeChange"
    />
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { TOUCHLESS_PERIOD_OPTIONS } from 'src/store/touchless-intelligence.store';
import type { TouchlessFilters } from 'src/store/touchless-intelligence.store';
import type { TouchlessDocTypeOption } from 'src/services/analytics/TouchlessService';

/**
 * Phase A filter dimensions are period + doc type. Doc-type options come from
 * `available_filters.doc_types` in the summary response; a dimension the
 * backend has no values for is hidden entirely rather than shown as an empty
 * dropdown.
 *
 * Supplier is deliberately not a filter here. Scoping the whole dashboard to a
 * single supplier would make the headline rate mean something different from
 * the number the same page reports elsewhere. The supplier view is a
 * drill-down: click a row in the opportunity queue.
 *
 * The period preset labels mirror `AnalyticsTimeFilter.vue`; that component is
 * hard-coupled to the dashboard store, so the mapping is copied, not reused.
 */
const PERIOD_LABEL_KEYS: Record<string, string> = {
  '7d': '7_days',
  '30d': '30_days',
  '90d': '3_months',
};

export default defineComponent({
  name: 'TouchlessFilterBar',

  props: {
    filters: {
      type: Object as PropType<TouchlessFilters>,
      required: true,
    },
    docTypeOptions: {
      type: Array as PropType<TouchlessDocTypeOption[]>,
      default: () => [],
    },
  },

  emits: ['change'],

  computed: {
    periodOptions(): { label: string; value: string }[] {
      return TOUCHLESS_PERIOD_OPTIONS.map((period) => ({
        label: this.$t(PERIOD_LABEL_KEYS[period] || period) as string,
        value: period,
      }));
    },

    docTypeSelectOptions(): { label: string; value: string }[] {
      return this.docTypeOptions.map((option) => ({
        label: option.doc_type_name || option.doc_type,
        value: option.doc_type,
      }));
    },
  },

  methods: {
    onPeriodChange(period: string): void {
      if (!period || period === this.filters.period) return;
      this.$emit('change', { period });
    },

    onDocTypeChange(docType: string | null): void {
      this.$emit('change', { doc_type: docType || null });
    },
  },
});
</script>

