<template>
  <div v-if="currentCard.type !== 'placeholder'" class="card-container">
    <div :class="cardClasses">
      <div :class="['icon-wrapper', { 'dark-mode': isDarkMode }]">
        <div :class="['icon', iconClass]">
          <img
            :src="iconSrc"
            :alt="`${currentCard.label || currentCard.name || 'flow'} icon`"
            @error="onIconError"
          />
        </div>
      </div>
      <h3>{{ formattedLabel }}</h3>
      <div v-if="showDetail" class="bottom-section">
        <q-separator
          class="separator"
          size="1.5px"
        />
        <div class="info-row">
          <div class="info-block">
            <div class="info-row">
              <div class="label">{{ $t('max_time') }}</div>
              <div class="value">{{ currentCard.maxTime }}</div>
            </div>
            <div class="info-row">
              <div :class="['label', avgTimeColorClass]">{{ $t('avg_time') }}</div>
              <div :class="['value', avgTimeColorClass]">{{ currentCard.avgTime }}</div>
            </div>
            <div class="info-row">
              <div class="label">{{ $t('min_time') }}</div>
              <div class="value">{{ currentCard.minTime }}</div>
            </div>
          </div>
        </div>
        <q-separator
          :class="['separator', 'system-separator', { 'separator-no-avg': !showDocbitsAverage || !hasSystemAvg }]"
          size="1.5px"
        />
        <div v-if="showDocbitsAverage && hasSystemAvg" class="info-row system-avg-row">
          <div class="info-block">
            <div class="info-row">
              <div class="label system-label"><img src="/icons/LOGO.svg" alt="DocBits" class="docbits-logo" /> {{ $t('global_average') }}</div>
              <div class="value system-value">{{ currentCard.systemAvg }}</div>
            </div>
          </div>
        </div>
      </div>

      <!-- Selection circle integrated into bottom border -->
      <button
        v-if="showDetail"
        type="button"
        :class="['selection-circle', { 'selected': isSelected, 'dark-mode': isDarkMode }]"
        @click="$emit('toggle-selection', currentCard)"
        :aria-pressed="isSelected"
        :aria-label="isSelected ? $t('unselect') : $t('select')"
        >
        <q-icon v-if="isSelected" name="check" size="12px" color="white" />
        </button>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, PropType } from 'vue';
import { formatServiceLabel, computeAvgTimeColorClass, resolveDocFlowIcon } from './analyticsUtils';

const DEFAULT_ICON = '/images/docflow/field_extraction.svg';

export interface FlowCard {
  type?: string;
  name?: string;
  label?: string;
  avgTime?: string;
  minTime?: string;
  maxTime?: string;
  systemAvg?: string | null;
  _avgTimeRaw?: number;
  _systemAvgRaw?: number;
}

export default defineComponent({
  name: 'AnalyticsFlowCard',
  props: {
    currentCard: {
      type: Object as PropType<FlowCard>,
      required: true,
    },
    showDetail: {
      type: Boolean,
      default: false,
    },
    isSelected: {
      type: Boolean,
      default: false,
    },
    showDocbitsAverage: {
      type: Boolean,
      default: true,
    },
  },
  emits: ['toggle-selection'],
  data() {
    return {
      iconLoadFailed: false,
    };
  },
  computed: {
    isDarkMode() {
      return this.$q.dark.isActive;
    },
    normalizedName() {
      const name = this.currentCard.name;
      if (!name || typeof name !== 'string') {
        return null;
      }
      return name.toUpperCase();
    },
    formattedLabel() {
      if (this.normalizedName?.startsWith('STATUS_')) {
        return formatServiceLabel(this.currentCard.name, this.$t);
      }
      // For non-status cards, use the label as-is
      return this.currentCard.label;
    },
    iconSrc() {
      if (this.iconLoadFailed) {
        return DEFAULT_ICON;
      }
      return resolveDocFlowIcon(this.currentCard.name);
    },
    hasSystemAvg() {
      return this.currentCard.systemAvg !== undefined && this.currentCard.systemAvg !== null;
    },
    cardClasses() {
      return {
        'card': true,
        'selected': this.isSelected,
        'dark-mode': this.isDarkMode,
        'compact': !this.showDocbitsAverage
      };
    },
    iconClass() {
      return 'normal-icon';
    },
    // Color class for avg time based on comparison with system average
    // Uses raw numeric values when available (from _avgTimeRaw, _systemAvgRaw props)
    // Falls back to parsing formatted strings via cached utility function
    avgTimeColorClass() {
      // Prefer raw values if available (passed from parent for performance)
      const avgValue = this.currentCard._avgTimeRaw !== undefined
        ? this.currentCard._avgTimeRaw
        : this.currentCard.avgTime;
      const systemValue = this.currentCard._systemAvgRaw !== undefined
        ? this.currentCard._systemAvgRaw
        : this.currentCard.systemAvg;

      return computeAvgTimeColorClass(avgValue, systemValue, this.showDocbitsAverage);
    }
  },
  watch: {
    'currentCard.name'() {
      this.iconLoadFailed = false;
    }
  },
  methods: {
    onIconError(event: Event) {
      if (!this.iconLoadFailed) {
        this.iconLoadFailed = true;
        (event.target as HTMLImageElement).src = DEFAULT_ICON;
      }
    },
  },
});
</script>

