<template>
  <q-drawer
    :model-value="open"
    @update:model-value="$emit('close')"
    side="right"
    overlay
    bordered
    :width="440"
    data-test="touchless-methodology-drawer"
  >
    <q-scroll-area class="fit">
      <div class="q-pa-md">
        <div class="row items-center q-mb-md">
          <div class="text-h6">{{ $t('touchless_how_calculated') }}</div>
          <q-space />
          <q-btn
            flat
            dense
            round
            icon="close"
            :aria-label="$t('close')"
            data-test="touchless-methodology-close"
            @click="$emit('close')"
          />
        </div>

        <!-- The denominator, stated first: every rate below is a share of it,
             and it is the part people get wrong when they compare numbers. -->
        <q-card flat bordered class="q-mb-md">
          <q-card-section>
            <div class="text-subtitle2 q-mb-xs">
              {{ $t('touchless_method_denominator_title') }}
            </div>
            <div class="text-body2 q-mb-sm">
              {{ $t('touchless_method_denominator_body') }}
            </div>
            <div class="method-formula">
              PURE + AP_TOUCHLESS + AP_ASSISTED + PROCESS_EXCEPTION
            </div>
          </q-card-section>
        </q-card>

        <!-- Worked with THIS org's current numbers, not an example. A formula
             nobody can reconcile against the tiles above it is decoration. -->
        <q-card
          v-if="population"
          flat
          bordered
          class="q-mb-md"
          data-test="touchless-methodology-worked"
        >
          <q-card-section>
            <div class="text-subtitle2 q-mb-sm">
              {{ $t('touchless_method_your_numbers') }}
            </div>
            <div
              v-for="row in workedExample"
              :key="row.key"
              class="row justify-between items-center q-py-xs"
              :class="row.emphasis ? 'text-weight-medium' : 'text-grey-8'"
            >
              <div class="text-body2">{{ row.label }}</div>
              <div class="text-body2">{{ row.value }}</div>
            </div>
          </q-card-section>
        </q-card>

        <q-card flat bordered class="q-mb-md">
          <q-card-section>
            <div class="text-subtitle2 q-mb-sm">
              {{ $t('touchless_method_buckets_title') }}
            </div>
            <div
              v-for="bucket in bucketExplanations"
              :key="bucket.key"
              class="q-mb-sm"
            >
              <div class="row items-center q-gutter-xs">
                <q-badge :color="bucket.color" class="q-mr-xs" />
                <span class="text-weight-medium text-body2">
                  {{ $t(bucket.labelKey) }}
                </span>
              </div>
              <div class="text-body2 text-grey-8 q-ml-md">
                {{ $t(bucket.bodyKey) }}
              </div>
            </div>
          </q-card-section>
        </q-card>

        <q-card flat bordered class="q-mb-md">
          <q-card-section>
            <div class="text-subtitle2 q-mb-sm">
              {{ $t('touchless_method_sticky_title') }}
            </div>
            <div class="text-body2 text-grey-8">
              {{ $t('touchless_method_sticky_body') }}
            </div>
          </q-card-section>
        </q-card>

        <!-- Where a stated cause comes from. Without this, a model's guess and
             a rule's finding look identical on the card, and the reader has no
             way to know which of the two they are about to act on. -->
        <q-card
          flat
          bordered
          class="q-mb-md"
          data-test="touchless-methodology-advice"
        >
          <q-card-section>
            <div class="text-subtitle2 q-mb-sm">
              {{ $t('touchless_method_advice_title') }}
            </div>
            <div class="text-body2 text-grey-8 q-mb-sm">
              {{ $t('touchless_method_advice_body') }}
            </div>
            <div
              v-for="provenance in provenanceExplanations"
              :key="provenance.key"
              class="row items-start q-gutter-xs q-mb-xs"
            >
              <q-icon
                :name="provenance.icon"
                :color="provenance.color"
                size="16px"
                class="q-mt-xs"
              />
              <div class="col">
                <span class="text-weight-medium text-body2">
                  {{ $t(provenance.labelKey) }}
                </span>
                <div class="text-body2 text-grey-8">
                  {{ $t(provenance.bodyKey) }}
                </div>
              </div>
            </div>
          </q-card-section>
        </q-card>

        <q-card flat bordered>
          <q-card-section>
            <div class="text-subtitle2 q-mb-sm">
              {{ $t('touchless_method_freshness_title') }}
            </div>
            <div class="text-body2 text-grey-8">
              {{ $t('touchless_method_freshness_body') }}
            </div>
          </q-card-section>
        </q-card>
      </div>
    </q-scroll-area>
  </q-drawer>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import type {
  TouchlessBuckets,
  MetricPopulation,
} from 'src/services/analytics/TouchlessService';
import {
  formatTouchlessPct,
  provenanceColor,
  provenanceIcon,
} from 'src/utils/touchless-format';

/**
 * How the touchless rate is calculated, explained where it is read.
 *
 * The number on a KPI tile is only trustworthy if the reader can reconstruct
 * it. Two things in particular are not guessable from the tile:
 *
 *  * the DENOMINATOR is terminal documents only — documents still in flight
 *    are excluded, so an org with thousands in progress and forty finished has
 *    a rate over forty, not over thousands. Without saying so, a low rate
 *    looks like a catastrophe instead of a small sample.
 *  * `human_touched` is STICKY. One correction marks a document for good, even
 *    if a later automatic re-run needs no one. That is deliberate — the work
 *    happened — but it surprises people who restart a document and expect the
 *    rate to recover.
 *
 * The worked example uses the org's OWN current numbers rather than an
 * illustration, so the arithmetic can be checked against the tiles beside it.
 */
export default defineComponent({
  name: 'TouchlessMethodologyDrawer',

  props: {
    open: { type: Boolean, default: false },
    buckets: {
      type: Object as PropType<TouchlessBuckets | null>,
      default: null,
    },
    population: {
      type: Object as PropType<MetricPopulation | null>,
      default: null,
    },
    purePct: { type: Number as PropType<number | null>, default: null },
    apPct: { type: Number as PropType<number | null>, default: null },
  },

  emits: ['close'],

  computed: {
    /** The four buckets that make up the denominator, in report order. */
    bucketDefinitions(): { key: string; color: string }[] {
      return [
        { key: 'PURE_TOUCHLESS', color: 'positive' },
        { key: 'AP_TOUCHLESS', color: 'teal' },
        { key: 'AP_ASSISTED', color: 'warning' },
        { key: 'PROCESS_EXCEPTION', color: 'negative' },
        { key: 'IN_PROGRESS', color: 'grey-5' },
        { key: 'NOT_ELIGIBLE', color: 'grey-4' },
      ];
    },

    /**
     * The three provenances a cause can carry, with the SAME icon and colour
     * the chip on the card uses — the drawer is the legend for that chip, so
     * both have to come from one definition or the legend stops matching.
     */
    provenanceExplanations(): {
      key: string;
      icon: string;
      color: string;
      labelKey: string;
      bodyKey: string;
    }[] {
      return ['DETERMINISTIC', 'AGENT_HYPOTHESIS', 'HUMAN_CONFIRMED'].map(
        (key) => ({
          key,
          icon: provenanceIcon(key),
          color: provenanceColor(key),
          labelKey: `touchless_provenance_${key.toLowerCase()}`,
          bodyKey: `touchless_provenance_hint_${key.toLowerCase()}`,
        }),
      );
    },

    /** Named distinctly from the `buckets` PROP, which is the count map. */
    bucketExplanations(): {
      key: string;
      color: string;
      labelKey: string;
      bodyKey: string;
    }[] {
      return this.bucketDefinitions.map((b) => ({
        ...b,
        labelKey: `touchless_bucket_${b.key.toLowerCase()}`,
        bodyKey: `touchless_method_${b.key.toLowerCase()}`,
      }));
    },

    /**
     * The org's own arithmetic, line by line.
     *
     * `count` is read straight off the buckets so the drawer cannot drift
     * from the tiles: if they disagree, the drawer is showing the same source
     * and the bug is upstream of both.
     */
    workedExample(): {
      key: string;
      label: string;
      value: string;
      emphasis?: boolean;
    }[] {
      const count = (key: string): number =>
        (this.buckets && this.buckets[key]?.count) || 0;

      const denominator =
        count('PURE_TOUCHLESS') +
        count('AP_TOUCHLESS') +
        count('AP_ASSISTED') +
        count('PROCESS_EXCEPTION');

      const rows = [
        {
          key: 'total',
          label: this.$t('touchless_method_row_total') as string,
          value: String(this.population?.total ?? 0),
        },
        {
          key: 'in_progress',
          label: this.$t('touchless_method_row_in_progress') as string,
          value: `− ${count('IN_PROGRESS')}`,
        },
        {
          key: 'not_eligible',
          label: this.$t('touchless_method_row_excluded') as string,
          value: `− ${this.population?.excluded?.count ?? 0}`,
        },
        {
          key: 'denominator',
          label: this.$t('touchless_method_row_denominator') as string,
          value: String(denominator),
          emphasis: true,
        },
        {
          key: 'pure',
          label: this.$t('touchless_method_row_pure') as string,
          value: `${count('PURE_TOUCHLESS')} → ${formatTouchlessPct(
            this.purePct,
          )}`,
          emphasis: true,
        },
        {
          key: 'ap',
          label: this.$t('touchless_method_row_ap') as string,
          value: `${
            count('PURE_TOUCHLESS') + count('AP_TOUCHLESS')
          } → ${formatTouchlessPct(this.apPct)}`,
          emphasis: true,
        },
      ];
      return rows;
    },
  },
});
</script>

