    -->
    <div
      v-if="bulkScopeHintVisible"
      class="bulk-scope-hint q-mb-md"
      data-test="touchless-bulk-scope-hint"
    >
      {{ bulkScopeHint }}
    </div>

    <!--
      DOCB-14333. When most of the window's loss cannot be attributed to any
      supplier, that is a finding in its own right — supplier recognition is
      not working — and it belongs on screen as one. Before this it was only
      visible as the word "unknown" at the top of every result row, which
