      Above the results and the tiles because it qualifies both: a
      per-supplier report whose supplier dimension is 99 % one bucket is a
      report the reader has to know how to read.
    -->
    <q-banner
      v-if="unresolvedSupplierFinding"
      dense
      class="unresolved-supplier-hint q-mb-md"
      data-test="touchless-unresolved-supplier-hint"
    >
      <template #avatar>
        <q-icon name="person_search" color="warning" />
      </template>
      <div class="unresolved-supplier-title">
        {{ $t('touchless_supplier_recognition_title') }}
      </div>
      <div class="unresolved-supplier-body">
        {{
          $t('touchless_supplier_recognition_hint', {
            count: unresolvedSupplierShare.unresolved,
            total: unresolvedSupplierShare.total,
          })
        }}
      </div>
      <template #action>
        <q-btn
          flat
          dense
          no-caps
          size="sm"
          color="primary"
          :label="$t('touchless_supplier_recognition_action')"
          data-test="touchless-unresolved-supplier-action"
          @click="openSupplierMasterData"
        />
      </template>
    </q-banner>

    <!--
      What the bulk run analysed (DOCB-14311). Above the KPI row because it is
      the ANSWER to the click that started it — a result the reader has to
      scroll past the whole dashboard to find is the dead end this replaces.

      No longer "until a run has been dispatched in this tab" (DOCB-14328):
      the last run is restored on mount, so leaving the page and coming back
      finds the list where it was left.
    -->
    <BulkAnalysisResults
      v-if="bulkResultsVisible"
      ref="bulkResults"
      :entries="store.bulkResultEntries"
      @open="openBulkResult"
      @dismiss="store.dismissBulkResults()"
    />

    <!--
      KPI row. Every tile is a drill-down to the documents its number was
