    -->
    <div class="kpi-row q-mb-md" data-test="touchless-kpi-row">
      <TouchlessKpiCard
        :label="$t('touchless_kpi_pure')"
        :value="formatPct(store.purePct)"
        :numeric-value="store.purePct"
        :target="store.targetPct"
        :subtitle="
          $t('touchless_documents_count', {
            count: store.bucketCount('PURE_TOUCHLESS'),
