        "
        icon="mdi:gesture-tap-button"
        data-test="touchless-kpi-pure"
        :to="bucketDrilldown('PURE_TOUCHLESS')"
        :link-title="drilldownTitle"
      />
      <TouchlessKpiCard
        :label="$t('touchless_kpi_ap')"
        :value="formatPct(store.apPct)"
        :subtitle="
          $t('touchless_documents_count', {
            count: store.bucketCount('AP_TOUCHLESS'),
          })
        "
        icon="mdi:check-decagram-outline"
        data-test="touchless-kpi-ap"
        :to="bucketDrilldown('AP_TOUCHLESS')"
        :link-title="drilldownTitle"
      />
      <TouchlessKpiCard
        :label="$t('touchless_kpi_ap_assisted')"
        :value="store.bucketCount('AP_ASSISTED')"
        :subtitle="formatPct(store.bucketPct('AP_ASSISTED'))"
        icon="mdi:account-edit"
        data-test="touchless-kpi-ap-assisted"
        :to="bucketDrilldown('AP_ASSISTED')"
        :link-title="drilldownTitle"
      />
      <TouchlessKpiCard
        :label="$t('touchless_kpi_exceptions')"
        :value="store.bucketCount('PROCESS_EXCEPTION')"
        :subtitle="formatPct(store.bucketPct('PROCESS_EXCEPTION'))"
        icon="mdi:alert-circle-outline"
        data-test="touchless-kpi-exceptions"
        :to="bucketDrilldown('PROCESS_EXCEPTION')"
        :link-title="drilldownTitle"
      />
      <!--
        The fifth tile shows a RATE but its drill-down is the subtitle's
        count: the documents whose loss has no known cause. That is
        `first_blocking_reason_code == UNKNOWN`, not a bucket, so it travels as
        its own param.
      -->
      <TouchlessKpiCard
        :label="$t('touchless_kpi_diagnosed')"
        :value="formatPct(store.diagnosedPct)"
        :subtitle="
          $t('touchless_unknown_count', { count: store.undiagnosedCount })
        "
        icon="mdi:magnify"
        data-test="touchless-kpi-diagnosed"
        :to="undiagnosedDrilldown"
        :link-title="drilldownTitle"
      />
    </div>

    <div class="touchless-widget-grid">
      <TouchlessTrendChart
        :points="store.trend?.points || []"
        :target="store.targetPct"
        :loading="store.trendLoading"
        :error="store.trendError"
        @retry="retrySection('trend')"
      />
      <BlockingStageChart
        :stages="store.blockingStages"
        :loading="store.summaryLoading"
        :error="store.summaryError"
        @retry="retrySection('summary')"
      />
    </div>

    <SupplierQueueTable
      class="q-mt-md"
      :rows="store.suppliers"
      :pagination="store.supplierPagination"
      :total-rows="store.supplierCount"
      :loading="store.suppliersLoading"
      :error="store.suppliersError"
      :target="store.targetPct"
      @sort="onSupplierSort"
      @page="onSupplierPage"
      @select-supplier="openSupplier"
      @retry="retrySection('suppliers')"
    />

    <MetricContractFooter
      :data-as-of="store.dataAsOf"
      :contract-version="store.metricContractVersion"
      :population="store.summary?.population || null"
    />

    <TouchlessMethodologyDrawer
      :open="methodologyOpen"
      :buckets="store.summary?.buckets || null"
      :population="store.summary?.population || null"
      :pure-pct="store.purePct"
      :ap-pct="store.apPct"
      @close="methodologyOpen = false"
    />
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useTouchlessAccess } from 'src/composables/useTouchlessAccess';
import {
  formatTouchlessDateTime,
  formatTouchlessPct,
} from 'src/utils/touchless-format';
import { notify } from 'src/components/notifications/notify';
import { logger } from 'src/utils/logger';
import { touchlessService } from 'src/services';
import type {
  TouchlessBulkAdvicePreview,
  TouchlessSubOrgScope,
} from 'src/services/analytics/TouchlessService';
import { useTouchlessIntelligenceStore } from 'src/store/touchless-intelligence.store';
import type {
  TouchlessFilters,
  TouchlessSection,
} from 'src/store/touchless-intelligence.store';
import TouchlessFilterBar from './components/TouchlessFilterBar.vue';
import TouchlessKpiCard from './components/TouchlessKpiCard.vue';
import MetricContractFooter from './components/MetricContractFooter.vue';
import TouchlessMethodologyDrawer from './components/TouchlessMethodologyDrawer.vue';
import TouchlessTrendChart from './components/charts/TouchlessTrendChart.vue';
import BlockingStageChart from './components/charts/BlockingStageChart.vue';
import SupplierQueueTable from './components/SupplierQueueTable.vue';
import BulkAnalysisResults from './components/BulkAnalysisResults.vue';
import { unresolvedSupplierShare } from 'src/utils/touchless-supplier';
import type { TouchlessUnresolvedShare } from 'src/utils/touchless-supplier';
import { TOUCHLESS_SUPPLIER_ROUTE } from 'src/router/touchless-routes';
import type { TouchlessBulkResultEntry } from 'src/utils/touchless-bulk-results';
import {
  buildTouchlessDrilldownLocation,
  touchlessWindowDays,
  type TouchlessDrilldownBucket,
  type TouchlessDrilldownLocation,
} from './touchlessDrilldown';

/**
 * Seconds one cluster's AI analysis takes, for the button's own promise
 * (DOCB-14313).
 *
 * MEASURED, not assumed: a cold run of six clusters took ~81 s end to end on
 * dev (02.09.2026), and the worker analyses them one at a time. Rounded down
 * to 13 so the estimate under-promises rather than over-promises — a job that
 * finishes early is a pleasant surprise, one that runs long reads as a hang.
 */
const TOUCHLESS_BULK_SECONDS_PER_CLUSTER = 13;

/**
 * Touchless Intelligence, rendered inside the Analytics Dashboard's tab bar
 * rather than on a page of its own.
 *
 * It is a panel, not a page: the host supplies the SubHeader, the admin gate
 * and the q-page wrapper. What stays here is everything specific to touchless —
 * its own filter bar (period + doc type; the host's flow-type filters are
 * meaningless here), its KPI row, its charts and its metric footer.
 *
 * The host mounts this only while the touchless tab is active AND the org flag
 * is on, so no touchless request can fire from an analytics tab. `load()` still
 * re-checks the gate itself.
 */
export default defineComponent({
  name: 'TouchlessIntelligencePanel',

  components: {
    TouchlessFilterBar,
    TouchlessKpiCard,
    MetricContractFooter,
    TouchlessMethodologyDrawer,
    TouchlessTrendChart,
    BlockingStageChart,
    SupplierQueueTable,
    BulkAnalysisResults,
  },

  setup() {
    const store = useTouchlessIntelligenceStore();
    const { accessGranted, checkAccess, ensureSettingsLoaded } =
      useTouchlessAccess();
    return { store, accessGranted, checkAccess, ensureSettingsLoaded };
  },

  data() {
    return {
      hasLoaded: false,
      methodologyOpen: false,
      /**
       * The backend's answer to "how many clusters would a click analyse".
       * `null` until the preview lands, which is what keeps the button off
       * screen instead of flashing "Analyse 0 clusters" on every mount.
       */
      bulkAdvicePreview: null as TouchlessBulkAdvicePreview | null,
      bulkAdviceBusy: false,
      /**
       * Whether this view is narrowed to a sub-organisation, and its name
       * (DOCB-14313). Null until resolved, and null again if the resolution
       * fails — both mean "say nothing", never "claim org-wide".
       */
      subOrgScope: null as TouchlessSubOrgScope | null,
    };
  },

  computed: {
    /**
     * The button exists once the backend has said something about it, and not
     * when the advisor is switched off — a control that can only ever refuse
     * is worse than no control.
     */
    bulkAdviceVisible(): boolean {
      const preview = this.bulkAdvicePreview;
      if (!preview) return false;
      // DOCB-14335. One exception to "a control that can only ever refuse is
      // worse than no control": when the backend named WHY it refuses. On
      // sandbox and prod the advisor was off for weeks and the panel's only
      // reaction was to remove the button, so the question a reader actually
      // has — is this broken, or not set up here? — had no answer on the
      // page. A backend that sends no reason still gets the old behaviour.
      if (this.bulkAdviceUnavailableReason) return true;
      return preview.status !== 'disabled';
    },

    /**
     * Disabled while a run is in flight, not only while the POST is.
     *
     * A second dispatch would be refused per cluster server-side anyway, but it
     * would replace the run this indicator is counting and reset the reader's
     * x/N to 0 for a job already half done.
     */
    bulkAdviceDisabled(): boolean {
      return (
        this.bulkAdviceBusy ||
        this.store.isBulkRunActive ||
        this.bulkAdvicePreview?.advisorEnabled === false ||
        this.bulkAdviceCount <= 0
      );
    },

    /** Only while a run is genuinely being watched — never a standing 0/0. */
    bulkProgressVisible(): boolean {
      return this.store.isBulkRunActive;
    },

    /**
     * "3/8 fertig · 1:18" — measured, never an invented percentage.
     *
     * The elapsed clock rides alongside the counter (DOCB-14327). Measured on
     * dev, a run over six already-analysed clusters really regenerated all six
     * and took eighty seconds, during which the counter moved once every
     * thirteen seconds and nothing else on screen changed. A reader watching
     * "0/6" with no clock cannot tell a job that started eight seconds ago
     * from one that stopped eight minutes ago.
     */
    bulkProgressLabel(): string {
      const counted = this.$t('touchless_bulk_analyze_progress', {
        done: this.store.bulkRunDone,
        total: this.store.bulkRunTotal,
      }) as string;
      const elapsed = this.store.bulkRunElapsedLabel;
      return elapsed ? `${counted} · ${elapsed}` : counted;
    },

    bulkAdviceCount(): number {
      return this.bulkAdvicePreview?.eligibleCount ?? 0;
    },

    /**
     * "Analyse 5 clusters with AI", or "Re-analyse 6 clusters" once every
     * eligible cluster already has an answer (DOCB-14312).
     *
     * The action stays available either way — evidence moves, and asking
     * again is a real thing to want. What it stops doing is describing a
     * re-run as first-time work: on dev the button read "Analyse 6 clusters
     * with AI" after all six had been analysed, and the second click returned
     * cached advice in four seconds while announcing it exactly like the
     * 81-second run it was not.
     *
     * Falls back to the original wording against a backend that does not send
     * the breakdown — a rollback must not turn every button into
     * "Re-analyse 0".
     */
    bulkAdviceLabel(): string {
      if (this.bulkEverythingAnalyzed) {
        return this.$t('touchless_bulk_reanalyze', {
          count: this.bulkAdviceCount,
        }) as string;
      }
      return this.$t('touchless_bulk_analyze', {
        count: this.bulkAdviceCount,
      }) as string;
    },

    /**
     * True only when the backend has SAID that nothing is new.
     *
     * `newCount === 0` with a positive eligible count, never an absence of
     * information: a backend that sends no breakdown leaves this false and
     * the button keeps its original label.
     */
    bulkEverythingAnalyzed(): boolean {
      const preview = this.bulkAdvicePreview;
      if (!preview) return false;
      return (
        typeof preview.newCount === 'number' &&
        preview.newCount === 0 &&
        this.bulkAdviceCount > 0
      );
    },

    /** "2 new clusters to analyse - 4 already analysed". */
    bulkBreakdownLabel(): string {
      const preview = this.bulkAdvicePreview;
      if (
        !preview ||
        typeof preview.newCount !== 'number' ||
        typeof preview.alreadyAnalyzedCount !== 'number'
      ) {
        return '';
      }
      return this.$t('touchless_bulk_analyze_breakdown', {
        fresh: preview.newCount,
        analyzed: preview.alreadyAnalyzedCount,
      }) as string;
    },

    /**
     * The breakdown is only worth the space once something HAS been analysed.
     *
     * On a first-ever run "6 new clusters to analyse - 0 already analysed" is
     * noise beside a button that already says "Analyse 6 clusters".
     */
    bulkBreakdownVisible(): boolean {
      if (this.store.isBulkRunActive) return false;
      const already = this.bulkAdvicePreview?.alreadyAnalyzedCount;
      return (
        typeof already === 'number' && already > 0 && !!this.bulkBreakdownLabel
      );
    },

    /** "Last analysed: 1 Sep 2026, 20:35", in the reader's own timezone. */
    bulkLastAnalyzedLabel(): string {
      const when = formatTouchlessDateTime(
        this.bulkAdvicePreview?.lastAnalyzedAt,
      );
      if (!when) return '';
      return this.$t('touchless_bulk_last_analyzed', { when }) as string;
    },

    bulkLastAnalyzedVisible(): boolean {
      return !this.store.isBulkRunActive && !!this.bulkLastAnalyzedLabel;
    },

    /**
     * Why this environment cannot run an AI analysis at all (DOCB-14335).
     *
     * Two states, told apart because the remedy differs: `no_api_key` is a
     * deployment that was never given a key (Ruiz), `kill_switch` is somebody
     * having deliberately switched a paid feature off. Empty for every other
     * case — including a reason code this client does not know, which must
     * never reach a user as a raw string.
     */
    bulkAdviceUnavailableReason(): string {
      const reason = this.bulkAdvicePreview?.advisorDisabledReason;
      if (reason === 'no_api_key') {
        return this.$t('touchless_bulk_analyze_unavailable_no_key') as string;
      }
      if (reason === 'kill_switch') {
        return this.$t(
          'touchless_bulk_analyze_unavailable_kill_switch',
        ) as string;
      }
      return '';
    },

    /**
     * What the button will do, or why it will not (DOCB-14313).
     *
     * BOTH states are explained. The disabled one always was — a greyed-out
     * control with no explanation reads as a bug — but the active one answered
     * `''`, so the single control on this page that starts a paid,
     * minutes-long job across the whole organisation was also the only one
     * that said nothing about what it starts.
     *
     * The three facts it now carries are the three a reader needs BEFORE
     * pressing it: how many clusters (the backend's own selection, not a tally
     * of what is on screen), roughly how long that takes, and that it reaches
     * the whole organisation regardless of the sub-organisation in the header.
     *
     * Still empty while no preview has landed: a tooltip is worth nothing next
     * to a button that is not there yet.
     */
    bulkAdviceHint(): string {
      const preview = this.bulkAdvicePreview;
      if (!preview) return '';
      // The configured-off reason is the whole story; nothing about counts or
      // durations applies to a run that cannot start.
      if (this.bulkAdviceUnavailableReason) {
        return this.bulkAdviceUnavailableReason;
      }
      // "We could not ask" is not "nothing qualifies" (DOCB-14335). Borrowing
      // the latter's sentence turned a failed request into a statement about
      // this org's clusters — and, with the zeros that envelope carried, into
      // "no cluster affects at least 0 documents".
      if (preview.status === 'unavailable') {
        return this.$t('touchless_bulk_analyze_unavailable') as string;
      }
      if (this.bulkAdviceCount > 0) {
        const hint = this.$t('touchless_bulk_analyze_hint', {
          count: this.bulkAdviceCount,
          min: preview.minAffected,
          seconds: this.bulkAdviceCount * TOUCHLESS_BULK_SECONDS_PER_CLUSTER,
        }) as string;
        // DOCB-14318: a fourth fact, and the one that decides whether the run
        // is worth starting. "6 clusters" reads as six opportunities; on dev
        // three of the six could only ever be fixed by the supplier.
        return this.bulkSplitLabel ? `${hint} ${this.bulkSplitLabel}` : hint;
      }
      return this.$t('touchless_bulk_analyze_none', {
        count: preview.minAffected,
      }) as string;
    },

    /**
     * "6 clusters: 3 fixable in DocBits, 3 supplier action only"
     * (DOCB-14318).
     *
     * Empty against a backend that does not send the two counts — not "0
     * fixable", which would be a claim this client cannot make. Both are
     * checked because the backend sends them together or not at all, and half
     * a split is not a split. The numbers are the BACKEND's, counted over the
     * same selection `eligibleCount` comes from, so the three always add up.
     */
    bulkSplitLabel(): string {
      const preview = this.bulkAdvicePreview;
      if (
        !preview ||
        typeof preview.fixableCount !== 'number' ||
        typeof preview.supplierOnlyCount !== 'number'
      ) {
        return '';
      }
      return this.$t('touchless_bulk_analyze_split', {
        count: this.bulkAdviceCount,
        fixable: preview.fixableCount,
        supplierOnly: preview.supplierOnlyCount,
      }) as string;
    },

    /**
     * The split earns its own line only when the supplier-only group has
     * anything in it. "6 clusters: 6 fixable, 0 supplier action only" is noise
     * beside a button that already says "Analyse 6 clusters".
     */
    bulkSplitVisible(): boolean {
      if (this.store.isBulkRunActive) return false;
      const supplierOnly = this.bulkAdvicePreview?.supplierOnlyCount;
      return (
        typeof supplierOnly === 'number' &&
        supplierOnly > 0 &&
        !!this.bulkSplitLabel
      );
    },

    /**
     * Whether the org-wide scope needs saying out loud (DOCB-14313).
     *
     * Only beside a button that exists, and only when a sub-organisation is
     * genuinely selected AND has a name to print — an unresolved scope says
     * nothing rather than claiming a filter that may or may not be there.
     */
    bulkScopeHintVisible(): boolean {
      return (
        this.bulkAdviceVisible &&
        this.subOrgScope?.scoped === true &&
        !!this.subOrgScope?.name
      );
    },

    bulkScopeHint(): string {
      return this.$t('touchless_bulk_analyze_scope_suborg', {
        name: this.subOrgScope?.name ?? '',
      }) as string;
    },

    /**
     * Drill-down for the fifth tile — the documents with no known cause.
     *
     * A computed rather than a `bucketDrilldown`-style method because there is
     * exactly one of it and it takes no argument.
     */
    undiagnosedDrilldown(): TouchlessDrilldownLocation | null {
      return buildTouchlessDrilldownLocation({
        undiagnosed: true,
        period: this.store.filters.period,
        docType: this.store.filters.doc_type,
        count: this.store.undiagnosedCount,
      });
    },

    /** Tooltip on every drill-down tile. */
    drilldownTitle(): string {
      return this.$t('touchless_kpi_view_documents') as string;
    },

    /**
     * Whether the run's own result list has anything to say (DOCB-14311).
     *
     * Driven by the entries themselves rather than by a phase, so the list
     * appears the moment the 202 names the dispatched clusters and stays after
     * the run has stopped being watched.
     */
    bulkResultsVisible(): boolean {
      return this.store.bulkResultEntries.length > 0;
    },

    /**
     * How much of the window's loss has no supplier behind it (DOCB-14333).
     *
     * Counted off the supplier rows this panel already loaded, so the hint
     * and the table below it can never describe different populations.
     */
    unresolvedSupplierShare(): TouchlessUnresolvedShare {
      return unresolvedSupplierShare(
        this.store.suppliers as unknown as Record<string, unknown>[],
      );
    },

    /** Whether that share is big enough to be a finding of its own. */
    unresolvedSupplierFinding(): boolean {
      return this.unresolvedSupplierShare.isFinding;
    },

    /** Watch source for the completion toast. Null once the run is cleared. */
    bulkRunPhase(): string | null {
      return this.store.bulkRun?.phase ?? null;
    },
  },

  watch: {
    /**
     * The bulk run's ending, announced once (DOCB-14285).
     *
     * A watcher on the store's phase rather than a `notify` call inside the
     * store: the toast belongs to the screen the reader is on, and a store that
     * raised its own would keep firing them for a panel that has been unmounted
     * for ten minutes. The table refresh DOES live in the store, because it is
     * the store's own data either way.
     *
     * `timeout` gets its own wording. "5/8 finished" with no explanation reads
     * as a broken run; the truth is that this tab stopped watching, not that
     * the worker stopped working.
     */
    bulkRunPhase(phase: string | null): void {
      if (phase !== 'done' && phase !== 'timeout' && phase !== 'stalled') {
        return;
      }
      const params = {
        done: this.store.bulkRunDone,
        total: this.store.bulkRunTotal,
      };
      // Kept BEFORE the reset below: the list of what was analysed is the one
      // thing that must outlive the run (DOCB-14311), and `resetBulkAdviceRun`
      // is about to drop the run it is built from.
      this.store.snapshotBulkResults();
      // "Show results" — the toast is where the reader is looking when the run
      // ends, so it is where the way in belongs.
      const showResults = {
        label: this.$t('touchless_bulk_results_show') as string,
        onClick: () => this.scrollToBulkResults(),
      };
      // DOCB-14312. How many of those endings cost nothing, PROVEN by the
      // run's own read-backs rather than predicted at dispatch: `bulk-status`
      // flags a signature cached when the run touched its row while
      // `generated_at` never moved. Only then may the toast say "no new
      // computation" — a run that really did spend 81 seconds on six model
      // calls must never be described that way.
      const cached = this.store.bulkRunCached;
      if (phase === 'done') {
        notify.success(
          (cached > 0
            ? this.$t('touchless_bulk_analyze_finished_cached', {
                ...params,
                cached,
              })
            : this.$t('touchless_bulk_analyze_finished', params)) as string,
          { action: showResults },
        );
      } else {
        // `timeout` and `stalled` share their wording, because they are the
        // same statement: this tab stopped watching at "x of N", and the
        // worker may well still be going (DOCB-14327). What separates them is
        // urgency, not meaning — a run that never moved at all is a warning,
        // a run that ran out of ceiling while making progress is information.
        const notifier = phase === 'stalled' ? notify.warning : notify.info;
        notifier(this.$t('touchless_bulk_analyze_timeout', params) as string, {
          action: showResults,
        });
      }
      // The count is now history; the indicator has nothing left to show and
      // the button has to become clickable again.
      this.store.resetBulkAdviceRun();
      // Final numbers for the rows the run just finished — the affected count
      // and the lift can both have moved while it ran.
      void this.store.refreshBulkResultSummaries();
      void this.refreshBulkAdvicePreview();
    },

    // Reactive gate: on a cold load the preferences arrive after mount, so the
    // page loads the moment access is granted rather than deciding once and
    // staying blank. Deduplicated — a later settings refresh must not refetch.
    accessGranted: {
      immediate: true,
      handler(granted: boolean) {
        if (granted && !this.hasLoaded) {
          this.hasLoaded = true;
          void this.loadDashboard();
        }
      },
    },
  },

  async mounted() {
    await this.ensureSettingsLoaded();
    // DOCB-14328. Put the last run back before anything else settles: the
    // reader who navigated away mid-run and came back should find the list
    // already there, not appear a second after the page has finished drawing.
    // Never awaited into the mount — a slow or missing record must not hold
    // up a panel that has plenty else to show.
    void this.store.restoreBulkRun();
  },

  beforeUnmount() {
    // Leaving the tab (or losing access) unmounts the panel while requests may
    // still be in flight. Opening a fresh generation for every section means
    // those responses cannot commit into a store the user is no longer looking
    // at, and cannot leave loading flags set for the next mount.
    this.store.beginAllGenerations();
    // And the bulk poll is a TIMER, which no generation counter can stop: left
    // alone it would keep reading eight clusters every five seconds for a panel
    // that is gone, forever.
    this.store.resetBulkAdviceRun();
    // The in-memory list goes with the panel. It is not lost: `restoreBulkRun`
    // puts it back on the next mount from the server's record (or this
    // browser's copy), which is the whole of DOCB-14328 — teardown drops the
    // COPY, never the run.
    this.store.clearBulkResults();
  },

  methods: {
    formatPct(value: unknown): string {
      return formatTouchlessPct(value);
    },

    /**
     * Drill-down for a bucket tile, or null when the bucket is empty.
     *
     * The window travels with it, so the list covers the same period the tile
     * counted rather than whatever the dashboard was last left on.
     */
    bucketDrilldown(
      bucket: TouchlessDrilldownBucket,
    ): TouchlessDrilldownLocation | null {
      return buildTouchlessDrilldownLocation({
        bucket,
        period: this.store.filters.period,
        docType: this.store.filters.doc_type,
        count: this.store.bucketCount(bucket),
      });
    },

    /**
     * Single entry point for a full load. The store's loaders reject so that
     * `loadAll` can distinguish a partial outage from a total one; every
     * fire-and-forget call site therefore has to absorb that rejection. The
     * failure is already visible — each section carries its own error flag —
     * so there is nothing left to do with the error here beyond not crashing
     * the app with an unhandled rejection.
     */
    async loadDashboard(): Promise<void> {
      try {
        await this.store.loadAll();
      } catch {
        // Section error flags already drive the UI.
      }
      // After the sections, never before: the preview is an enhancement to a
      // page that has to render without it. It also has to be re-read on every
      // filter change, because the eligible set is window-scoped.
      await this.refreshBulkAdvicePreview();
      // Same enhancement status as the preview: the page renders without it.
      await this.refreshSubOrgScope();
    },

    /**
     * Which sub-organisation the reader is looking at, if any (DOCB-14313).
     *
     * Read from the service that builds the scope of every request on this
     * page, so the sentence beside the button cannot contradict the query
     * string in flight. A failed resolution leaves `null` — the hint then
     * stays off, which is the honest answer: nothing here knows whether the
     * view is narrowed.
     */
    async refreshSubOrgScope(): Promise<void> {
      try {
        this.subOrgScope = await touchlessService.resolveSubOrgScope();
      } catch (error) {
        logger.warn('[Touchless] sub-org scope unresolved', error);
        this.subOrgScope = null;
      }
    },

    /**
     * Re-read how many clusters a bulk click would analyse.
     *
     * The service swallows its own failures into an `unavailable` zero, so
     * this cannot break the page — a preview that does not arrive simply
     * leaves the button disabled.
     */
    async refreshBulkAdvicePreview(): Promise<void> {
      if (!this.checkAccess()) return;
      this.bulkAdvicePreview = await touchlessService.previewBulkAdvice({
        window: touchlessWindowDays(this.store.filters.period),
      });
    },

    /**
     * Start the bulk run.
     *
     * One request. The individual cards keep showing their own per-cluster
     * progress when the reader opens a supplier; nothing here fans out on the
     * client. The count in the toast is the SERVER's, not the label's — if the
     * eligible set moved between the preview and the click, the honest number
     * is the one the worker will actually run.
     */
    async onBulkAnalyze(): Promise<void> {
      if (!this.checkAccess() || this.bulkAdviceBusy) return;
      this.bulkAdviceBusy = true;
      try {
        const result = await touchlessService.generateBulkAdvice({
          window: touchlessWindowDays(this.store.filters.period),
        });
        if (result.outcome === 'running') {
          // The dispatch toast states ONLY what was started (DOCB-14312).
          //
          // It deliberately does not repeat the backend's `already_analyzed`
          // expectation. That number comes from `advice_is_reusable`, which
          // omits the evidence hash the advisor's real cache rule compares,
          // so it is true in strictly more cases than the cache is: measured
          // on dev (02.09.2026) the dispatch reported six reusable clusters
          // and the worker regenerated all six. Putting that beside "started"
          // reads as "this run is free", which is exactly the impression this
          // ticket exists to remove.
          //
          // The cache is named where it can be PROVEN — the completion toast
          // below, from `bulk-status`'s own `cached`.
          notify.success(
            this.$t('touchless_bulk_analyze_started', {
              count: result.dispatched,
            }) as string,
          );
          // From here the store watches the clusters the server named, until
          // every one of them has ended or the ceiling is reached. Handing over
          // the SERVER's list means the x/N the reader watches is the same run
          // the toast just announced. An older backend sends no list; the store
          // then starts nothing and the toast stands on its own, exactly as it
          // did before this feature.
          this.store.startBulkAdviceRun(
            result.signatures,
            result.dispatchedAt,
            Date.now(),
            // DOCB-14327. The server's handle for this run. Every status read
            // carries it, so the answer describes the run in the scope it was
            // dispatched in instead of one rebuilt from this tab's context.
            result.runId,
          );
          // And name them straight away (DOCB-14311): the dispatched clusters
          // are listed while the run goes, not only once it lands.
          this.store.clearBulkResults();
          void this.store.loadBulkClusterSummaries(result.signatures);
        } else if (result.outcome === 'empty') {
          notify.info(this.$t('touchless_bulk_analyze_empty') as string);
        } else {
          notify.error(
            result.message ||
              (this.$t('touchless_advice_unavailable') as string),
          );
        }
      } catch (error) {
        logger.warn('[Touchless] bulk advice dispatch failed', error);
        notify.error(this.$t('touchless_advice_unavailable') as string);
      } finally {
        this.bulkAdviceBusy = false;
        await this.refreshBulkAdvicePreview();
      }
    },

    /** Retry one section from its widget's retry button. */
    async retrySection(section: TouchlessSection): Promise<void> {
      if (!this.checkAccess()) return;
      try {
        if (section === 'summary') await this.store.loadSummary();
        else if (section === 'trend') await this.store.loadTrend();
        else await this.store.loadSuppliers();
      } catch {
        // The section's error flag is already set by the store.
      }
    },

    async onFiltersChange(patch: Partial<TouchlessFilters>): Promise<void> {
      if (!this.checkAccess()) return;
      // A window change moves the eligible set, so the run in flight is no
      // longer a run over what this page now shows. Stop watching rather than
      // count a stale N against a table describing a different period.
      this.store.resetBulkAdviceRun();
      // Same reason for the result list: it describes clusters selected for a
      // window this page no longer shows.
      this.store.clearBulkResults();
      this.store.setFilters(patch);
      await this.loadDashboard();
    },

    async onSupplierSort(payload: {
      sortBy: string;
      descending: boolean;
    }): Promise<void> {
      // Table events can fire after the flag was revoked mid-session; the gate
      // check is a function call, so it costs nothing to ask again here.
      if (!this.checkAccess()) return;
      try {
        await this.store.setSupplierSort(payload.sortBy, payload.descending);
      } catch {
        // suppliersError already drives the table's error state.
      }
    },

    async onSupplierPage(payload: {
      page: number;
      rowsPerPage: number;
    }): Promise<void> {
      if (!this.checkAccess()) return;
      try {
        await this.store.setSupplierPage(payload.page, payload.rowsPerPage);
      } catch {
        // suppliersError already drives the table's error state.
      }
    },

    /**
     * Open the cluster a result row names (DOCB-14311).
     *
     * The supplier's route plus the signature as a query param, so the
     * detail page can expand THAT cluster's card instead of dropping the
     * reader at the top of a list of eight.
     */
    openBulkResult(entry: TouchlessBulkResultEntry): void {
      if (!this.checkAccess()) return;
      if (!entry?.supplierKey) return;
      this.$router.push({
        name: TOUCHLESS_SUPPLIER_ROUTE,
        params: { supplierId: entry.supplierKey },
        query: { issue: entry.signature },
      });
    },

    /**
     * Bring the result list into view from the completion toast.
     *
     * Guarded: `scrollIntoView` does not exist in jsdom, and a toast action
     * that throws would take the notification down with it.
     */
    scrollToBulkResults(): void {
      const target = this.$refs.bulkResults as
        | { $el?: HTMLElement }
        | undefined;
      const element = target?.$el;
      if (!element || typeof element.scrollIntoView !== 'function') return;
      element.scrollIntoView({ behavior: 'smooth', block: 'start' });
      if (typeof element.focus === 'function') element.focus();
    },

    /** Leaves the analytics page for the supplier's own deep-linkable route. */
    /**
     * Where a reader fixes supplier recognition (DOCB-14333).
     *
     * The master-data lookup, which is where a missing supplier is either
     * created or matched. A hint that names a problem and offers no way to it
     * is half a hint.
     */
    openSupplierMasterData(): void {
      void this.$router.push({ path: '/settings/master-data' });
    },

    openSupplier(supplierKey: string): void {
      if (!this.checkAccess()) return;
      if (!supplierKey) return;
      this.$router.push({
        name: TOUCHLESS_SUPPLIER_ROUTE,
        params: { supplierId: supplierKey },
      });
    },
  },
});
</script>

