<template>
  <!--
    What the bulk AI analysis actually produced — DOCB-14311.

    The run used to end in a toast and nothing else: the analyses were real,
    but they sat two clicks away (supplier row → cluster card) and nothing on
    this page said WHICH clusters had been analysed. This list is the missing
    half of the sentence the button starts. It appears the moment the 202 names
    the dispatched signatures — not only at the end — so the reader can watch
    the named clusters land one by one instead of a bare counter.
  -->
  <div
    class="bulk-results q-mb-md"
    data-test="touchless-bulk-results"
    tabindex="-1"
  >
    <div class="bulk-results-head">
      <span class="bulk-results-title" data-test="touchless-bulk-results-title">
        {{ $t('touchless_bulk_results_title', { count: entries.length }) }}
      </span>
      <span class="bulk-results-hint">
        {{ $t('touchless_bulk_results_hint') }}
      </span>

      <!--
        DOCB-14328. The list now outlives the visit that produced it, which
        means it needs a way to be finished with. Deliberately a discard and
        not a delete: the run happened, another tab may still be watching it,
        and this only says "I have read this".
      -->
      <q-btn
        flat
        dense
        no-caps
        size="sm"
        class="bulk-results-dismiss"
        :label="$t('discard')"
        data-test="touchless-bulk-results-dismiss"
        @click="$emit('dismiss')"
      />
    </div>

    <!--
      DOCB-14327. Said once, above the rows, rather than repeated on every
      grey chip: when this tab has given up on a run, the reader needs to know
      what that does and does not mean — the worker may still be going, and
      this tab has simply stopped following it.

      Deliberately the SAME sentence the run's own ending toast carries, from
      the same key. A toast is gone in six seconds; the list is what the
      reader comes back to, and the explanation belongs where the grey rows
      are. Two wordings for one fact would only be one edit away from
      disagreeing.
    -->
    <p
      v-if="hasUnknown"
      class="bulk-results-stalled"
      data-test="touchless-bulk-results-stalled"
    >
      {{ $t('touchless_bulk_analyze_timeout', unknownHintCounts) }}
    </p>

    <!--
      Two headings, not one list (DOCB-14318). Three of the six clusters a dev
      run covered cannot be fixed inside DocBits at all — the supplier has to
      correct the electronic document and send it again — and they sat
      indistinguishably beside the ones that ARE a setting away. A clerk
      working the list top to bottom spent the morning on things they could
      not do. The group is skipped entirely when it is empty: an empty heading
      is a claim about a run that made none.
    -->
    <template v-for="group in groups" :key="group.key">
      <div
        v-if="group.entries.length"
        class="bulk-results-group"
        :data-test="`touchless-bulk-results-group-${group.key}`"
      >
        <span
          class="bulk-results-group-title"
          :data-test="`touchless-bulk-results-group-title-${group.key}`"
        >
          {{ $t(group.labelKey, { count: group.entries.length }) }}
        </span>
      </div>

      <ul v-if="group.entries.length" class="bulk-results-list">
        <li
          v-for="entry in group.entries"
          :key="entry.signature"
          class="bulk-results-row"
          data-test="touchless-bulk-result-row"
          :data-group="group.key"
        >
          <!--
            Status first, because it qualifies everything to its right: an
            affected-document count on a cluster whose analysis errored out is
            not a finding, it is a cluster nobody has an answer for yet. The
            machine-readable `data-status` is what tests and any future filter
            read; the chip label is what the reader reads.
          -->
          <q-chip
            dense
            square
            outline
            :color="statusColor(entry.status)"
            :icon="statusIcon(entry.status)"
            :label="statusLabel(entry.status)"
            class="bulk-results-status"
            data-test="touchless-bulk-result-status"
            :data-status="entry.status"
          />

          <!--
            DOCB-14333. The REASON is the headline and the supplier is the line
            under it, not the other way round. On dev every row of this list was
            headed "unknown" — the raw bucket for a document nobody could
            attribute — with the one actionable thing on the row ("Field
            validation — Field validation failed") demoted beneath it. A row is
            about a problem; whose problem it is qualifies it.
          -->
          <div class="bulk-results-main">
            <span
              class="bulk-results-cluster"
              data-test="touchless-bulk-result-title"
            >
              {{ clusterTitle(entry) }}
            </span>
            <span
              class="bulk-results-supplier"
              data-test="touchless-bulk-result-supplier"
            >
              {{ supplierLabel(entry) }}
            </span>
          </div>

          <span
            class="bulk-results-docs"
            data-test="touchless-bulk-result-docs"
          >
            {{
              $t('touchless_affected_docs', { count: entry.affectedDocCount })
            }}
          </span>
          <span
            class="bulk-results-lift"
            data-test="touchless-bulk-result-lift"
          >
            {{ formatLift(entry.liftPct) }}
          </span>

          <!--
            What of that lift is actually PRESSABLE (DOCB-14325). Shown only when
            the cluster carries an applicable proposal: the whole-cluster lift
            beside it includes causes only a supplier can fix, and a reader who
            reads the two as the same number would go looking for a button that
            was never going to be there.
          -->
          <span
            v-if="entry.applicableLiftPct !== null"
            class="bulk-results-applicable"
            data-test="touchless-bulk-result-applicable-lift"
          >
            {{
              $t('touchless_bulk_result_applicable_lift', {
                lift: formatLift(entry.applicableLiftPct),
              })
            }}
          </span>

          <!--
            The way in. Disabled only when the read that would name the supplier
            has not landed — a row with no supplier key has nowhere to go, and a
            link that silently does nothing is worse than one that says it is not
            ready yet.
          -->
          <q-btn
            flat
            dense
            no-caps
            size="sm"
            color="primary"
            icon="open_in_new"
            :label="$t('touchless_bulk_result_open')"
            :disable="!entry.supplierKey"
            data-test="touchless-bulk-result-open"
            @click="$emit('open', entry)"
          />
        </li>
      </ul>
    </template>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { formatLiftPp } from 'src/utils/touchless-format';
import { isUnresolvedSupplier } from 'src/utils/touchless-supplier';
import { splitBulkResultEntries } from 'src/utils/touchless-fixability';
import type {
  TouchlessBulkResultEntry,
  TouchlessBulkResultStatus,
} from 'src/utils/touchless-bulk-results';

/** Quasar colour per state. Not a severity scale — three different answers. */
const STATUS_COLOR: Record<TouchlessBulkResultStatus, string> = {
  // Waiting its turn: real, and deliberately quieter than the one the model
  // is actually inside (DOCB-14327).
  queued: 'grey-7',
  running: 'primary',
  // A finish that cost nothing. Positive like `done`, because it IS done —
  // the icon and the word carry the difference, not the colour (DOCB-14312).
  cached: 'positive',
  done: 'positive',
  error: 'negative',
  // DOCB-14327. Grey, not red: nothing failed. This tab stopped following
  // the run, and drawing that as an error would accuse a worker that may
  // well still be finishing the job.
  unknown: 'grey',
};

const STATUS_ICON: Record<TouchlessBulkResultStatus, string> = {
  queued: 'schedule',
  running: 'autorenew',
  cached: 'bolt',
  done: 'check',
  error: 'error_outline',
  unknown: 'help_outline',
};

/**
 * The analysed clusters of one bulk run, as a list.
 *
 * Presentational on purpose: it owns no run state, starts no request and knows
 * nothing about the store. The panel hands it rows and receives an `open`
 * back, which keeps the run's lifecycle in exactly one place.
 */
export default defineComponent({
  name: 'BulkAnalysisResults',

  props: {
    entries: {
      type: Array as PropType<TouchlessBulkResultEntry[]>,
      required: true,
    },
  },

  emits: ['open', 'dismiss'],

  computed: {
    /**
     * The rows under their two headings — DOCB-14318.
     *
     * Fixable first, in the order the server ran them: the selection is
     * ordered fixable-first and by leverage inside that, so a list that
     * re-sorted would stop matching the run it describes. The split rule is
     * `touchless-fixability.ts`, which mirrors the backend's own — the
     * button's tooltip states the same two numbers, and two rules would put
     * "3 fixable" over a list showing four.
     */
    groups(): Array<{
      key: 'fixable' | 'supplier-only';
      labelKey: string;
      entries: TouchlessBulkResultEntry[];
    }> {
      const split = splitBulkResultEntries(this.entries);
      return [
        {
          key: 'fixable',
          labelKey: 'touchless_group_fixable',
          entries: split.fixable,
        },
        {
          key: 'supplier-only',
          labelKey: 'touchless_group_supplier_only',
          entries: split.supplierOnly,
        },
      ];
    },

    /** Whether any row is one this tab stopped following (DOCB-14327). */
    hasUnknown(): boolean {
      return this.entries.some((entry) => entry.status === 'unknown');
    },

    /**
     * "x of N", counted from the rows themselves (DOCB-14327).
     *
     * Not read off the run: this list outlives the run it was built from
     * (DOCB-14311), and the rows on screen are the only thing still around to
     * count. `done` and `error` are both endings — a cluster whose analysis
     * failed has been heard back from.
     */
    unknownHintCounts(): { done: number; total: number } {
      return {
        done: this.entries.filter(
          (entry) => entry.status === 'done' || entry.status === 'error',
        ).length,
        total: this.entries.length,
      };
    },
  },

  methods: {
    statusColor(status: TouchlessBulkResultStatus): string {
      return STATUS_COLOR[status] ?? 'grey';
    },

    statusIcon(status: TouchlessBulkResultStatus): string {
      return STATUS_ICON[status] ?? 'help_outline';
    },

    /**
     * The chip's wording.
     *
     * `unknown` (DOCB-14327) borrows the product-wide `unknown` string rather
     * than minting a `touchless_bulk_result_status_unknown` of its own: it is
     * the same word, and while the Tolgee server is unreachable a key that
     * exists everywhere already is one the build can actually resolve.
     */
    statusLabel(status: TouchlessBulkResultStatus): string {
      if (status === 'unknown') return this.$t('unknown') as string;
      return this.$t(`touchless_bulk_result_status_${status}`) as string;
    },

    /**
     * Same fallback rule the cluster card uses: a value this build has no
     * translation for is shown verbatim rather than as a raw key.
     */
    translateEnum(prefix: string, value: string | null | undefined): string {
      if (!value) return '';
      const key = `${prefix}${String(value).toLowerCase()}`;
      const translated = this.$t(key) as string;
      return translated === key ? value : translated;
    },

    /**
     * Whose problem this row is.
     *
     * The supplier's name; the explanatory label with its document count when
     * nobody could attribute the documents (DOCB-14333) — never the raw
     * `unknown` bucket the backend stores in BOTH the key and the name
     * column, which is what every row of this list read on dev; and the
     * loading placeholder only while the cluster read is genuinely still in
     * flight.
     */
    supplierLabel(entry: TouchlessBulkResultEntry): string {
      if (
        entry.supplierName &&
        !isUnresolvedSupplier(entry.supplierKey, entry.supplierName)
      ) {
        return entry.supplierName;
      }
      // Nothing has landed yet: the read is in flight, and this row knows
      // neither a supplier nor that there is none.
      if (!entry.supplierKey && !entry.supplierName) {
        return this.$t('touchless_bulk_result_pending') as string;
      }
      if (isUnresolvedSupplier(entry.supplierKey, entry.supplierName)) {
        return entry.affectedDocCount > 0
          ? (this.$t('touchless_supplier_unidentified_count', {
              count: entry.affectedDocCount,
            }) as string)
          : (this.$t('touchless_supplier_unidentified') as string);
      }
      return entry.supplierKey;
    },

    /**
     * The cluster's headline, built exactly as `IssueClusterCard` builds it —
     * stage and reason, or the reason alone when the loss could not be
     * attributed to a stage. The row and the card it opens must not name the
     * same cluster two different ways.
     */
    clusterTitle(entry: TouchlessBulkResultEntry): string {
      const stage = this.translateEnum('touchless_stage_', entry.stage);
      const reason = this.translateEnum('touchless_reason_', entry.reasonCode);
      if (!stage) return reason;
      return reason ? `${stage} — ${reason}` : stage;
    },

    formatLift(value: number | null): string {
      return formatLiftPp(value);
    },
  },
});
</script>

