<template>
  <TouchlessWidgetWrapper
    :title="$t('touchless_blocking_stages_title')"
    icon="mdi:chart-bar"
    :loading="loading"
    :error="error"
    data-test="touchless-blocking-widget"
    @retry="$emit('retry')"
  >
    <div v-if="hasData" class="chart-container">
      <apexchart
        type="bar"
        :height="chartHeight"
        :options="chartOptions"
        :series="series"
      />
    </div>
    <div v-else class="widget-empty" data-test="touchless-blocking-empty">
      <Icon icon="mdi:chart-bar" width="32" class="text-grey-5" />
      <span class="q-mt-xs text-grey-6 text-caption">
        {{ $t('touchless_no_blocking_stages') }}
      </span>
    </div>
  </TouchlessWidgetWrapper>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import VueApexCharts from 'vue3-apexcharts';
import type { ApexOptions } from 'apexcharts';
import { Icon } from '@iconify/vue';
import TouchlessWidgetWrapper from '../TouchlessWidgetWrapper.vue';
import type { TouchlessBlockingStage } from 'src/services/analytics/TouchlessService';

/**
 * Where touchless is lost first, as a horizontal bar chart sorted by volume.
 * This replaces a funnel: the stages are not strictly sequential per document
 * (a doc can skip po_match entirely), so a funnel would imply a drop-off that
 * does not exist.
 *
 * Stage and reason-code labels are looked up in i18n and fall back to the raw
 * enum value, so a backend that adds a code still renders something truthful.
 */
/** Local series shape — avoids the ambient `ApexAxisChartSeries` global. */
interface TouchlessChartSeries {
  name: string;
  data: number[];
}

export default defineComponent({
  name: 'BlockingStageChart',

  components: {
    apexchart: VueApexCharts,
    Icon,
    TouchlessWidgetWrapper,
  },

  props: {
    stages: {
      type: Array as PropType<TouchlessBlockingStage[]>,
      default: () => [],
    },
    loading: { type: Boolean, default: false },
    error: { type: Boolean, default: false },
  },

  emits: ['retry'],

  computed: {
    /** Descending by count — the biggest loss belongs at the top. */
    sortedStages(): TouchlessBlockingStage[] {
      return [...this.stages].sort((a, b) => (b.count ?? 0) - (a.count ?? 0));
    },

    hasData(): boolean {
      return this.sortedStages.length > 0;
    },

    chartHeight(): number {
      return Math.max(140, this.sortedStages.length * 44 + 60);
    },

    series(): TouchlessChartSeries[] {
      return [
        {
          name: this.$t('touchless_series_blocked_documents') as string,
          data: this.sortedStages.map((stage) => stage.count ?? 0),
        },
      ];
    },

    categories(): string[] {
      return this.sortedStages.map((stage) => this.stageLabel(stage));
    },

    isDark(): boolean {
      return this.$q.dark.isActive;
    },

    chartOptions(): ApexOptions {
      const dark = this.isDark;
      const axisColor = dark ? '#9ca3af' : '#6b7280';
      return {
        chart: { toolbar: { show: false }, background: 'transparent' },
        plotOptions: {
          bar: { horizontal: true, barHeight: '65%', borderRadius: 3 },
        },
        xaxis: {
          categories: this.categories,
          labels: { style: { fontSize: '10px', colors: axisColor } },
        },
        yaxis: {
          labels: { style: { fontSize: '10px', colors: [axisColor] } },
        },
        colors: ['#e91e8a'],
        dataLabels: { enabled: false },
        legend: { show: false },
        grid: {
          strokeDashArray: 3,
          borderColor: dark ? '#374151' : '#e5e7eb',
        },
        tooltip: { theme: dark ? 'dark' : 'light' },
      };
    },
  },

  methods: {
    /** i18n label for a stage, falling back to the raw enum value. */
    translateEnum(prefix: string, value: string): string {
      if (!value) return '';
      const key = `${prefix}${value.toLowerCase()}`;
      const translated = this.$t(key) as string;
      return translated === key ? value : translated;
    },

    /**
     * A bar's label. `stage` is null when the evaluator could not attribute
     * the loss to one — the registry's UNKNOWN outcome — and the bar still
     * belongs on the chart: those documents were lost too, and hiding them
     * would understate the total the user is trying to reduce. The reason code
     * carries the meaning in that case.
     */
    stageLabel(stage: TouchlessBlockingStage): string {
      const stageName = stage.stage
        ? this.translateEnum('touchless_stage_', stage.stage)
        : '';
      const reason = this.translateEnum(
        'touchless_reason_',
        stage.reason_code || '',
      );
      // With no stage the reason IS the label. The guard guarantees a reason
      // code in that case, so there is no third fallback to write.
      if (!stageName) return reason;
      return reason ? `${stageName} — ${reason}` : stageName;
    },
  },
});
</script>

<style lang="scss" scoped>
.chart-container {
  padding: 0 8px 8px;
}
</style>
