<template>
  <div class="service-time-chart" :class="{ 'dark-mode': isDark }">
    <div v-if="!hideTitle" class="text-subtitle2 text-primary q-mb-sm">
      {{ $t('time_trend') }}: {{ serviceLabel }} {{ isMultiService ? `(${$t('combined')})` : '' }}
    </div>
    <apexchart
      :key="isDark ? 'dark' : 'light'"
      type="line"
      :options="chartOptions"
      :series="chartSeries"
      height="200"
    />
  </div>
</template>

<script lang="ts">
import { defineComponent, PropType } from 'vue';
import VueApexCharts from 'vue3-apexcharts';
import { mapState } from 'pinia';
import { useSettingStore } from 'src/store/main';
import { amount_format_setting } from 'src/constants';
import dateUtils from 'src/utils/date';
import { formatAmount } from './analyticsUtils';

export interface ServiceDataPoint {
  date: string;
  min: number;
  avg: number;
  max: number;
}

export interface AggregatedDataPoint extends ServiceDataPoint {
  startDate: string;
  endDate: string;
}

const TARGET_STEPS = 10;

function aggregateDataPoints(data: ServiceDataPoint[]): AggregatedDataPoint[] {
  const totalPoints = data.length;

  if (totalPoints <= TARGET_STEPS) {
    return data.map(d => ({
      ...d,
      startDate: d.date,
      endDate: d.date,
    }));
  }

  const stepSize = Math.ceil(totalPoints / TARGET_STEPS);
  const aggregated: AggregatedDataPoint[] = [];

  for (let i = 0; i < totalPoints; i += stepSize) {
    const chunk = data.slice(i, Math.min(i + stepSize, totalPoints));

    if (chunk.length === 0) continue;

    const minValue = Math.min(...chunk.map(d => d.min));
    const avgValue = chunk.reduce((sum, d) => sum + d.avg, 0) / chunk.length;
    const maxValue = Math.max(...chunk.map(d => d.max));

    aggregated.push({
      date: chunk[Math.floor(chunk.length / 2)].date,
      startDate: chunk[0].date,
      endDate: chunk[chunk.length - 1].date,
      max: maxValue,
      avg: avgValue,
      min: minValue,
    });
  }

  return aggregated;
}

export default defineComponent({
  name: 'ServiceTimeChart',
  components: {
    apexchart: VueApexCharts,
  },
  mixins: [dateUtils],
  props: {
    serviceName: {
      type: String,
      required: true,
    },
    serviceLabel: {
      type: String,
      required: true,
    },
    timeData: {
      type: Array as PropType<ServiceDataPoint[]>,
      default: () => [],
    },
    isMultiService: {
      type: Boolean,
      default: false,
    },
    hideTitle: {
      type: Boolean,
      default: false,
    },
    formatAsCount: {
      type: Boolean,
      default: false,
    },
    groupedSeries: {
      type: Array as PropType<Array<{ name: string; data: Array<{ date: string; avg: number }> }>>,
      default: undefined,
    },
  },
  data() {
    return {
      primaryColor: '#1976D2',
    };
  },
  computed: {
    ...mapState(useSettingStore, ['user_settings']),

    isDark(): boolean {
      return this.$q.dark.isActive;
    },

    textColor(): string {
      return this.isDark ? '#ffffff' : '#373d3f';
    },

    isGroupedMode(): boolean {
      return this.groupedSeries !== undefined && this.groupedSeries.length > 0;
    },

    aggregatedData(): AggregatedDataPoint[] {
      if (this.isGroupedMode) return [];
      return aggregateDataPoints(this.timeData);
    },

    // Aggregate grouped series data to reduce data points
    // Uses null for missing/zero data to create gaps in the chart
    aggregatedGroupedSeries(): Array<{ name: string; data: (number | null)[] }> {
      if (!this.isGroupedMode || !this.groupedSeries) return [];

      // Get all dates from first series (all series have same dates)
      const firstSeries = this.groupedSeries[0];
      if (!firstSeries || firstSeries.data.length === 0) return [];

      const totalPoints = firstSeries.data.length;

      const zeroValue = this.formatAsCount ? 0 : null;

      if (totalPoints <= TARGET_STEPS) {
        return this.groupedSeries.map(series => ({
          name: series.name,
          data: series.data.map(d => d.avg === 0 ? zeroValue : parseFloat(d.avg.toFixed(2)))
        }));
      }

      // Aggregate data points
      const stepSize = Math.ceil(totalPoints / TARGET_STEPS);
      return this.groupedSeries.map(series => {
        const aggregatedData: (number | null)[] = [];
        for (let i = 0; i < totalPoints; i += stepSize) {
          const chunk = series.data.slice(i, Math.min(i + stepSize, totalPoints));
          const hasData = chunk.some(d => d.avg > 0);
          if (!hasData) {
            aggregatedData.push(zeroValue);
          } else {
            const avgValue = chunk.reduce((sum, d) => sum + d.avg, 0) / chunk.length;
            aggregatedData.push(parseFloat(avgValue.toFixed(2)));
          }
        }
        return {
          name: series.name,
          data: aggregatedData
        };
      });
    },

    // Categories (x-axis labels) for grouped mode
    groupedCategories(): string[] {
      return this.groupedAggregatedDateRanges.map(d => this.formatDateLabel(d.date));
    },

    // Aggregated date ranges for grouped mode (similar to aggregatedData for service mode)
    groupedAggregatedDateRanges(): Array<{ date: string; startDate: string; endDate: string }> {
      if (!this.isGroupedMode || !this.groupedSeries) return [];

      const firstSeries = this.groupedSeries[0];
      if (!firstSeries || firstSeries.data.length === 0) return [];

      const totalPoints = firstSeries.data.length;

      if (totalPoints <= TARGET_STEPS) {
        return firstSeries.data.map(d => ({
          date: d.date,
          startDate: d.date,
          endDate: d.date,
        }));
      }

      // Aggregate to get date ranges for each chunk
      const stepSize = Math.ceil(totalPoints / TARGET_STEPS);
      const dateRanges: Array<{ date: string; startDate: string; endDate: string }> = [];
      for (let i = 0; i < totalPoints; i += stepSize) {
        const chunk = firstSeries.data.slice(i, Math.min(i + stepSize, totalPoints));
        const middleIndex = Math.floor(chunk.length / 2);
        dateRanges.push({
          date: chunk[middleIndex].date,
          startDate: chunk[0].date,
          endDate: chunk[chunk.length - 1].date,
        });
      }
      return dateRanges;
    },

    chartSeries(): any[] {
      if (this.isGroupedMode) {
        return this.aggregatedGroupedSeries;
      }
      return [
        {
          name: this.$t('max_time'),
          data: this.aggregatedData.map(d => parseFloat(d.max.toFixed(2))),
        },
        {
          name: this.$t('avg_time'),
          data: this.aggregatedData.map(d => parseFloat(d.avg.toFixed(2))),
        },
        {
          name: this.$t('min_time'),
          data: this.aggregatedData.map(d => parseFloat(d.min.toFixed(2))),
        },
      ];
    },

    groupedColors(): string[] {
      // Generate distinct colors for grouped series
      const seriesCount = this.aggregatedGroupedSeries.length;
      return this.generateColorPalette(this.primaryColor, Math.max(seriesCount, 5));
    },

    chartOptions(): any {
      const baseOptions = {
        chart: {
          type: 'line',
          toolbar: {
            show: false,
          },
          zoom: {
            enabled: false,
          },
        },
        yaxis: {
          min: 0,
          title: {
            text: this.formatAsCount ? this.$t('tests') : this.$t('time'),
            style: {
              fontSize: '11px',
              color: this.textColor,
            },
          },
          labels: {
            formatter: (val: number) => this.formatAsCount ? String(Math.round(val)) : this.formatDuration(val),
            style: {
              fontSize: '10px',
              colors: this.textColor,
            },
          },
        },
        legend: {
          show: true,
          showForSingleSeries: true,
          position: 'top',
          horizontalAlign: 'right',
          fontSize: '11px',
          labels: {
            colors: this.textColor,
          },
        },
        tooltip: {
          shared: true,
          theme: this.isDark ? 'dark' : 'light',
          y: {
            formatter: (val: number | null) => {
              if (val === null || val === undefined) return '-';
              if (val === 0) return this.formatAsCount ? '0' : '-';
              return this.formatAsCount ? String(Math.round(val)) : this.formatDuration(val);
            },
          },
        },
        grid: {
          borderColor: this.isDark ? '#444444' : '#e0e0e0',
          strokeDashArray: 3,
        },
      };

      if (this.isGroupedMode) {
        // Grouped mode - multiple series with different colors, all solid lines
        return {
          ...baseOptions,
          colors: this.groupedColors,
          stroke: {
            curve: 'smooth',
            width: 2,
            dashArray: 0,
          },
          markers: {
            size: 3,
            strokeWidth: 0,
            hover: {
              size: 6,
            },
          },
          xaxis: {
            type: 'category',
            categories: this.groupedCategories,
            labels: {
              style: {
                fontSize: '10px',
                colors: this.textColor,
              },
            },
          },
          tooltip: {
            ...baseOptions.tooltip,
            x: {
              formatter: (_val: string, opts: { dataPointIndex: number }) => {
                const dateRange = this.groupedAggregatedDateRanges[opts.dataPointIndex];
                if (!dateRange) return '';
                const start = this.formatDateLabel(dateRange.startDate);
                const end = this.formatDateLabel(dateRange.endDate);
                return start === end ? start : `${start} - ${end}`;
              },
            },
          },
        };
      }

      // Default min/avg/max mode
      return {
        ...baseOptions,
        colors: [
          this.primaryColor + '66',
          this.primaryColor,
          this.primaryColor + 'CC',
        ],
        stroke: {
          curve: 'smooth',
          width: [1, 3, 1],
          dashArray: [5, 0, 5],
        },
        fill: {
          type: 'solid',
          opacity: [0.3, 0.7, 0.3],
        },
        markers: {
          size: 3,
          strokeWidth: 0,
          hover: {
            size: 6,
          },
        },
        xaxis: {
          type: 'category',
          categories: this.aggregatedData.map(d => this.formatDateLabel(d.date)),
          labels: {
            style: {
              fontSize: '10px',
              colors: this.textColor,
            },
          },
        },
        tooltip: {
          ...baseOptions.tooltip,
          x: {
            formatter: (_val: number, opts: { dataPointIndex: number }) => {
              const dataPoint = this.aggregatedData[opts.dataPointIndex];
              if (!dataPoint) return '';
              const start = this.formatDateLabel(dataPoint.startDate);
              const end = this.formatDateLabel(dataPoint.endDate);
              return start === end ? start : `${start} - ${end}`;
            },
          },
        },
      };
    },
  },
  mounted() {
    const computedStyle = getComputedStyle(document.documentElement);
    const cssColor = computedStyle.getPropertyValue('--primary-color').trim();
    if (/^#[0-9a-fA-F]{6}$/.test(cssColor)) {
      this.primaryColor = cssColor;
    }
  },
  methods: {
    formatAmount(value: number): string {
      const userLocale = this.user_settings[amount_format_setting] || 'en_US';
      return formatAmount(value, userLocale);
    },

    formatDateLabel(dateStr: string): string {
      return this.formatDateAccordingToPreference(dateStr, true, dateStr);
    },

    hexToHsl(hex: string): { h: number; s: number; l: number } {
      hex = hex.replace(/^#/, '');
      const r = parseInt(hex.substring(0, 2), 16) / 255;
      const g = parseInt(hex.substring(2, 4), 16) / 255;
      const b = parseInt(hex.substring(4, 6), 16) / 255;

      const max = Math.max(r, g, b);
      const min = Math.min(r, g, b);
      let h = 0, s = 0;
      const l = (max + min) / 2;

      if (max !== min) {
        const d = max - min;
        s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
        switch (max) {
          case r: h = ((g - b) / d + (g < b ? 6 : 0)) / 6; break;
          case g: h = ((b - r) / d + 2) / 6; break;
          case b: h = ((r - g) / d + 4) / 6; break;
        }
      }
      return { h: h * 360, s: s * 100, l: l * 100 };
    },

    hslToHex(h: number, s: number, l: number): string {
      s /= 100;
      l /= 100;
      const a = s * Math.min(l, 1 - l);
      const f = (n: number) => {
        const k = (n + h / 30) % 12;
        const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
        return Math.round(255 * color).toString(16).padStart(2, '0');
      };
      return `#${f(0)}${f(8)}${f(4)}`;
    },

    generateColorPalette(baseColor: string, count: number): string[] {
      const { h, s } = this.hexToHsl(baseColor);
      const colors: string[] = [];
      // Use different hues for better distinction between series
      for (let i = 0; i < count; i++) {
        const hue = (h + (i * 360 / count)) % 360;
        colors.push(this.hslToHex(hue, s, 50));
      }
      return colors;
    },
  },
});
</script>

<style scoped>
.service-time-chart {
  width: 100%;
  padding: 16px;
  border-radius: 8px;
  background: white;
}

.service-time-chart.dark-mode {
  background: var(--q-dark);
}
</style>