/**
 * Utility functions for Analytics Dashboard components
 */

import amountConversionHelper from 'src/utils/amountConversionHelper';

type TranslateFunction = (key: string) => string;

// Cache for normalizeServiceName to avoid redundant string operations
// Capped at 500 entries to prevent unbounded memory growth
const CACHE_MAX_SIZE = 500;
const normalizeCache = new Map<string, string>();

/**
 * Normalizes a service name to uppercase with underscores.
 * This is the canonical format used throughout the analytics dashboard.
 * Results are cached for performance.
 *
 * @param service - The service name to normalize
 * @returns Normalized service name (uppercase, spaces replaced with underscores)
 */
export function normalizeServiceName(service: string): string {
  let cached = normalizeCache.get(service);
  if (cached !== undefined) {
    return cached;
  }
  cached = service.toUpperCase().replace(/\s+/g, '_');
  if (normalizeCache.size >= CACHE_MAX_SIZE) normalizeCache.clear();
  normalizeCache.set(service, cached);
  return cached;
}

// Cache for parseDurationToSeconds to avoid re-parsing the same strings
const durationCache = new Map<string, number>();

/**
 * Parses a formatted duration string back to seconds for comparison.
 * Results are cached for performance since the same duration strings
 * are often parsed repeatedly during rendering.
 *
 * Format examples: "0s", "45s", "2m 30s", "1h 15m", "2d 5h"
 *
 * @param duration - The formatted duration string to parse
 * @returns The duration in seconds
 */
export function parseDurationToSeconds(duration: string | null | undefined): number {
  if (!duration || duration === '-') return 0;

  const cached = durationCache.get(duration);
  if (cached !== undefined) {
    return cached;
  }

  let totalSeconds = 0;

  // Match days
  const daysMatch = duration.match(/(\d+)d/);
  if (daysMatch) {
    totalSeconds += parseInt(daysMatch[1], 10) * 86400;
  }

  // Match hours
  const hoursMatch = duration.match(/(\d+)h/);
  if (hoursMatch) {
    totalSeconds += parseInt(hoursMatch[1], 10) * 3600;
  }

  // Match minutes
  const minutesMatch = duration.match(/(\d+)m(?!s)/); // m but not ms
  if (minutesMatch) {
    totalSeconds += parseInt(minutesMatch[1], 10) * 60;
  }

  // Match seconds
  const secondsMatch = duration.match(/(\d+)s/);
  if (secondsMatch) {
    totalSeconds += parseInt(secondsMatch[1], 10);
  }

  if (durationCache.size >= CACHE_MAX_SIZE) durationCache.clear();
  durationCache.set(duration, totalSeconds);
  return totalSeconds;
}

/**
 * Computes the color class for avg time based on comparison with system average.
 * Green if lower or matching average, Orange if higher, Red if 25%+ slower.
 *
 * @param avgTimeRaw - Raw average time in seconds (or formatted string if raw not available)
 * @param systemAvgRaw - Raw system average in seconds (or formatted string if raw not available)
 * @param showDocbitsAverage - Whether the docbits average comparison is enabled
 * @returns CSS class name for the color styling
 */
export function computeAvgTimeColorClass(
  avgTimeRaw: number | string | null | undefined,
  systemAvgRaw: number | string | null | undefined,
  showDocbitsAverage: boolean
): string {
  if (!showDocbitsAverage || systemAvgRaw === undefined || systemAvgRaw === null) {
    return '';
  }

  // Use raw values if numbers, otherwise parse strings
  const avgSeconds = typeof avgTimeRaw === 'number' ? avgTimeRaw : parseDurationToSeconds(avgTimeRaw as string);
  const systemSeconds = typeof systemAvgRaw === 'number' ? systemAvgRaw : parseDurationToSeconds(systemAvgRaw as string);

  // 25% threshold for "critical" slowdown
  const criticalThreshold = systemSeconds * 1.25;

  if (avgSeconds >= criticalThreshold) {
    return 'avg-worse'; // Red - 25%+ slower than average
  } else if (avgSeconds > systemSeconds) {
    return 'avg-match'; // Orange - higher than average but less than 25%
  }
  return 'avg-better'; // Green - lower or matching average
}

/**
 * Formats a service label for display in analytics charts and cards.
 * Handles STATUS_ prefixed services by stripping the prefix and translating the remainder.
 *
 * @param service - The service name to format
 * @param t - Translation function (Vue i18n $t)
 * @returns Formatted and translated service label
 */
export function formatServiceLabel(
  service: string,
  t: TranslateFunction
): string {
  // Handle composite keys with occurrence suffix (e.g., "STATUS_READY_FOR_VALIDATION::2")
  let occurrence = 0;
  let baseName = service;
  const compositeMatch = service.match(/^(.+)::(\d+)$/);
  if (compositeMatch) {
    baseName = compositeMatch[1];
    occurrence = parseInt(compositeMatch[2], 10);
  }

  const normalizedName = normalizeServiceName(baseName);

  // Strip the STATUS_ prefix — the surrounding UI already conveys that these are statuses
  const translationKey = normalizedName.startsWith('STATUS_')
    ? normalizedName.substring(7)
    : normalizedName;

  const translatedLabel = String(t(translationKey.toLowerCase()));
  const label = translatedLabel.replace(/(?:^|\s)\S/gu, (char) => char.toUpperCase());
  return occurrence >= 2 ? `${occurrence}. ${label}` : label;
}

const DEFAULT_DOCFLOW_ICON = '/images/docflow/field_extraction.svg';
const VALID_DOCFLOW_ICON_NAME = /^[a-z0-9_-]+$/i;

/**
 * Resolves the icon path for a Document Flow service / status name.
 * Centralized so the flow cards and the analytics table stay in sync.
 *
 * Handles:
 *  - composite-key occurrence suffix (e.g. `STATUS_EXPORT_ERROR::2`)
 *  - `STATUS_` prefix stripping
 *  - keyword-based icon mapping for shared categories (waiting, user, approval, pending, validation, error)
 *  - fallback to `<name>.svg` (the caller must handle 404 with `onIconError`)
 *  - invalid characters → DEFAULT_DOCFLOW_ICON
 */
export function resolveDocFlowIcon(name: string | null | undefined): string {
  if (!name || typeof name !== 'string') {
    return DEFAULT_DOCFLOW_ICON;
  }

  // Strip composite-key occurrence suffix like "::2"
  let normalized = name.toUpperCase().replace(/::\d+$/, '');

  // Strip STATUS_ prefix
  if (normalized.startsWith('STATUS_')) {
    normalized = normalized.substring(7);
  }

  normalized = normalized.trim();
  if (!VALID_DOCFLOW_ICON_NAME.test(normalized)) {
    return DEFAULT_DOCFLOW_ICON;
  }

  if (normalized.endsWith('WAITING')) {
    return '/images/docflow/docbits-loading-orbit.svg';
  }
  if (normalized.startsWith('USER')) {
    return '/images/docflow/user.svg';
  }
  if (normalized.includes('APPROVAL')) {
    return '/images/docflow/approval.svg';
  }
  if (normalized.includes('PENDING')) {
    return '/images/docflow/pending.svg';
  }
  if (normalized.includes('VALIDATI')) {
    return '/images/docflow/po_matching.svg';
  }
  if (normalized.includes('ERROR')) {
    return '/images/docflow/error.svg';
  }

  return `/images/docflow/${encodeURIComponent(normalized.toLowerCase())}.svg`;
}

/**
 * Comparator for flow cards / aggregated stats.
 *
 * Sorts by occurrence first (round 1, then round 2, etc.), then by the caller-provided
 * order index within each round. This produces an interleaved ordering that follows the
 * natural flow:
 *   Running, Validation, 2. Running, 2. Validation, 3. Running, 3. Validation
 * rather than grouping all occurrences of one status before moving on:
 *   Running, 2. Running, 3. Running, Validation, 2. Validation, 3. Validation
 *
 * @param a - First entry with `service` name and `occurrence` (defaults to 1 if falsy)
 * @param b - Second entry, same shape as `a`
 * @param getOrder - Returns the order index for a (normalized) service name; entries with
 *   lower indices sort earlier within the same occurrence round.
 */
export function compareFlowCards(
  a: { service: string; occurrence?: number },
  b: { service: string; occurrence?: number },
  getOrder: (service: string) => number,
): number {
  const occurrenceDiff = (a.occurrence || 1) - (b.occurrence || 1);
  if (occurrenceDiff !== 0) return occurrenceDiff;
  return getOrder(normalizeServiceName(a.service)) - getOrder(normalizeServiceName(b.service));
}

/**
 * Formats a numeric value as a localized amount string.
 *
 * @param value - The numeric value to format
 * @param userLocale - The user's locale setting (e.g., 'en_US', 'de_DE')
 * @returns Formatted amount string
 */
export function formatAmount(value: number, userLocale = 'en_US'): string {
  const safeValue = typeof value === 'number' && !Number.isNaN(value) ? value : 0;
  return amountConversionHelper.methods.convertPOValuePerLocale(userLocale, safeValue.toFixed(2));
}

/**
 * Clears all module-level caches. Call on component unmount to free memory.
 */
export function clearCaches(): void {
  normalizeCache.clear();
  durationCache.clear();
}