<template>
  <TouchlessWidgetWrapper
    :title="$t('touchless_trend_title')"
    icon="mdi:chart-line"
    :loading="loading"
    :error="error"
    data-test="touchless-trend-widget"
    @retry="$emit('retry')"
  >
    <div v-if="hasData" class="chart-container">
      <apexchart
        type="line"
        height="260"
        :options="chartOptions"
        :series="series"
      />
    </div>
    <div v-else class="widget-empty" data-test="touchless-trend-empty">
      <Icon icon="mdi:chart-line" width="32" class="text-grey-5" />
      <span class="q-mt-xs text-grey-6 text-caption">
        {{ $t('no_trend_data') }}
      </span>
    </div>
  </TouchlessWidgetWrapper>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import VueApexCharts from 'vue3-apexcharts';
import type { ApexOptions } from 'apexcharts';
import { Icon } from '@iconify/vue';
import TouchlessWidgetWrapper from '../TouchlessWidgetWrapper.vue';
import type { TouchlessTrendPoint } from 'src/services/analytics/TouchlessService';

/**
 * Pure vs AP touchless rate over time, with the org target drawn as a
 * horizontal annotation so "are we above the line" is answerable at a glance.
 * Chart options are computed on `$q.dark.isActive` (pattern: DocNet
 * `IssueTrend.vue`) so a theme switch repaints axes and grid.
 */
/** Local series shape — avoids the ambient `ApexAxisChartSeries` global. */
interface TouchlessChartSeries {
  name: string;
  data: number[];
}

export default defineComponent({
  name: 'TouchlessTrendChart',

  components: {
    apexchart: VueApexCharts,
    Icon,
    TouchlessWidgetWrapper,
  },

  props: {
    points: {
      type: Array as PropType<TouchlessTrendPoint[]>,
      default: () => [],
    },
    target: { type: Number, default: 70 },
    loading: { type: Boolean, default: false },
    error: { type: Boolean, default: false },
  },

  emits: ['retry'],

  computed: {
    hasData(): boolean {
      return Array.isArray(this.points) && this.points.length > 0;
    },

    series(): TouchlessChartSeries[] {
      return [
        {
          name: this.$t('touchless_series_pure') as string,
          // null, NOT 0: ApexCharts draws a gap for null and a plunge to the
          // axis for 0. A day with nothing exported yet did not have a 0 %
          // touchless rate — it had no rate, and drawing a cliff there invents
          // a collapse that never happened.
          data: this.points.map((point) => point.pure_pct ?? null),
        },
        {
          name: this.$t('touchless_series_ap') as string,
          // Same reason as pure_pct above: a gap, not a plunge.
          data: this.points.map((point) => point.ap_pct ?? null),
        },
      ];
    },

    isDark(): boolean {
      return this.$q.dark.isActive;
    },

    chartOptions(): ApexOptions {
      const dark = this.isDark;
      const axisColor = dark ? '#9ca3af' : '#6b7280';
      return {
        chart: { toolbar: { show: false }, background: 'transparent' },
        xaxis: {
          categories: this.points.map((point) => point.date),
          labels: { style: { fontSize: '10px', colors: axisColor } },
        },
        yaxis: {
          min: 0,
          max: 100,
          labels: {
            style: { fontSize: '10px', colors: [axisColor] },
            formatter: (value: number) => `${Math.round(value)}%`,
          },
        },
        annotations: {
          yaxis: [
            {
              y: this.target,
              borderColor: '#f59e0b',
              strokeDashArray: 4,
              label: {
                text: this.$t('touchless_target_label', {
                  target: this.target,
                }) as string,
                position: 'left',
                textAnchor: 'start',
                style: {
                  background: '#f59e0b',
                  color: '#fff',
                  fontSize: '10px',
                },
              },
            },
          ],
        },
        stroke: { curve: 'smooth' as const, width: 2 },
        colors: ['#e91e8a', '#3b82f6'],
        dataLabels: { enabled: false },
        legend: { labels: { colors: axisColor } },
        grid: {
          strokeDashArray: 3,
          borderColor: dark ? '#374151' : '#e5e7eb',
        },
        tooltip: { theme: dark ? 'dark' : 'light' },
      };
    },
  },
});
</script>

<style lang="scss" scoped>
.chart-container {
  padding: 0 8px 8px;
}
</style>
