<template>
  <q-btn-toggle
    v-model="selected_time"
    toggle-color="primary"
    class="toggle_time dashboard-text-color back-white"
    :ripple="false"
    :options="time_options"
    @update:model-value="TimeFilterSelected()"
    @click="onToggleClick()"
  />

  <q-menu
    v-model="open_date_picker"
    no-parent-event
    anchor="bottom right"
    self="top right"
    @before-show="isCustomSelected()"
  >
    <div class="q-pa-md">
      <q-date
        v-model="custom_date_range"
        minimal
        range
        :options="dateOptions"
      >
        <div class="row items-center justify-end q-gutter-sm">
          <f-btn
            v-close-popup
            class="q-mr-sm mt-10 float-right q-mb-md text-uppercase"
            :label="$t('apply')"
            :disable="isApplyDisabled"
            @click="triggerApplyFilters()"
          />
        </div>
      </q-date>
    </div>
  </q-menu>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent } from 'vue';
import { mapState } from 'pinia';
import { useDashboardStore } from 'src/store/main';
export default defineComponent({
    data() {
    return {
      open_date_picker: false,
      selected_time: 'last_90_days',
      time_options: [] as any[],
      custom_date_range: null as { from: string; to: string } | string | null,
      start_date: '',
      end_date: '',
    };
  },
  computed: {
    ...mapState(useDashboardStore, ['quickFilterMap', 'tempFilterMap']),

    isApplyDisabled(): boolean {
      // Disable if no date range is set
      if (!this.tempFilterMap.has('date_range')) {
        return true;
      }

      // Check if there's a date range and validate it
      const dateRangeStr = this.tempFilterMap.get('date_range');

      // Validate dateRangeStr is a non-empty string
      if (typeof dateRangeStr !== 'string' || !dateRangeStr.trim()) {
        return true;
      }

      // Ensure it contains the expected delimiter
      if (!dateRangeStr.includes(' To ')) {
        return true;
      }

      const dates = dateRangeStr.split(' To ');

      // Must split into exactly two parts
      if (dates.length !== 2) {
        return true;
      }

      const [startStr, endStr] = dates;

      // Ensure parts are not placeholder tokens and are non-empty
      if (!startStr || !endStr || startStr === '?' || endStr === '?') {
        return true;
      }

      // Parse dates robustly using Date.parse and check for validity
      const startTimestamp = Date.parse(startStr);
      const endTimestamp = Date.parse(endStr);

      // If either date failed to parse, disable apply
      if (isNaN(startTimestamp) || isNaN(endTimestamp)) {
        return true;
      }

      // Disable if start date is after end date
      if (startTimestamp > endTimestamp) {
        return true;
      }

      return false;
    },
  },
  watch: {
    quickFilterMap: {
      deep: true,
      handler(newVal, oldVal) {
        this.loadFilters();
      },
    },
    custom_date_range: {
      deep: true,
      handler(newVal) {
        this.onCustomDateRangeChanged(newVal);
      },
    },
  },
  mounted() {
    this.setTimeOptions();
    this.loadFilters();
  },
  methods: {
    isCustomSelected() {
      if (this.selected_time != 'custom') {
        this.open_date_picker = false;
      }
    },

    loadFilters() {
      if (this.quickFilterMap.has('date_range')) {
        this.selected_time = 'custom';
        return;
      }
      const selected_time = this.quickFilterMap.get('filter');

      if (!selected_time || !selected_time.hasOwnProperty('value')) {
        this.resetFilters();
        return;
      }
      this.selected_time = selected_time.value;
    },

    resetFilters() {
      this.selected_time = 'last_90_days';
    },

    onToggleClick() {
      // If custom is already selected, reopen the date picker on any click
      // (the click fires before model-value update, so we check current state)
      if (this.selected_time === 'custom' && !this.open_date_picker) {
        this.open_date_picker = true;
      }
    },

    dateOptions(date: string): boolean {
      const today = new Date();
      today.setHours(23, 59, 59, 999); // end of today (local)
      const [y, m, d] = date.split('/').map(Number);
       const checkDate = new Date(y, (m ?? 1) - 1, d ?? 1);
      return checkDate <= today;
    },

    onCustomDateRangeChanged(newVal: any) {
      if (!newVal) {
        this.tempFilterMap.delete('date_range');
        this.start_date = '';
        this.end_date = '';
        return;
      }

      let startDateStr: string | null = null;
      let endDateStr: string | null = null;

      // q-date range returns { from: 'YYYY/MM/DD', to: 'YYYY/MM/DD' } or a single date string
      if (typeof newVal === 'object' && newVal.from && newVal.to) {
        startDateStr = newVal.from.replace(/\//g, '-');
        endDateStr = newVal.to.replace(/\//g, '-');
      } else if (typeof newVal === 'string') {
        // Single date selected
        startDateStr = newVal.replace(/\//g, '-');
        endDateStr = startDateStr;
      }

      if (startDateStr && endDateStr) {
        // Store the dates for emitting
        this.start_date = startDateStr;
        this.end_date = endDateStr;

        // Build date range string in format: 'YYYY-MM-DD To YYYY-MM-DD'
        const dateRange = `${startDateStr} To ${endDateStr}`;
        this.tempFilterMap.set('date_range', dateRange);
      }
    },

    TimeFilterSelected() {
      if (this.selected_time === 'custom') {
        // Open the date picker when custom is first selected
        this.open_date_picker = true;
        return;
      }

      if (this.selected_time == 'last_180_days' || this.selected_time == 'last_365_days') {
        notify.warning(this.$t('may_increase_loading_time'), { duration: 5000 });
      }

      if (this.open_date_picker && this.selected_time != 'custom') {
        this.tempFilterMap.delete('date_range');
        this.quickFilterMap.delete('date_range');
        this.open_date_picker = false;
        this.custom_date_range = null;
      }
      this.quickFilterMap.set('filter', {
        value: this.selected_time,
        label: this.selected_time,
      });
      this.tempFilterMap.set('filter', {
        value: this.selected_time,
        label: this.selected_time,
      });
      this.emitTimeChange();
      this.triggerApplyFilters();
    },

    emitTimeChange() {
      const today = new Date();
      const todayStr = today.toISOString().split('T')[0];

      // Mapping from preset to number of days to subtract from today
      const timeMapping: Record<string, number> = {
        'last_7_days': 7,
        'last_30_days': 30,
        'last_90_days': 90,
        'last_180_days': 180,
        'last_365_days': 365,
      };

      let startDateStr: string;
      let endDateStr: string;

      if (this.selected_time === 'custom') {
        // Use the stored custom dates
        if (!this.start_date || !this.end_date) {
            return;
         }
        startDateStr = this.start_date;
        endDateStr = this.end_date;
      } else {
        // Calculate start date based on preset
        const days = timeMapping[this.selected_time];
        if (typeof days !== 'number' || !Number.isFinite(days)) {
          this.resetFilters();
          return;
        }
        const startDate = new Date(today);
        startDate.setDate(startDate.getDate() - days);
        startDateStr = startDate.toISOString().split('T')[0];
        endDateStr = todayStr;

        // Store for consistency
        this.start_date = startDateStr;
        this.end_date = endDateStr;
      }

      this.$emit('time-changed', { start_date: startDateStr, end_date: endDateStr });
    },

    triggerApplyFilters() {
      if (this.tempFilterMap.has('date_range')) {
        this.quickFilterMap.set('date_range', this.tempFilterMap.get('date_range'));
      }
      if (this.quickFilterMap.has('date_range')) {
        this.quickFilterMap.delete('filter');
        this.selected_time = 'custom';
        this.emitTimeChange();
      }
      const event = new CustomEvent('apply_filters', { detail: {} });
      document.dispatchEvent(event);
    },

    setTimeOptions() {
      this.time_options = [
        { label: this.$t('7_days'), value: 'last_7_days' },
        { label: this.$t('30_days'), value: 'last_30_days' },
        { label: this.$t('3_months'), value: 'last_90_days' },
        { label: this.$t('6_months'), value: 'last_180_days' },
        { label: this.$t('year'), value: 'last_365_days' },
        { label: this.$t('custom'), value: 'custom' },
      ];
    },
  },
});
</script>

